// Behavioral test for compat.abseil.
//
// Every assertion below crosses into a COMPILED Abseil translation unit, on
// purpose — header-only usage would link zero objects from the package and
// still go green, which is exactly the failure this suite has to catch:
//
//   absl::StrCat / StrSplit / StrJoin  -> absl/strings/*.cc
//   absl::Status / StatusOr            -> absl/status/status.cc, statusor.cc
//   absl::Mutex / Notification         -> absl/synchronization/mutex.cc
//   absl::Cord                         -> absl/strings/cord.cc + cord_rep_*.cc
//   absl::FormatTime / ParseTime       -> absl/time/*.cc + internal/cctz/src/*.cc
//   absl::flat_hash_map                -> absl/container/internal/raw_hash_set.cc
//   absl::StrFormat                    -> absl/strings/internal/str_format/*.cc
//
// Returns non-zero on any mismatch.
#include <string>
#include <thread>
#include <vector>

#include "absl/container/flat_hash_map.h"
#include "absl/status/status.h"
#include "absl/status/statusor.h"
#include "absl/strings/cord.h"
#include "absl/strings/str_cat.h"
#include "absl/strings/str_format.h"
#include "absl/strings/str_join.h"
#include "absl/strings/str_split.h"
#include "absl/synchronization/mutex.h"
#include "absl/synchronization/notification.h"
#include "absl/time/civil_time.h"
#include "absl/time/time.h"

namespace {

bool strings_ok() {
    if (absl::StrCat("answer=", 42, "/", 1.5) != "answer=42/1.5") return false;
    if (absl::StrFormat("%s:%04d:%#x", "id", 7, 255) != "id:0007:0xff") return false;

    const std::vector<std::string> parts = absl::StrSplit("a,b,,c", ',');
    if (parts.size() != 4 || parts[2] != "") return false;
    if (absl::StrJoin(parts, "|") != "a|b||c") return false;
    return true;
}

bool cord_ok() {
    // Build a Cord large enough to leave the inline representation and go
    // through the btree reps in absl/strings/internal/cord_rep_btree*.cc.
    absl::Cord cord;
    for (int i = 0; i < 512; ++i) cord.Append(absl::StrCat("chunk", i, ";"));
    const std::string flat(cord);
    return cord.size() == flat.size() && flat.rfind("chunk511;") != std::string::npos;
}

bool status_ok() {
    const absl::Status ok = absl::OkStatus();
    const absl::Status err = absl::InvalidArgumentError("bad input");
    if (!ok.ok() || err.ok()) return false;
    if (err.code() != absl::StatusCode::kInvalidArgument) return false;
    if (err.message() != "bad input") return false;
    // ToString() formats through absl/status/status.cc.
    if (err.ToString().find("INVALID_ARGUMENT") == std::string::npos) return false;

    const absl::StatusOr<int> good = 11;
    const absl::StatusOr<int> bad = absl::NotFoundError("missing");
    return good.ok() && *good == 11 && !bad.ok();
}

bool time_ok() {
    // A fixed instant, formatted in UTC: exercises the vendored cctz sources.
    const absl::TimeZone utc = absl::UTCTimeZone();
    const absl::Time t = absl::FromCivil(absl::CivilSecond(2026, 8, 4, 12, 34, 56), utc);
    if (absl::FormatTime("%Y-%m-%dT%H:%M:%S", t, utc) != "2026-08-04T12:34:56") return false;

    absl::Time parsed;
    std::string err;
    if (!absl::ParseTime("%Y-%m-%d", "2026-08-04", utc, &parsed, &err)) return false;
    return absl::ToUnixSeconds(t) - absl::ToUnixSeconds(parsed) == 12 * 3600 + 34 * 60 + 56;
}

bool concurrency_ok() {
    // absl::Mutex + Notification pull in the real synchronization objects
    // (mutex.cc, waiter backends, thread identity).
    absl::Mutex mu;
    int counter = 0;
    absl::Notification started;

    std::thread worker([&] {
        started.WaitForNotification();
        for (int i = 0; i < 1000; ++i) {
            absl::MutexLock lock(&mu);
            ++counter;
        }
    });

    started.Notify();
    for (int i = 0; i < 1000; ++i) {
        absl::MutexLock lock(&mu);
        ++counter;
    }
    worker.join();

    absl::MutexLock lock(&mu);
    return counter == 2000;
}

bool container_ok() {
    absl::flat_hash_map<std::string, int> m;
    for (int i = 0; i < 256; ++i) m.emplace(absl::StrCat("k", i), i);
    if (m.size() != 256) return false;
    const auto it = m.find("k255");
    return it != m.end() && it->second == 255;
}

}  // namespace

int main() {
    const bool ok = strings_ok() && cord_ok() && status_ok() && time_ok()
                    && concurrency_ok() && container_ok();
    return ok ? 0 : 1;
}

// Round-trip compress→decompress per codec, asserting byte-for-byte recovery.
#include <bzlib.h>
#include <lz4.h>
#include <lzma.h>
#include <zlib.h>
#include <zstd.h>
#include <cstdint>
#include <cstring>
#include <limits>
#include <vector>

static bool same_bytes(const void* a, size_t an, const void* b, size_t bn) {
    return an == bn && std::memcmp(a, b, bn) == 0;
}

int main() {
    const uint8_t input[] = "mcpp compat compression smoke";
    const size_t input_size = sizeof(input) - 1;

    uint8_t zc[256] = {}; uLongf zcs = sizeof(zc);
    if (compress2(zc, &zcs, input, (uLong)input_size, Z_BEST_SPEED) != Z_OK) return 1;
    uint8_t zo[sizeof(input)] = {}; uLongf zos = input_size;
    if (uncompress(zo, &zos, zc, zcs) != Z_OK || !same_bytes(zo, zos, input, input_size)) return 2;

    char bc[256] = {}; unsigned int bcs = sizeof(bc);
    if (BZ2_bzBuffToBuffCompress(bc, &bcs, const_cast<char*>(reinterpret_cast<const char*>(input)),
                                 (unsigned)input_size, 1, 0, 30) != BZ_OK) return 3;
    char bo[sizeof(input)] = {}; unsigned int bos = input_size;
    if (BZ2_bzBuffToBuffDecompress(bo, &bos, bc, bcs, 0, 0) != BZ_OK ||
        !same_bytes(bo, bos, input, input_size)) return 4;

    char lc[256] = {};
    const int lcs = LZ4_compress_default(reinterpret_cast<const char*>(input), lc, (int)input_size, sizeof(lc));
    if (lcs <= 0) return 5;
    char lo[sizeof(input)] = {};
    const int los = LZ4_decompress_safe(lc, lo, lcs, sizeof(lo));
    if (los < 0 || !same_bytes(lo, (size_t)los, input, input_size)) return 6;

    std::vector<char> sc(ZSTD_compressBound(input_size));
    const size_t scs = ZSTD_compress(sc.data(), sc.size(), input, input_size, 1);
    if (ZSTD_isError(scs)) return 7;
    std::vector<char> so(input_size);
    const size_t sos = ZSTD_decompress(so.data(), so.size(), sc.data(), scs);
    if (ZSTD_isError(sos) || !same_bytes(so.data(), sos, input, input_size)) return 8;

    std::vector<uint8_t> xc(lzma_stream_buffer_bound(input_size)); size_t xcp = 0;
    if (lzma_easy_buffer_encode(0, LZMA_CHECK_CRC64, nullptr, input, input_size,
                                xc.data(), &xcp, xc.size()) != LZMA_OK) return 9;
    uint64_t xm = (std::numeric_limits<uint64_t>::max)(); size_t xip = 0, xop = 0;
    std::vector<uint8_t> xo(input_size);
    if (lzma_stream_buffer_decode(&xm, 0, nullptr, xc.data(), &xip, xcp, xo.data(), &xop, xo.size()) != LZMA_OK ||
        !same_bytes(xo.data(), xop, input, input_size)) return 10;
    return 0;
}

// libarchive object lifecycle + version probes across all codecs.
#include <archive.h>
#include <archive_entry.h>
#include <bzlib.h>
#include <lz4.h>
#include <lzma.h>
#include <zlib.h>
#include <zstd.h>

int main() {
    archive* writer = archive_write_new();
    if (!writer) return 1;
    archive_write_free(writer);
    archive_entry* entry = archive_entry_new();
    if (!entry) return 2;
    archive_entry_free(entry);
    if (!archive_version_string()) return 3;
    if (!zlibVersion()) return 4;
    if (!BZ2_bzlibVersion()) return 5;
    if (LZ4_versionNumber() <= 0) return 6;
    if (ZSTD_versionNumber() == 0) return 7;
    if (lzma_version_number() == 0) return 8;
    return 0;
}

// Behavioral test — compat.argparse parses a command line, it does not merely
// include.
//
// argv is written by hand rather than taken from the runner, so the assertions
// are about argparse's behaviour and not about how `mcpp test` invokes a
// binary. No `import std;`: argparse.hpp is a textual header over the standard
// library.
#include <argparse/argparse.hpp>

#include <iostream>
#include <string>
#include <vector>

int main() {
    argparse::ArgumentParser program("renderer", "0.1.0");
    program.add_argument("model").help("path to the glTF model");
    program.add_argument("--width").default_value(1280).scan<'i', int>();
    program.add_argument("--validate").default_value(false).implicit_value(true);

    const std::vector<std::string> argv{"renderer", "scene.gltf", "--width", "1920", "--validate"};
    try {
        program.parse_args(argv);
    } catch (const std::exception& e) {
        std::cerr << "parse_args threw: " << e.what() << "\n";
        return 1;
    }

    if (program.get<std::string>("model") != "scene.gltf") { std::cerr << "positional wrong\n"; return 2; }
    if (program.get<int>("--width") != 1920)               { std::cerr << "typed scan wrong\n";  return 3; }
    if (!program.get<bool>("--validate"))                  { std::cerr << "implicit flag wrong\n"; return 4; }

    // The default has to survive an argv that never mentions the option.
    argparse::ArgumentParser defaults("renderer");
    defaults.add_argument("--width").default_value(1280).scan<'i', int>();
    defaults.parse_args(std::vector<std::string>{"renderer"});
    if (defaults.get<int>("--width") != 1280) { std::cerr << "default_value wrong\n"; return 5; }

    // A missing required positional must be an error, not a silent empty
    // string — that is the half of a parser a "compiles fine" test misses.
    argparse::ArgumentParser required("renderer");
    required.add_argument("model");
    bool threw = false;
    try {
        required.parse_args(std::vector<std::string>{"renderer"});
    } catch (const std::exception&) {
        threw = true;
    }
    if (!threw) { std::cerr << "missing positional did not throw\n"; return 6; }

    std::cout << "compat.argparse: ok (positional, typed scan, implicit flag, default, error path)\n";
    return 0;
}

// Core executor/timer behavior over the module surface: strand FIFO order,
// work-guard-driven run loop, thread_pool, and timer cancellation mapping to
// asio::error::operation_aborted. Module consumers pair `import asio;` with
// `import std;` (no text #include mixing).
import std;
import asio;

int main() {
    using namespace std::chrono_literals;

    asio::io_context io;
    auto guard = asio::make_work_guard(io);
    auto serial = asio::make_strand(io);
    asio::steady_timer timer(io, 2ms);

    std::atomic<int> posted{0};
    std::mutex order_mutex;
    std::vector<int> order;
    bool timer_called = false;

    asio::post(serial, [&] {
        std::lock_guard lock(order_mutex);
        order.push_back(1);
        ++posted;
    });
    asio::post(serial, [&] {
        std::lock_guard lock(order_mutex);
        order.push_back(2);
        ++posted;
    });
    timer.async_wait([&](const std::error_code& ec) {
        timer_called = !ec;
        guard.reset();
    });

    std::thread worker([&] { io.run(); });
    worker.join();
    if (posted != 2 || !timer_called || order != std::vector<int>{1, 2}) return 1;

    asio::thread_pool pool(2);
    std::atomic<int> pooled{0};
    asio::post(pool, [&] { ++pooled; });
    asio::post(pool, [&] { ++pooled; });
    pool.join();
    if (pooled != 2) return 2;

    asio::io_context cancel_io;
    asio::steady_timer cancelled(cancel_io, 1h);
    asio::cancellation_signal cancellation;
    std::error_code cancelled_ec;
    bool cancelled_called = false;
    cancelled.async_wait(asio::bind_cancellation_slot(
        cancellation.slot(),
        [&](const std::error_code& ec) {
            cancelled_ec = ec;
            cancelled_called = true;
        }));
    cancellation.emit(asio::cancellation_type::all);
    cancel_io.run();

    return cancelled_called && cancelled_ec == asio::error::operation_aborted ? 0 : 3;
}

// Coroutine surface: awaitable/co_spawn/use_awaitable/this_coro over the
// module boundary, including a real timer suspension point.
import std;
import asio;

asio::awaitable<int> answer() {
    auto ex = co_await asio::this_coro::executor;
    asio::steady_timer t(ex, std::chrono::milliseconds(1));
    co_await t.async_wait(asio::use_awaitable);
    co_return 42;
}

int main() {
    asio::io_context io;
    int result = 0;
    asio::co_spawn(io, answer(), [&](std::exception_ptr, int v) { result = v; });
    io.run();
    return result == 42 ? 0 : 1;
}

// The error surface: the four Asio error enums and their enumerators reach a
// module consumer, and each one compares equal to the std::error_code that
// asio::error::make_error_code builds from it.
//
// Before this was exported the module offered exactly one condition,
// operation_aborted, which is enough to notice a cancellation and nothing else:
// telling a refused connection from a DNS failure had no name to compare
// against on the consumer's side.
import std;
import asio;

int main() {
    // --- the enum types themselves ---
    static_assert(std::is_enum_v<asio::error::basic_errors>);
    static_assert(std::is_enum_v<asio::error::netdb_errors>);
    static_assert(std::is_enum_v<asio::error::addrinfo_errors>);
    static_assert(std::is_enum_v<asio::error::misc_errors>);

    // --- enumerators, one per enum, round-tripped through make_error_code ---
    const std::error_code aborted   = asio::error::make_error_code(asio::error::operation_aborted);
    const std::error_code refused   = asio::error::make_error_code(asio::error::connection_refused);
    const std::error_code timedout  = asio::error::make_error_code(asio::error::timed_out);
    const std::error_code unreach   = asio::error::make_error_code(asio::error::host_unreachable);
    const std::error_code netdown   = asio::error::make_error_code(asio::error::network_unreachable);
    const std::error_code nohost    = asio::error::make_error_code(asio::error::host_not_found);
    const std::error_code retryhost = asio::error::make_error_code(asio::error::host_not_found_try_again);
    const std::error_code nosvc     = asio::error::make_error_code(asio::error::service_not_found);
    const std::error_code eof       = asio::error::make_error_code(asio::error::eof);

    // An error_code built from an enumerator compares equal to that enumerator:
    // this is the comparison real code writes (`if (ec == asio::error::eof)`),
    // and it only works if the enumerator NAME crossed the module boundary.
    if (aborted   != asio::error::operation_aborted)          return 1;
    if (refused   != asio::error::connection_refused)         return 2;
    if (timedout  != asio::error::timed_out)                  return 3;
    if (unreach   != asio::error::host_unreachable)           return 4;
    if (netdown   != asio::error::network_unreachable)        return 5;
    if (nohost    != asio::error::host_not_found)             return 6;
    if (retryhost != asio::error::host_not_found_try_again)   return 7;
    if (nosvc     != asio::error::service_not_found)          return 8;
    if (eof       != asio::error::eof)                        return 9;

    // Distinct conditions must not collapse into each other.
    if (refused == timedout || nohost == retryhost)           return 10;

    // Every one of them is a real, non-empty condition.
    for (const auto& ec : {aborted, refused, timedout, unreach, netdown,
                           nohost, retryhost, nosvc, eof}) {
        if (!ec)                    return 11;
        if (ec.message().empty())   return 12;
    }

    // --- ip::make_address parses, and reports failure through error_code ---
    std::error_code parse;
    const auto v4 = asio::ip::make_address("192.0.2.7", parse);
    if (parse || !v4.is_v4() || v4.to_string() != "192.0.2.7") return 13;

    const auto v6 = asio::ip::make_address("::1", parse);
    if (parse || !v6.is_v6() || !v6.is_loopback())             return 14;

    (void)asio::ip::make_address("not-an-address", parse);
    if (!parse)                                                 return 15;

    if (asio::ip::make_address_v4("10.0.0.1", parse).to_string() != "10.0.0.1" || parse) return 16;
    if (!asio::ip::make_address_v6("::1", parse).is_loopback() || parse)                 return 17;

    return 0;
}

// Experimental channel/concurrent_channel/use_promise over the module surface.
import std;
import asio;

int main() {
    asio::io_context io;

    asio::experimental::channel<void(std::error_code, std::string)> ch(io, 1);
    if (!ch.try_send(std::error_code{}, "channel")) return 1;
    std::string channel_value;
    std::error_code channel_error;
    ch.async_receive([&](std::error_code ec, std::string value) {
        channel_error = ec;
        channel_value = std::move(value);
    });

    asio::experimental::concurrent_channel<void(std::error_code, int)> concurrent(io, 1);
    if (!concurrent.try_send(std::error_code{}, 42)) return 2;
    int concurrent_value = 0;
    std::error_code concurrent_error;
    concurrent.async_receive([&](std::error_code ec, int value) {
        concurrent_error = ec;
        concurrent_value = value;
    });

    auto promised = asio::post(io, asio::experimental::use_promise);
    bool promise_completed = false;
    promised([&] { promise_completed = true; });

    io.run();

    return !channel_error && channel_value == "channel"
        && !concurrent_error && concurrent_value == 42
        && promise_completed ? 0 : 3;
}

// Asio's file I/O over the module surface: asio::stream_file writes and reads
// back through a coroutine, asio::random_access_file reads at an offset, and
// asio::file_base's open flags compose.
//
// These names are exported only where Asio has a file backend. For THIS
// package's configuration the condition is exactly Windows: the backend is IOCP
// (ASIO_HAS_WINDOWS_RANDOM_ACCESS_HANDLE), and the only other one Asio offers is
// io_uring, which this package does not enable. `ASIO_HAS_FILE` itself is
// unusable as the discriminator here — a macro does not cross a module boundary
// and a module consumer includes no Asio header, so it is always false in this
// TU no matter what the package was built with.
import std;
import asio;

#if defined(_WIN32)

int main() {
    namespace fs = std::filesystem;

    const auto path = (fs::temp_directory_path() / "mcpp_asio_module_file.bin").string();
    std::error_code rm;
    fs::remove(path, rm);

    constexpr std::string_view payload = "mcpp-asio-file";

    asio::io_context io;
    int failure = 0;

    asio::co_spawn(io, [&]() -> asio::awaitable<void> {
        // --- write through stream_file, composing three file_base flags ---
        {
            asio::stream_file out(co_await asio::this_coro::executor, path,
                                  asio::file_base::write_only
                                      | asio::file_base::create
                                      | asio::file_base::truncate);
            const auto written =
                co_await asio::async_write(out, asio::buffer(payload), asio::use_awaitable);
            if (written != payload.size()) { failure = 1; co_return; }
            out.close();
        }

        // --- read it back through stream_file ---
        {
            asio::stream_file in(co_await asio::this_coro::executor, path,
                                 asio::file_base::read_only);
            std::string got(payload.size(), '\0');
            const auto read =
                co_await asio::async_read(in, asio::buffer(got), asio::use_awaitable);
            if (read != payload.size() || got != payload) { failure = 2; co_return; }
        }

        // --- random_access_file reads at an offset, leaving no file position ---
        {
            asio::random_access_file ra(co_await asio::this_coro::executor, path,
                                        asio::file_base::read_only);
            std::string tail(5, '\0');   // "-file", offset 9
            const auto read = co_await ra.async_read_some_at(9, asio::buffer(tail),
                                                             asio::use_awaitable);
            if (read != 5 || tail != "-file") { failure = 3; co_return; }
        }
    }, asio::detached);

    io.run();
    fs::remove(path, rm);

    // The aliases are the basic_ templates with the default executor.
    static_assert(std::is_same_v<asio::stream_file, asio::basic_stream_file<>>);
    static_assert(std::is_same_v<asio::random_access_file,
                                 asio::basic_random_access_file<>>);
    static_assert(std::is_base_of_v<asio::file_base, asio::stream_file>);

    return failure;
}

#else

int main() {
    // No file backend in this configuration: asserting the names are absent is
    // not something a TU can do, so this leg only records that the test ran.
    std::println("asio module: file I/O not available in this configuration");
    return 0;
}

#endif

// TCP (acceptor/socket, async_read/async_write), the free asio::async_connect
// over a sequence of candidate endpoints, and UDP (datagram send/receive) over
// the imported module surface.
import std;
import asio;

int main() {
    using namespace std::chrono_literals;

    // --- TCP echo ---
    asio::io_context io;
    asio::ip::tcp::acceptor acceptor(io, {asio::ip::address_v4::loopback(), 0});
    asio::ip::tcp::socket server(io);
    asio::ip::tcp::socket client(io);
    asio::steady_timer deadline(io, 5s);

    const std::string ping = "ping";
    const std::string pong = "pong";
    std::array<char, 4> server_data{};
    std::array<char, 4> client_data{};
    bool accepted = false;
    bool connected = false;
    bool tcp_done = false;
    bool timed_out = false;
    int failure = 0;

    auto fail = [&](int code) {
        if (failure == 0) failure = code;
        std::error_code ignored;
        acceptor.close(ignored);
        server.close(ignored);
        client.close(ignored);
        deadline.cancel();
    };

    deadline.async_wait([&](const std::error_code& ec) {
        if (!ec) {
            timed_out = true;
            fail(90);
        }
    });

    acceptor.async_accept(server, [&](const std::error_code& ec) {
        if (ec) return fail(1);
        accepted = true;
        asio::async_read(server, asio::buffer(server_data),
            [&](const std::error_code& read_ec, std::size_t n) {
                if (read_ec || n != ping.size()
                    || std::string(server_data.data(), n) != ping) return fail(2);
                asio::async_write(server, asio::buffer(pong),
                    [&](const std::error_code& write_ec, std::size_t written) {
                        if (write_ec || written != pong.size()) fail(3);
                    });
            });
    });

    client.async_connect(
        {asio::ip::address_v4::loopback(), acceptor.local_endpoint().port()},
        [&](const std::error_code& ec) {
            if (ec) return fail(4);
            connected = true;
            asio::async_write(client, asio::buffer(ping),
                [&](const std::error_code& write_ec, std::size_t written) {
                    if (write_ec || written != ping.size()) return fail(5);
                    asio::async_read(client, asio::buffer(client_data),
                        [&](const std::error_code& read_ec, std::size_t n) {
                            if (read_ec || n != pong.size()
                                || std::string(client_data.data(), n) != pong) return fail(6);
                            tcp_done = true;
                            deadline.cancel();
                        });
                });
        });

    io.run();
    if (failure || timed_out || !accepted || !connected || !tcp_done) return failure ? failure : 7;

    // --- UDP datagram ---
    asio::io_context udp_io;
    asio::ip::udp::socket receiver(udp_io, {asio::ip::address_v4::loopback(), 0});
    asio::ip::udp::socket sender(udp_io, {asio::ip::address_v4::loopback(), 0});
    const std::string datagram = "asio-udp";
    std::array<char, 8> received{};
    asio::ip::udp::endpoint remote;
    bool receive_done = false;
    bool send_done = false;
    std::error_code udp_failure;

    receiver.async_receive_from(asio::buffer(received), remote,
        [&](const std::error_code& ec, std::size_t n) {
            udp_failure = ec;
            receive_done = !ec && n == datagram.size()
                && std::string(received.data(), n) == datagram;
        });
    sender.async_send_to(asio::buffer(datagram), receiver.local_endpoint(),
        [&](const std::error_code& ec, std::size_t n) {
            if (ec) udp_failure = ec;
            send_done = !ec && n == datagram.size();
        });

    udp_io.run();
    if (udp_failure || !receive_done || !send_done) return 8;

    // --- free asio::async_connect over a candidate sequence ---
    //
    // The member socket.async_connect above takes ONE endpoint; the free
    // function takes a range and tries each in turn, which is what a consumer
    // hands a resolver's results_type to. Assert that semantics directly:
    // an unreachable candidate first, the live acceptor second. Kept hermetic
    // (no DNS) so it cannot fail for reasons that have nothing to do with the
    // module surface.
    asio::io_context connect_io;
    asio::ip::tcp::acceptor live(connect_io, {asio::ip::address_v4::loopback(), 0});
    asio::ip::tcp::socket accepted_side(connect_io);
    asio::ip::tcp::socket connecting(connect_io);
    live.async_accept(accepted_side, [](const std::error_code&) {});

    const std::vector<asio::ip::tcp::endpoint> candidates{
        // Port 1 on loopback: nothing listens there, so this candidate is
        // refused and async_connect must move on rather than give up.
        {asio::ip::address_v4::loopback(), 1},
        live.local_endpoint(),
    };

    std::error_code connect_ec{std::make_error_code(std::errc::not_supported)};
    asio::ip::tcp::endpoint chosen;
    bool connect_done = false;

    asio::async_connect(connecting, candidates,
        [&](const std::error_code& ec, const asio::ip::tcp::endpoint& ep) {
            connect_ec = ec;
            chosen = ep;
            connect_done = true;
        });

    connect_io.run();
    if (!connect_done || connect_ec) return 9;
    if (chosen != live.local_endpoint()) return 10;   // it must have skipped port 1
    if (!connecting.is_open()) return 11;

    return 0;
}

// Surface/smoke coverage: exported types, completion tokens, and vocabulary
// types are usable across the module boundary.
import std;
import fmt;
import asio;

int main() {
    // 回归：导入 Asio 后，libc++ 的 println 仍应保持可用。
    std::println("asio module println");
    std::println("asio module println {}", 42);

    // --- buffer / address (existing) ---
    std::array<char, 4> src{'m', 'c', 'p', 'p'};
    asio::const_buffer cb = asio::buffer(src);
    if (cb.size() != 4) return 1;

    std::string dst(4, '\0');
    asio::mutable_buffer mb = asio::buffer(dst);
    std::memcpy(mb.data(), cb.data(), cb.size());
    if (dst != "mcpp") return 2;

    asio::ip::address_v4 loopback = asio::ip::address_v4::loopback();
    if (loopback.to_string() != "127.0.0.1") return 3;

    asio::ip::tcp::endpoint ep(loopback, 8080);
    if (ep.port() != 8080) return 4;

    // --- execution context hierarchy ---
    if (!std::is_base_of_v<asio::execution_context, asio::io_context>) return 5;
    if (!std::is_base_of_v<asio::execution_context, asio::system_context>) return 6;
    if (!std::is_base_of_v<asio::execution_context, asio::thread_pool>) return 7;

    // --- executors ---
    static_assert(std::is_class_v<asio::any_io_executor>);
    static_assert(std::is_class_v<asio::system_executor>);

    // --- error_code typedef ---
    static_assert(std::is_same_v<asio::error_code, std::error_code>);

    // --- cancellation_type (scoped enum) ---
    static_assert(std::is_enum_v<asio::cancellation_type>);
    if (static_cast<int>(asio::cancellation_type::all) == 0) return 8;
    if (static_cast<int>(asio::cancellation_type::terminal) == 0) return 9;

    // --- signal / timer types ---
    static_assert(std::is_class_v<asio::signal_set>);
    static_assert(std::is_class_v<asio::system_timer>);

    // --- completion token variables ---
    asio::io_context surface_io;
    // detached — compile test for the constexpr variable and its usage
    asio::steady_timer t(surface_io, std::chrono::milliseconds(0));
    t.async_wait(asio::detached);
    static_assert(std::is_same_v<decltype(asio::detached), const asio::detached_t>);

    // use_future — accessible as a named variable
    auto uf = asio::use_future;
    (void)uf;

    // deferred
    static_assert(std::is_same_v<decltype(asio::deferred), const asio::deferred_t>);

    // --- redirect_error ---
    std::error_code redirect_ec;
    auto redirected = asio::redirect_error(redirect_ec);
    (void)redirected;

    // --- bind_executor ---
    auto bound = asio::bind_executor(asio::system_executor(), []{});
    (void)bound;

    // --- associated traits ---
    static_assert(std::is_class_v<asio::associated_allocator<int>>);
    static_assert(std::is_class_v<asio::associated_executor<int>>);
    static_assert(std::is_class_v<asio::associated_cancellation_slot<int>>);

    // --- error namespace ---
    if (asio::error::operation_aborted == std::error_code{}) return 10;

    return 0;
}

