// Entirely OFFLINE — no DNS query is ever sent, so the result does not depend
// on the runner's network. What it does exercise is the machinery gRPC's
// resolver actually leans on, and each piece lives in a different part of the
// library:
//
//   ares_library_init / _cleanup   -> src/lib/ares_library_init.c
//   ares_init_options / ares_destroy -> ares_init.c, ares_options.c, util/*
//   set/get servers as CSV         -> ares_options.c, str/*, record/* (parsing
//                                     an address list is real string+record work)
//   ares_inet_pton / ares_inet_ntop -> inet_net_pton.c, inet_ntop.c
//   ares_strerror                  -> ares_strerror.c
//
// Returns non-zero on any mismatch.
#include <cstring>
#include <string>

#include "ares.h"

namespace {

bool version_ok() {
    int num = 0;
    const char* s = ares_version(&num);
    // The descriptor pins 1.34.5; assert the header/library agree with it, so a
    // silently different vendored version cannot pass.
    return s != nullptr && std::string(s).find("1.34.5") != std::string::npos &&
           ((num >> 16) & 0xff) == 1 && ((num >> 8) & 0xff) == 34 && (num & 0xff) == 5;
}

bool channel_and_servers_ok() {
    struct ares_options opts;
    std::memset(&opts, 0, sizeof(opts));
    opts.flags = ARES_FLAG_NOSEARCH | ARES_FLAG_NOALIASES;

    ares_channel_t* ch = nullptr;
    if (ares_init_options(&ch, &opts, ARES_OPT_FLAGS) != ARES_SUCCESS) return false;

    bool ok = false;
    // Setting servers parses the CSV into c-ares' internal server list; reading
    // it back re-serializes it. A stub would not survive the round trip.
    if (ares_set_servers_csv(ch, "127.0.0.1:5353,[::1]:5354") == ARES_SUCCESS) {
        char* csv = ares_get_servers_csv(ch);
        if (csv != nullptr) {
            const std::string got(csv);
            ok = got.find("127.0.0.1") != std::string::npos &&
                 got.find("5353") != std::string::npos &&
                 got.find("::1") != std::string::npos;
            ares_free_string(csv);
        }
    }

    // Garbage must be REJECTED — otherwise the "parse" above proves nothing.
    if (ok && ares_set_servers_csv(ch, "not-an-address:::") == ARES_SUCCESS) ok = false;

    ares_destroy(ch);
    return ok;
}

bool inet_conversions_ok() {
    unsigned char buf[16];
    char out[64];

    if (ares_inet_pton(AF_INET, "192.0.2.7", buf) != 1) return false;
    if (ares_inet_ntop(AF_INET, buf, out, sizeof(out)) == nullptr) return false;
    if (std::string(out) != "192.0.2.7") return false;

    if (ares_inet_pton(AF_INET6, "2001:db8::1", buf) != 1) return false;
    if (ares_inet_ntop(AF_INET6, buf, out, sizeof(out)) == nullptr) return false;
    if (std::string(out) != "2001:db8::1") return false;

    // Malformed input must fail.
    return ares_inet_pton(AF_INET, "999.1.1.1", buf) != 1;
}

bool strerror_ok() {
    const char* ok = ares_strerror(ARES_SUCCESS);
    const char* nf = ares_strerror(ARES_ENOTFOUND);
    return ok != nullptr && nf != nullptr && std::strlen(nf) > 0 &&
           std::string(ok) != std::string(nf);
}

}  // namespace

int main() {
    if (ares_library_init(ARES_LIB_INIT_ALL) != ARES_SUCCESS) return 1;

    const bool ok = version_ok() && channel_and_servers_ok() &&
                    inet_conversions_ok() && strerror_ok();

    ares_library_cleanup();
    return ok ? 0 : 1;
}

// cairo, via its HEADERS — draw something, read the pixels back, and check that the
// feature split actually took effect.
//
// Cairo needs no display and no fonts on disk to draw: an image surface is
// memory, and that is what a compositor's software fallback and every
// screenshot path use. So this test draws for real rather than only checking
// that symbols resolve.
//
// THE FEATURE ASSERTIONS ARE THE POINT OF THE PACKAGE. `xlib` and `xcb` are off
// by default, and "off" has to mean the macro is undefined — otherwise a
// consumer could `#include <cairo-xlib.h>` and fail at link instead of at
// compile, which is the wrong place to find out.

#ifdef __linux__

#include <cairo.h>
// ⚠️ cairo.h does NOT reach the feature headers. This name used to arrive from
// the module — which is precisely the confusion this split removes: on the
// header route you include what you use.
#include <cairo-ft.h>

#include <cstdio>
#include <cstring>

// ⚠️ THIS FILE IS THE HEADER ROUTE, AND IT NO LONGER IMPORTS.
//
// It used to do BOTH — `#include <cairo.h>` and `import freedesktop.cairo;` —
// and that is why nobody noticed the module was incomplete: the header
// supplied every name the module was missing, including `cairo_t` and all 192
// enumerators. An import that is never asked to stand on its own is not
// tested, it is decorated.
//
// `tests/module.cpp` next door takes the module route alone. Two files,
// because on GCC the two routes cannot be combined in one TU anyway: reaching
// a system header both textually and through a module's global fragment makes
// the same type two entities.

namespace {

int failures = 0;

void check(bool ok, const char *what)
{
    std::printf("%-58s %s\n", what, ok ? "ok" : "FAILED");
    if (!ok) {
        ++failures;
    }
}

} // namespace

int main()
{
    std::printf("   cairo %s\n", cairo_version_string());
    check(cairo_version() >= 11802, "cairo_version reports 1.18.2 or newer");

    // ── 1. Draw, then read the pixel back ────────────────────────────────
    // A 64x64 ARGB32 surface, filled with an exact colour, then one pixel
    // sampled. Exact because cairo_set_source_rgb takes doubles and
    // 0.25/0.5/0.75 land on 64/128/191 without rounding ambiguity — the same
    // values the GBM/EGL closed-loop test uses, for the same reason.
    cairo_surface_t *s = cairo_image_surface_create(CAIRO_FORMAT_ARGB32, 64, 64);
    check(cairo_surface_status(s) == CAIRO_STATUS_SUCCESS,
          "cairo_image_surface_create(ARGB32, 64, 64)");

    cairo_t *cr = cairo_create(s);
    check(cairo_status(cr) == CAIRO_STATUS_SUCCESS, "cairo_create on it");

    // ONE drawing pass, THEN one flush, THEN read. The first version of this
    // test flushed and read between the paint and the stroke, and the stroke
    // then changed zero pixels with `cairo_status` still SUCCESS — cairo had
    // handed the buffer out and did not take it back. `cairo_surface_flush` is
    // the end of a drawing sequence, not a checkpoint inside one.
    cairo_set_source_rgb(cr, 0.25, 0.5, 0.75);
    cairo_paint(cr);

    cairo_set_source_rgb(cr, 1, 1, 1);
    cairo_set_line_width(cr, 8);
    cairo_move_to(cr, 8, 8);
    cairo_line_to(cr, 56, 56);
    cairo_stroke(cr);

    check(cairo_status(cr) == CAIRO_STATUS_SUCCESS, "…and the context is still clean");
    cairo_surface_flush(s);

    const unsigned char *d = cairo_image_surface_get_data(s);
    const int stride = cairo_image_surface_get_stride(s);

    // ARGB32 is little-endian: B G R A.
    // (56,8) is far from the diagonal, so it still carries the paint —
    // 0.25/0.5/0.75 land on 64/128/191 with no rounding ambiguity, the same
    // values the GBM/EGL closed-loop test uses and for the same reason.
    const unsigned char *bg = d + 8 * stride + 56 * 4;
    std::printf("   (56,8) = %u %u %u %u (B G R A)\n", bg[0], bg[1], bg[2], bg[3]);
    check(bg[2] == 64 && bg[1] == 128 && bg[0] == 191 && bg[3] == 255,
          "the painted background is exactly what was asked for");

    // (32,32) is on the diagonal, under an 8px white stroke.
    const unsigned char *on = d + 32 * stride + 32 * 4;
    std::printf("   (32,32) = %u %u %u %u\n", on[0], on[1], on[2], on[3]);
    // ── 3. The path machinery, checked directly ─────────────────────────
    //
    // These three are here because of what they caught. With
    // `WORDS_BIGENDIAN` defined to 0 — which cairo tests with `#ifdef`, so 0
    // means BIG-ENDIAN — every path got garbage fixed-point coordinates while
    // `cairo_status` reported success and `cairo_paint` kept working:
    //
    //     path_extents      -8.03e+06 -8.03e+06 4.37e+06 4.37e+06
    //     in_fill(40, 40)   1          (the point is outside the rectangle)
    //
    // The pixel check above catches it too, but only as "the stroke drew
    // nothing", which sends you looking for a missing source file. These say
    // where the arithmetic went wrong.
    {
        cairo_t *c3 = cairo_create(s);
        cairo_rectangle(c3, 4, 4, 16, 16);
        double x1, y1, x2, y2;
        cairo_path_extents(c3, &x1, &y1, &x2, &y2);
        std::printf("   path_extents = %g %g %g %g\n", x1, y1, x2, y2);
        check(x1 == 4 && y1 == 4 && x2 == 20 && y2 == 20,
              "a rectangle path has the extents it was given");
        check(cairo_in_fill(c3, 10, 10) == 1, "…and a point inside it reads as inside");
        check(cairo_in_fill(c3, 40, 40) == 0, "…and a point outside reads as outside");
        cairo_destroy(c3);
    }

    check(on[0] == 255 && on[1] == 255 && on[2] == 255,
          "…and the stroked diagonal covers the centre in white");


    cairo_destroy(cr);
    cairo_surface_destroy(s);

    // ── 3. The default feature set ───────────────────────────────────────
#ifdef CAIRO_HAS_FT_FONT
    check(true, "feature ft is ON by default (CAIRO_HAS_FT_FONT)");
#else
    check(false, "feature ft should be ON by default");
#endif
#ifdef CAIRO_HAS_FC_FONT
    check(true, "feature fc is ON by default (CAIRO_HAS_FC_FONT)");
#else
    check(false, "feature fc should be ON by default");
#endif
#ifdef CAIRO_HAS_PNG_FUNCTIONS
    check(true, "feature png is ON by default");
#else
    check(false, "feature png should be ON by default");
#endif

    // ── 4. X11 is OFF, and that is the whole point ───────────────────────
    // A Wayland program must not acquire libX11 by depending on cairo. If this
    // ever fails, someone made a backend unconditional.
#ifdef CAIRO_HAS_XLIB_SURFACE
    check(false, "xlib must be OFF unless the consumer asks for it");
#else
    check(true, "feature xlib is OFF by default — no libX11 pulled in");
#endif
#ifdef CAIRO_HAS_XCB_SURFACE
    check(false, "xcb must be OFF unless the consumer asks for it");
#else
    check(true, "feature xcb is OFF by default");
#endif

    // ── 5. The module carries what the features enabled ──────────────────
    // `cairo_image_surface_create_from_png` lives behind CAIRO_HAS_PNG_FUNCTIONS
    // inside cairo.h itself, not in a feature header — the module generator has
    // to notice that or a png-enabled consumer cannot reach it through `import`.
    check(&cairo_surface_write_to_png != nullptr,
          "module exports a name guarded inside cairo.h (write_to_png)");
    check(&cairo_ft_font_face_create_for_ft_face != nullptr,
          "…and one from a feature header (cairo_ft_font_face_create…)");

    std::printf("\n%d check(s) failed\n", failures);
    return failures == 0 ? 0 : 1;
}

#else
int main() { return 0; }
#endif

// cairo, via its MODULE — and this is the route that had never been checked.
//
// ⭐ WHY THIS FILE EXISTS
//
// The package exposed `import freedesktop.cairo;` and the only test that named
// it also wrote `#include <cairo.h>`. So the header supplied whatever the
// module lacked, and what it lacked was substantial:
//
//     470 names exported, and among the missing:
//       cairo_t              the single most-used type in the library
//       192 enumerators      every CAIRO_FORMAT_*, CAIRO_STATUS_*, CAIRO_OPERATOR_*
//
// It was found from OUTSIDE, by gnome.pangocairo — which cannot mix the two
// routes (pangocairo.h reaches glib and therefore <stdio.h>, so a textual
// include alongside the import makes `struct _IO_FILE` two entities) and
// therefore had to ask the module for `cairo_t` and got nothing.
//
// This file includes NOTHING. That is the whole point: if a name is missing
// from the module, this fails to compile.

#ifdef __linux__

import cairo;

#include <cstdio>

namespace {

int failures = 0;

void check(bool ok, const char *what)
{
    std::printf("%-58s %s\n", what, ok ? "ok" : "FAILED");
    if (!ok) {
        ++failures;
    }
}

} // namespace

int main()
{
    std::printf("import cairo — %s\n\n", cairo_version_string());

    // ── the types, including the one that used to be missing ─────────────
    cairo_surface_t *surf = cairo_image_surface_create(CAIRO_FORMAT_ARGB32, 64, 64);
    check(cairo_surface_status(surf) == CAIRO_STATUS_SUCCESS,
          "cairo_image_surface_create — CAIRO_FORMAT_ARGB32 is an ENUMERATOR");
    check(cairo_image_surface_get_format(surf) == CAIRO_FORMAT_ARGB32,
          "…and the surface reports the format that was asked for");

    // ⭐ `cairo_t` — `typedef struct _cairo cairo_t;`. The old regex required at
    // least one character between `cairo_` and `_t`, so this one name, the one
    // every cairo program starts with, was the one it could not match.
    cairo_t *cr = cairo_create(surf);
    check(cairo_status(cr) == CAIRO_STATUS_SUCCESS, "cairo_create returns a live cairo_t");

    // ── draw, and read the pixels back ───────────────────────────────────
    cairo_set_source_rgb(cr, 1.0, 0.0, 0.0);
    cairo_rectangle(cr, 8, 8, 48, 48);
    cairo_fill(cr);
    cairo_surface_flush(surf);

    const unsigned char *d = cairo_image_surface_get_data(surf);
    const int stride = cairo_image_surface_get_stride(surf);
    check(d != nullptr, "the image surface has readable pixel data");

    long ink = 0;
    for (int y = 0; d && y < 64; ++y) {
        for (int x = 0; x < 64; ++x) {
            if (d[static_cast<long>(y) * stride + 4 * x + 3] != 0) {
                ++ink;
            }
        }
    }
    std::printf("   filled pixels: %ld (expected 48*48 = 2304)\n", ink);
    check(ink == 48 * 48, "the rectangle is exactly the pixels it asked for");

    // ── more enumerators, from three different enums ─────────────────────
    cairo_set_operator(cr, CAIRO_OPERATOR_OVER);
    check(cairo_get_operator(cr) == CAIRO_OPERATOR_OVER, "CAIRO_OPERATOR_OVER");
    cairo_set_line_cap(cr, CAIRO_LINE_CAP_ROUND);
    check(cairo_get_line_cap(cr) == CAIRO_LINE_CAP_ROUND, "CAIRO_LINE_CAP_ROUND");
    cairo_set_fill_rule(cr, CAIRO_FILL_RULE_EVEN_ODD);
    check(cairo_get_fill_rule(cr) == CAIRO_FILL_RULE_EVEN_ODD, "CAIRO_FILL_RULE_EVEN_ODD");

    // ── the matrix, which is a struct type rather than an opaque handle ──
    cairo_matrix_t m;
    cairo_matrix_init_identity(&m);
    cairo_matrix_translate(&m, 3.0, 4.0);
    check(m.x0 == 3.0 && m.y0 == 4.0, "cairo_matrix_t is a usable value type");

    // ── the FreeType font backend, which is a default feature ────────────
    // ⚠️ The point is the ENUMERATOR: CAIRO_FONT_TYPE_FT is what a consumer
    // compares against, and it was among the 192 that never made it out.
    cairo_font_face_t *ff = cairo_get_font_face(cr);
    std::printf("   default font backend: %d (CAIRO_FONT_TYPE_FT=%d)\n",
                (int) cairo_font_face_get_type(ff), (int) CAIRO_FONT_TYPE_FT);
    check(cairo_font_face_status(ff) == CAIRO_STATUS_SUCCESS,
          "the default font face is live");

    cairo_destroy(cr);
    cairo_surface_destroy(surf);

    std::printf("\n%s\n", failures == 0 ? "all ok" : "FAILURES");
    return failures == 0 ? 0 : 1;
}

