static bool check_lua() {
    lua_State* state = luaL_newstate();
    if (!state) return false;
    luaL_openlibs(state);
    const int rc = luaL_dostring(state, "return 20 + 22");
    const bool ok = rc == LUA_OK && lua_isinteger(state, -1) && lua_tointeger(state, -1) == 42;
    lua_close(state);
