}
static bool check_mbedtls() {
    const unsigned char input[] = "abc";
    std::array<unsigned char, 32> out{};
    mbedtls_sha256(input, 3, out.data(), 0);
    return out[0] == 0xba && out[1] == 0x78 && out[30] == 0x15 && out[31] == 0xad;
}
static bool check_opengl_headers() {
    return GL_TEXTURE_2D == 0x0DE1 && static_cast<khronos_uint32_t>(1) == 1;
}

TEST(CompatGTest, BasicAssertion) { EXPECT_EQ(2 + 2, 4); }
TEST(CompatCore, UpstreamHeadersAndMinimalRuntime) {
    EXPECT_TRUE(check_ftxui());
    EXPECT_TRUE(check_lua());
    EXPECT_TRUE(check_mbedtls());
    EXPECT_TRUE(check_opengl_headers());
}

// Behavioral test — compat.cpptrace unwinds a real call stack.
//
// What is asserted is deliberately what the CHOSEN BACKENDS can answer on a
// bare CI runner. The package selects `_Unwind_Backtrace` + `dladdr` on unix
// and DbgHelp on windows, all dependency-free, and the documented cost of that
// choice is that frames carry no file:line (dladdr does not read DWARF). So
// this test asserts the unwinder — frame count and distinct return addresses —
// and never asserts on line numbers, which would be testing libdwarf's absence
// rather than this package.
#include <cpptrace/cpptrace.hpp>
#include <cpptrace/version.hpp>

#include <cstdio>
#include <cstdint>

#if CPPTRACE_VERSION != CPPTRACE_TO_VERSION(1, 0, 4)
#  error "cpptrace/version.hpp does not describe 1.0.4 — the generated header drifted from the tarball"
#endif

// The package builds objects, not a shared library, so every cpptrace
// declaration this TU sees must be plain — not dllimport, not
// visibility("default"). The package delivers that with a shim in front of
// cpptrace/basic.hpp, because no descriptor key carries a define to a
// consumer's TUs.
//
// This check exists because the failure it guards is invisible on Linux: there
// the difference is only a visibility attribute and everything still links. On
// the MSVC ABI it is `dllimport` versus nothing, and the link fails with
// "undefined symbol: __declspec(dllimport) ...". Asserting the macro at COMPILE
// time fails on every platform the moment the shim stops being reached.
#if !defined(CPPTRACE_STATIC_DEFINE)
#  error "CPPTRACE_STATIC_DEFINE is not set for this consumer TU — the compat.cpptrace basic.hpp shim was not reached (include_dirs order?)"
#endif

// noinline so the three frames cannot be collapsed into one by the optimiser;
// the test is about the unwinder seeing depth.
#if defined(_MSC_VER)
#  define NOINLINE __declspec(noinline)
#else
#  define NOINLINE __attribute__((noinline))
#endif

static NOINLINE cpptrace::stacktrace level_three() { return cpptrace::generate_trace(); }
static NOINLINE cpptrace::stacktrace level_two()   { return level_three(); }
static NOINLINE cpptrace::stacktrace level_one()   { return level_two(); }

int main() {
    const cpptrace::stacktrace trace = level_one();

    if (trace.frames.empty()) {
        std::printf("generate_trace returned no frames — the unwinder produced nothing\n");
        return 1;
    }
    // main + three levels, minus whatever the runtime trims. Four is the
    // number the chain above must at least reach for the unwind to be real
    // rather than a single-frame stub.
    if (trace.frames.size() < 4) {
        std::printf("only %zu frames; expected the four-deep chain to survive\n", trace.frames.size());
        return 2;
    }

    // Distinct return addresses: a stub that filled the vector with one
    // repeated address would pass the count check but not this one.
    std::uintptr_t distinct = 0;
    for (std::size_t i = 1; i < trace.frames.size(); ++i) {
        if (trace.frames[i].raw_address != trace.frames[i - 1].raw_address) ++distinct;
    }
    if (distinct == 0) {
        std::printf("every frame has the same address\n");
        return 3;
    }
    if (trace.frames[0].raw_address == 0) {
        std::printf("top frame has a null address\n");
        return 4;
    }

    std::printf("compat.cpptrace: ok (%zu frames, %ju distinct addresses, version %d)\n",
                trace.frames.size(), static_cast<std::uintmax_t>(distinct), CPPTRACE_VERSION);
    return 0;
}

// The load path first, the device second.
//
// Reaching main is itself the assertion this member exists for: it means every
// DT_NEEDED of libcurand.so resolved through the farm compat.curand builds,
// including the C library stubs that the component's own `RUNPATH = $ORIGIN`
// would otherwise hide.
#include <cstdio>

// The adapters under test exist only on Linux, so the assertions do too. The
// file still compiles everywhere, which is what keeps it from rotting silently
// on the two platforms that do not exercise it.
#ifndef __linux__
int main() {
    std::printf("not applicable on this platform\n");
    return 0;
}
#else
#include <curand.h>
#include <cuda_runtime.h>

#include <cmath>

static int failures = 0;

static void check(bool ok, const char* what) {
    if (!ok) { std::printf("FAIL: %s\n", what); ++failures; }
    else       std::printf("ok: %s\n", what);
}

int main() {
    // ⭐ REACHING THIS LINE IS THE ASSERTION THIS MEMBER EXISTS FOR. Every
    // DT_NEEDED of libcurand.so had to resolve through the farm compat.curand
    // builds, including the C library stubs that the component's own
    // `RUNPATH = $ORIGIN` would otherwise hide. That failure happens before
    // main on every machine, with or without a device.
    int devices = 0;
    const cudaError_t rc = cudaGetDeviceCount(&devices);
    if (rc != cudaSuccess || devices == 0) {
        // Not a failure. A machine with no NVIDIA driver is a legitimate
        // configuration and every runner in this repository is one.
        //
        // ⚠️ THE DEVICE CHECK COMES FIRST, and that ordering is a correction.
        // An earlier revision created the generator before asking, on the
        // theory that a generator is a host-side object. Measured on CI:
        // `curandCreateGenerator` fails with `CUDA driver version is
        // insufficient for CUDA runtime version` on a driverless machine, so
        // the member reported a failure for the one configuration it was
        // written to tolerate.
        std::printf("ok: the library loaded and answered; no device here (%s)\n",
                    cudaGetErrorString(rc));
        return 0;
    }

    curandGenerator_t gen{};
    check(curandCreateGenerator(&gen, CURAND_RNG_PSEUDO_DEFAULT) == CURAND_STATUS_SUCCESS,
          "curandCreateGenerator answers");

    float* dev = nullptr;
    check(cudaMalloc(&dev, 4096 * sizeof(float)) == cudaSuccess, "cudaMalloc");
    check(curandSetPseudoRandomGeneratorSeed(gen, 1234ULL) == CURAND_STATUS_SUCCESS,
          "curandSetPseudoRandomGeneratorSeed");
    check(curandGenerateUniform(gen, dev, 4096) == CURAND_STATUS_SUCCESS,
          "curandGenerateUniform");

    float host[4096]{};
    check(cudaMemcpy(host, dev, sizeof host, cudaMemcpyDeviceToHost) == cudaSuccess,
          "cudaMemcpy back");

    double sum = 0.0;
    bool in_range = true;
    for (float v : host) {
        if (v < 0.0f || v > 1.0f) in_range = false;
        sum += v;
    }
    check(in_range, "every value lies in [0, 1]");
    check(std::fabs(sum / 4096.0 - 0.5) < 0.05, "the mean is near 0.5");

    cudaFree(dev);
    curandDestroyGenerator(gen);
    return failures == 0 ? 0 : 1;
}
#endif  // __linux__

// What compat.cuda-driver is asserted to do, and what it is not.
//
// A machine with no NVIDIA driver is a legitimate configuration and is what
// every runner in this repository is, so the test cannot require a device. It
// asserts the two properties that hold on both kinds of machine:
//
//   1. The package resolves, builds and links. That alone covers the failure
//      this package exists to prevent, because the failure is a LINK-time one:
//      an unversioned libcuda.so harvested into a directory mcpp puts on the
//      link line would be picked up by -lcuda and bind the build to one
//      machine's driver. The patterns are versioned precisely so that cannot
//      happen, and a build that links proves it did not.
//
//   2. Where a driver is present, the farm reaches it. Guarded on the driver
//      actually being there rather than skipped by a marker, so the assertion
//      is real on a machine with a GPU and vacuous on one without, and neither
//      case is reported as a pass of the other.
#include <cstdio>

// The adapter under test exists only on Linux, so the assertion does too. The
// file still compiles everywhere, which is what keeps it from rotting silently
// on the two platforms that do not exercise it.
#ifndef __linux__
int main() {
    std::printf("not applicable on this platform\n");
    return 0;
}
#else
#include <dlfcn.h>

int main() {
    // The driver's userspace library, by soname. The farm's whole job is to
    // make this resolve from inside mcpp's own loader, which does not search
    // the host's library path.
    void* h = dlopen("libcuda.so.1", RTLD_LAZY);
    if (!h) {
        // No driver on this machine. The farm is empty, which is correct.
        std::printf("no host driver: %s\n", dlerror());
        return 0;
    }
    // Present: then the symbol every CUDA runtime looks for must be there too.
    // A farm that linked a stale or wrong-class file would resolve the library
    // and fail here, which is the difference between "found something" and
    // "found the driver".
    void* sym = dlsym(h, "cuInit");
    std::printf("host driver present, cuInit=%p\n", sym);
    dlclose(h);
    return sym ? 0 : 1;
}
#endif

// Behavioral test — verify compat.curl builds a usable libcurl with working
// TLS, without touching the network.
//
// CI runners have no reliable outbound network and the index's other members
// never assume one, so nothing here opens a connection. What is asserted
// instead is everything that a misconfigured build actually gets wrong:
//
//   * the library initialises at all (curl_global_init walks the same setup
//     path a real transfer would),
//   * the TLS backend is really compiled in — a curl built with no SSL still
//     links and still runs, it just silently cannot do https, which is exactly
//     the failure EUI-NEO's `network` feature would hit at runtime,
//   * https and http are among the supported protocols,
//   * a handle can be configured with the options EUI-NEO actually sets.
#include <curl/curl.h>
import std;

// CURL_STATICLIB must arrive from the PACKAGE, not from this project. Without
// it <curl/curl.h> declares everything __declspec(dllimport) and the Windows
// link fails against a static archive; on other platforms it is inert, so this
// compile-time check is the only thing that catches a regression early.
static_assert([] {
#if defined(CURL_STATICLIB)
    return true;
#else
    return false;
#endif
}(), "CURL_STATICLIB did not reach the consumer — compat.curl stopped publishing it");

int main() {
    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        std::println("curl_global_init failed");
        return 1;
    }

    const curl_version_info_data* info = curl_version_info(CURLVERSION_NOW);
    if (info == nullptr) {
        std::println("curl_version_info returned null");
        curl_global_cleanup();
        return 2;
    }

    // The whole point of wiring a TLS backend. `ssl_version` is null when curl
    // was built without one.
    if ((info->features & CURL_VERSION_SSL) == 0 || info->ssl_version == nullptr) {
        std::println("libcurl built WITHOUT TLS — https would fail at runtime");
        curl_global_cleanup();
        return 3;
    }

    bool haveHttps = false;
    bool haveHttp = false;
    for (const char* const* p = info->protocols; p != nullptr && *p != nullptr; ++p) {
        const std::string_view proto{*p};
        if (proto == "https") haveHttps = true;
        if (proto == "http") haveHttp = true;
    }
    if (!haveHttp || !haveHttps) {
        std::println("missing protocol support (http={}, https={})", haveHttp, haveHttps);
        curl_global_cleanup();
        return 4;
    }

    // The exact option set core/platform/network.cpp configures. A handle that
    // rejects any of these would break the `network` feature.
    CURL* handle = curl_easy_init();
    if (handle == nullptr) {
        std::println("curl_easy_init failed");
        curl_global_cleanup();
        return 5;
    }
    const bool optionsOk =
        curl_easy_setopt(handle, CURLOPT_URL, "https://example.invalid/") == CURLE_OK &&
        curl_easy_setopt(handle, CURLOPT_FOLLOWLOCATION, 1L) == CURLE_OK &&
        curl_easy_setopt(handle, CURLOPT_TIMEOUT, 15L) == CURLE_OK &&
        curl_easy_setopt(handle, CURLOPT_NOPROGRESS, 0L) == CURLE_OK;
    curl_easy_cleanup(handle);

    if (!optionsOk) {
        std::println("curl_easy_setopt rejected an option EUI-NEO relies on");
        curl_global_cleanup();
        return 6;
    }

    std::println("compat.curl: ok ({}, ssl={}, http+https present)",
                 info->version, info->ssl_version);
    curl_global_cleanup();
    return 0;
}

// Behavioral test — compat.doctest gives a working framework AND its main.
//
// No `import std;` here: doctest.h is a textual header that includes the C++
// standard headers itself, and mixing those with the std module is the one
// thing this index's module packages tell consumers not to do.
//
// A failing REQUIRE makes doctest return a non-zero exit code, which is how
// `mcpp test` sees it — so the assertions below are the test, and the runner
// needs no adapter.
#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include <doctest/doctest.h>

#include <string>
#include <vector>

static unsigned factorial(unsigned n) { return n <= 1 ? 1 : n * factorial(n - 1); }

TEST_CASE("factorial") {
    CHECK(factorial(0) == 1);
    CHECK(factorial(5) == 120);
}

TEST_CASE("subcases run independently") {
    std::vector<int> v;
    SUBCASE("one element") {
        v.push_back(1);
        CHECK(v.size() == 1);
    }
    SUBCASE("two elements") {
        v.push_back(1);
        v.push_back(2);
        CHECK(v.size() == 2);
    }
    // Each subcase re-enters with a fresh `v`; if doctest's subcase machinery
    // were missing, one of the two CHECKs above would see the other's push.
}

TEST_CASE("string comparison reporting") {
    const std::string s = "doctest";
    REQUIRE(s.size() == 7);
    CHECK(s.substr(0, 3) == "doc");
}

// freedesktop.egl — behavioral test, runnable with no GPU and no display.
//
// Every FUNCTION and TYPE below comes from `import khronos.egl;`. <EGL/egl.h> is
// included for the EGL_* CONSTANTS only: they are macros, and no module can
// export a macro. So the file compiling is itself the first assertion — the
// module's export list has to cover everything used here — and the file
// linking is the second.
//
// ─────────────────────────────────────────────────────────────────────────
// EVERY ASSERTION HOLDS WITH ZERO VENDOR DRIVERS INSTALLED.
//
// libEGL is a DISPATCH: with no vendor it can answer questions about itself
// and nothing else. Upstream returns the empty string outright when the vendor
// list is empty (`libegl.c:928`), so an "it lists some EGL_EXT_ extension"
// check measures whether the MACHINE has a driver, not whether this package
// built libEGL. Vendor-dependent facts are reported below, or asserted only
// once their precondition is visibly met.
//
// ─────────────────────────────────────────────────────────────────────────
// THE PART THAT IS EASY TO GET FALSELY GREEN
//
// The ecosystem payload `xim:libglvnd` carries its own `libEGL.so.1` with the
// SAME soname, and on a machine with the graphics stack installed it is
// reachable. Only ONE library with a given soname is ever mapped, and nothing
// warns about the other — so a test that merely calls EGL functions can pass
// while this package's build is never loaded at all. Checks 2 and 3 pin the
// identity from both directions: what the library says it is, and what path
// its code actually came from. compat.libdrm's test does the same thing for
// the same reason.

#ifdef __linux__

#include <EGL/egl.h>   // the EGL_* macros only

#include <dlfcn.h>

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>

import khronos.egl;

namespace {

int failures = 0;

void check(bool ok, const char *what)
{
    std::printf("%-58s %s\n", what, ok ? "ok" : "FAILED");
    if (!ok) ++failures;
}

} // namespace

int main()
{
    // ── 1. The module carries the API ────────────────────────────────────
    EGLDisplay none = EGL_NO_DISPLAY;
    check(none == EGL_NO_DISPLAY, "EGLDisplay and EGL_NO_DISPLAY agree");

    // ── 2. It is GLVND's libEGL ──────────────────────────────────────────
    // EGL_VERSION on EGL_NO_DISPLAY is answered by libglvnd before any vendor
    // is consulted — a literal "1.5 libglvnd" — so it needs no driver and no
    // display, and a different implementation would answer differently.
    const char *version = eglQueryString(EGL_NO_DISPLAY, EGL_VERSION);
    check(version != nullptr && std::strcmp(version, "1.5 libglvnd") == 0,
          "eglQueryString(EGL_NO_DISPLAY, EGL_VERSION) is libglvnd's");
    std::printf("   EGL_VERSION: %s\n", version ? version : "(null)");

    // ── 3. …and it is THIS package's build, not the payload's ────────────
    // Same soname, so only one libEGL.so.1 is mapped and the loser is silent.
    // dladdr reports the object a symbol actually came from; if the path names
    // the ecosystem payload, this package built a library nobody loads.
    {
        Dl_info info{};
        const bool located =
            ::dladdr(reinterpret_cast<void *>(&eglQueryString), &info) != 0
            && info.dli_fname != nullptr;
        check(located, "dladdr locates the loaded libEGL");
        if (located) {
            const std::string from = info.dli_fname;
            std::printf("   loaded from: %s\n", from.c_str());
            check(from.find("xim-x-libglvnd") == std::string::npos,
                  "the loaded libEGL is not the ecosystem payload's copy");
        }
    }

    // ── 4. The error path works, with no driver ──────────────────────────
    // EGL_VENDOR without a display is invalid; libglvnd must report
    // EGL_BAD_DISPLAY rather than crash or silently answer. This exercises
    // __eglReportError and the thread-local error state.
    check(eglQueryString(EGL_NO_DISPLAY, EGL_VENDOR) == nullptr,
          "an invalid no-display query returns null");
    check(eglGetError() == EGL_BAD_DISPLAY,
          "…and leaves EGL_BAD_DISPLAY in the thread's error state");

    // ── 5. libEGL reaches libGLdispatch ──────────────────────────────────
    // Resolving a CORE entry point runs the path from libEGL into
    // libGLdispatch. That library is built by a sibling member of the same
    // fork and reached by PATH rather than through the index — so this is also
    // the check that the intra-package edge survived publication.
    check(eglGetProcAddress("eglInitialize") != nullptr,
          "eglGetProcAddress(\"eglInitialize\") resolves");
    check(eglGetProcAddress("eglNoSuchFunctionEXT") == nullptr,
          "…and a name that does not exist resolves to null");

    // ── 6. What the environment supplies, reported ───────────────────────
    // The package compiles in an EMPTY vendor-config default on purpose, so a
    // driver is only ever found through `__EGL_VENDOR_LIBRARY_DIRS`, which
    // `xim:mesa` declares (xim-pkgindex#713) exactly as it declares
    // GBM_BACKENDS_PATH for compat.libgbm. A runner with no GPU stack is not a
    // defect in this package, so none of this is asserted — but when a vendor
    // IS found, the extension list must look like one.
    std::puts("");
    const char *dirs = std::getenv("__EGL_VENDOR_LIBRARY_DIRS");
    std::printf("   __EGL_VENDOR_LIBRARY_DIRS = %s\n",
                dirs ? dirs : "(unset — the ecosystem declares it)");

    const char *client_exts = eglQueryString(EGL_NO_DISPLAY, EGL_EXTENSIONS);
    check(client_exts != nullptr,
          "eglQueryString(EGL_NO_DISPLAY, EGL_EXTENSIONS) answers");
    if (client_exts != nullptr && client_exts[0] != '\0') {
        std::printf("   client extensions: %.90s%s\n",
                    client_exts, std::strlen(client_exts) > 90 ? "…" : "");
        check(std::strstr(client_exts, "EGL_EXT_client_extensions") != nullptr,
              "a vendor was found, so the client extension list is populated");
    } else {
        std::puts("   client extensions: (none — no vendor driver here; the "
                  "dispatch itself is fine)");
    }

    std::printf("\n%d check(s) failed\n", failures);
    return failures == 0 ? 0 : 1;
}

#else

int main() { return 0; }

#endif

// Behavioral test: core (header-only) Eigen linear algebra. Returns non-zero on
// any mismatch. (The eigen_blas feature's dgemm_ path is covered separately;
// linking feature-built dependency objects into test binaries is a follow-up.)
#include <Eigen/Dense>
#include <cmath>

int main() {
    Eigen::Matrix2d A; A << 1, 2, 3, 4;
    Eigen::Vector2d x(1.0, 1.0);
    Eigen::Vector2d y = A * x;                              // [3,7]
    double det = A.determinant();                          // -2
    Eigen::Vector2d z = A.colPivHouseholderQr().solve(y);  // [1,1]
    bool ok = y(0) == 3.0 && y(1) == 7.0 && det == -2.0
              && std::abs(z(0) - 1.0) < 1e-9 && std::abs(z(1) - 1.0) < 1e-9;
    return ok ? 0 : 1;
}

// compat.eui-neo `app-main` FEATURE: there is no main() in this file on purpose.
// The entry point is upstream's core/app/glfw_app_main.cpp, which the feature
// adds to the library — it owns the window, the GL backend and the render loop,
// and calls back into the two symbols an EUI application must supply:
// app::dslAppConfig() and app::compose(). That is the whole shape being pinned
// here, and it is the shape a real EUI-NEO application uses.
//
// tests/examples/eui-neo-window asserts the OTHER half of the same feature pair:
// the same UI driven by a hand-written main(), with `app-main` NOT enabled.
//
// Two things make this member work under `mcpp test`:
//
//  1. The link IS the primary assertion. `main` has to come from the package;
//     if the feature ever stops gating glfw_app_main.cpp in, this member fails
//     with `undefined reference to 'main'`. Conversely, if the feature ever
//     stopped being opt-in, every OTHER member would fail with
//     `multiple definition of 'main'` — mcpp links a dependency's objects
//     eagerly, so there is no lazy-archive escape hatch.
//
//  2. Running a window needs a display, so the run is opt-in via
//     MCPP_RUN_WINDOW=1, as in tests/examples/imgui-window. Because the entry
//     point belongs to the package, the gate cannot live in main() — it lives in
//     a namespace-scope constructor, which runs before it. Headless CI links the
//     real binary, executes the guard, and exits 0.
//
// Builds on all three platforms: GLFW is upstream's default window backend
// everywhere, and nothing below is platform-specific.
#include <eui_neo.h>

#include "core/render/render_backend.h"

// GLFW would otherwise pull a GL header of its own choosing (GL/gl.h on Windows,
// the deprecated OpenGL/gl.h on macOS). EUI reaches GL through compat.glad, so
// this TU wants the GLFW API and nothing else — the same thing
// core/input/input_state.h does before its own include.
#ifndef GLFW_INCLUDE_NONE
#define GLFW_INCLUDE_NONE
#endif
#include <GLFW/glfw3.h>

import std;

namespace {

// Frames to render before asking the framework's loop to exit, so the opt-in run
// terminates on its own instead of waiting for a human to close the window.
constexpr int kFrameBudget = 60;

int g_frames = 0;

// Accumulated from the PREVIOUS frame's render stats — the framework's loop
// publishes them after each present(), and compose() is the only place an
// app-main consumer gets to look. A frame counter alone would pass against a
// null backend; these prove the OpenGL backend issued real geometry.
long long g_rectDraws = 0;
long long g_textDraws = 0;

// Runs before the package's main(). See point 2 above.
struct WindowRunGate {
    WindowRunGate() {
        if (std::getenv("MCPP_RUN_WINDOW") != nullptr) {
            return;
        }
        std::println("compat.eui-neo[app-main]: linked, main() supplied by the package; "
                     "window run is opt-in (MCPP_RUN_WINDOW=1)");
        std::exit(0);
    }
};

const WindowRunGate g_gate;

} // namespace

namespace app {

const DslAppConfig& dslAppConfig() {
    static const DslAppConfig config = DslAppConfig{}
        .title("compat.eui-neo — app-main")
        .pageId("eui_neo_app_main")
        .clearColor({0.06f, 0.07f, 0.09f, 1.0f})
        .windowSize(420, 240)
        .fps(60.0)
        .showDebugStatsInTitle(false);
    return config;
}

void compose(eui::Ui& ui, const eui::Screen& screen) {
    // A node carrying .onFrame() marks the runtime as animating, which is what
    // keeps the framework's loop rendering continuously instead of parking in
    // glfwWaitEvents(). It is also the only per-frame hook an app-main consumer
    // has, so the frame budget is enforced from here.
    ui.stack("loop.driver")
        .size(1.0f, 1.0f)
        .onFrame([](float deltaSeconds) {
            // app::update() runs the runtime twice per frame — the second pass
            // with deltaSeconds == 0, to settle the re-compose that onFrame
            // itself requested — so this fires twice per rendered frame.
            if (deltaSeconds <= 0.0f) {
                return;
            }

            const core::render::RenderFrameStats& stats = core::render::lastRenderFrameStats();
            g_rectDraws += stats.rectDraws;
            g_textDraws += stats.textDraws;

            if (++g_frames < kFrameBudget) {
                return;
            }

            // The entry point belongs to the package, so there is no main() of
            // ours to return a code from — exit() is how this member fails.
            if (g_rectDraws <= 0) {
                std::println("no rect geometry reached the backend over {} frames", g_frames);
                std::exit(2);
            }
            if (g_textDraws <= 0) {
                // Text needs the freetype path AND a usable font; worth
                // distinguishing from a dead backend.
                std::println("no text geometry reached the backend over {} frames "
                             "(freetype path or system font missing)", g_frames);
                std::exit(3);
            }

            std::println("compat.eui-neo[app-main]: ok ({} frames, {} rect / {} text draws)",
                         g_frames, g_rectDraws, g_textDraws);

            // The framework's loop keeps our window's context current across
            // update and render, so this is the window it is driving.
            if (GLFWwindow* window = glfwGetCurrentContext()) {
                glfwSetWindowShouldClose(window, GLFW_TRUE);
            }
        })
        .build();

    // Text exercises the freetype + font-fallback path, rects the OpenGL
    // primitive path — i.e. the parts a headless smoke test cannot reach.
    ui.text("title")
        .position(32.0f, 40.0f)
        .size(std::max(120.0f, screen.width - 64.0f), 30.0f)
        .text("app-main")
        .fontSize(22.0f)
        .lineHeight(28.0f)
        .color({0.94f, 0.96f, 1.0f, 1.0f})
        .build();

    ui.text("stats")
        .position(32.0f, 76.0f)
        .size(std::max(120.0f, screen.width - 64.0f), 24.0f)
        .text(std::format("frame {} / {}", g_frames, kFrameBudget))
        .fontSize(15.0f)
        .lineHeight(20.0f)
        .color({0.58f, 0.68f, 0.80f, 1.0f})
        .build();

    const float progress = static_cast<float>(g_frames) / static_cast<float>(kFrameBudget);
    const float trackWidth = std::max(120.0f, screen.width - 64.0f);

    ui.rect("track")
        .position(32.0f, 150.0f)
        .size(trackWidth, 6.0f)
        .radius(3.0f)
        .color({0.16f, 0.19f, 0.24f, 1.0f})
        .build();

    ui.rect("fill")
        .position(32.0f, 150.0f)
        .size(std::min(1.0f, progress) * trackWidth, 6.0f)
        .radius(3.0f)
        .color({0.36f, 0.62f, 0.98f, 1.0f})
        .build();
}

} // namespace app

// POSITIVE verification for compat.eui-neo's `markdown` feature.
//
// components/markdown.h is header-only and compiles one of two definitions of
// detail::parseMarkdownBlocks depending on EUI_HAS_MD4C. That makes it a clean
// probe for something the descriptor cannot otherwise prove: the feature's
// `defines` really do reach the CONSUMER's translation unit, not just the
// package's own. Without propagation this member would link md4c and still
// silently get the fallback parser.
//
// tests/examples/eui-neo asserts the negative side — same header, feature off,
// degenerate single-Paragraph result.
#include <eui_neo.h>
import std;

namespace app {

const DslAppConfig& dslAppConfig() {
    static const DslAppConfig config = DslAppConfig{}.title("markdown feature test");
    return config;
}

void compose(eui::Ui&, const eui::Screen&) {}

} // namespace app

int main() {
#if !defined(EUI_HAS_MD4C)
    std::println("EUI_HAS_MD4C not defined — the feature's interface define did not propagate");
    return 1;
#else
    namespace md = components::detail;

    const auto blocks = md::parseMarkdownBlocks("# Heading\n\nBody text.\n");

    // The real parser splits heading from paragraph; the fallback returns one
    // Paragraph holding the raw source.
    if (blocks.size() < 2) {
        std::println("expected >= 2 blocks from the md4c parser, got {}", blocks.size());
        return 2;
    }
    if (blocks[0].kind != md::MarkdownBlockKind::Heading || blocks[0].headingLevel != 1) {
        std::println("expected an h1 first block, got kind={} level={}",
                     static_cast<int>(blocks[0].kind), blocks[0].headingLevel);
        return 3;
    }
    if (md::plainText(blocks[0].runs) != "Heading") {
        std::println("unexpected heading text: '{}'", md::plainText(blocks[0].runs));
        return 4;
    }

    std::println("compat.eui-neo[markdown]: ok ({} blocks, h1 = '{}')",
                 blocks.size(), md::plainText(blocks[0].runs));
    return 0;
#endif
}

// Verify compat.eui-neo's `sdl2` window backend and `network` feature.
//
// Both are asserted at COMPILE time first, because both fail silently at
// runtime otherwise: a window backend that did not switch just uses GLFW, and
// `network` that did not switch leaves core/platform/network.cpp compiled as
// stubs that return failure. Neither shows up without a display or a network.
#include <eui_neo.h>
// SDL_MAIN_HANDLED before <SDL.h>: on Windows SDL_main.h does
// `#define main SDL_main` and expects the real entry point to come from
// SDL2main (src/main/windows/SDL_windows_main.c). This package does not ship
// that — a library consumer should not be handed an entry point — so the test
// takes SDL's documented alternative and keeps its own main, pairing it with
// SDL_SetMainReady() below. Without this the link fails with
// "LNK1561: entry point must be defined".
#define SDL_MAIN_HANDLED
#include <SDL.h>
#include <curl/curl.h>
import std;

#if !defined(EUI_WINDOW_BACKEND_SDL2)
#error "sdl2 feature requested but EUI_WINDOW_BACKEND_SDL2 is not defined"
#endif
#if !defined(EUI_HAS_CURL)
#error "network feature requested but EUI_HAS_CURL is not defined"
#endif

namespace app {

const DslAppConfig& dslAppConfig() {
    static const DslAppConfig config = DslAppConfig{}.title("sdl2 + network test");
    return config;
}

void compose(eui::Ui&, const eui::Screen&) {}

} // namespace app

int main() {
    // SDL's dummy driver is a real driver, so unlike the GL/Vulkan backends
    // this actually runs: init, create, query, tear down.
    SDL_SetMainReady();
    SDL_SetHint(SDL_HINT_VIDEODRIVER, "dummy");
    if (SDL_Init(SDL_INIT_VIDEO) != 0) {
        std::println("SDL_Init failed: {}", SDL_GetError());
        return 1;
    }
    SDL_Window* window = SDL_CreateWindow("eui-neo", SDL_WINDOWPOS_UNDEFINED,
                                          SDL_WINDOWPOS_UNDEFINED, 200, 100,
                                          SDL_WINDOW_HIDDEN);
    if (window == nullptr) {
        std::println("SDL_CreateWindow failed: {}", SDL_GetError());
        SDL_Quit();
        return 2;
    }
    const char* driver = SDL_GetCurrentVideoDriver();
    SDL_DestroyWindow(window);
    SDL_Quit();

    // libcurl came in through the feature's dependency, and it has TLS — the
    // thing EUI-NEO's downloader needs and the thing a misconfigured curl
    // silently lacks. No connection is made.
    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        std::println("curl_global_init failed");
        return 3;
    }
    const curl_version_info_data* curlInfo = curl_version_info(CURLVERSION_NOW);
    const bool haveTls = curlInfo != nullptr &&
                         (curlInfo->features & CURL_VERSION_SSL) != 0 &&
                         curlInfo->ssl_version != nullptr;
    curl_global_cleanup();
    if (!haveTls) {
        std::println("libcurl reached us without TLS");
        return 4;
    }

    // Still eui-neo underneath — a headless facade from the base source set.
    eui::json::Document doc;
    if (!doc.parse(R"({"window": "sdl2"})")) {
        std::println("parse failed: {}", doc.error().message);
        return 5;
    }
    std::string windowBackend;
    if (!doc.stringAt("/window", windowBackend) || windowBackend != "sdl2") {
        std::println("unexpected /window: '{}'", windowBackend);
        return 6;
    }

    std::println("compat.eui-neo[sdl2,network]: ok (SDL driver={}, curl {} ssl={})",
                 driver, curlInfo->version, curlInfo->ssl_version);
    return 0;
}

// compat.eui-neo's SYSTEM TRAY, through the public C++ surface.
//
// This is the shape a consumer should copy. `core::platform` exposes the whole
// tray as six free functions and a two-field options struct, and none of it
// needs a window, a GL context, or the DSL app loop -- a tray-only utility is
// the ten lines in runTray() below. The raw C bridge in
// core/platform/tray_bridge.h is an implementation detail and is not used here.
//
// WHY THIS MEMBER EXISTS, and why the assertion is the shape it is.
//
// tray_bridge.c selects one of four backends at preprocessor level --
// EUI_TRAY_WINAPI, EUI_TRAY_APPKIT, EUI_TRAY_SNI, EUI_TRAY_APPINDICATOR -- and
// falls through to an `#else` stub when none is defined. THE STUB DEFINES ALL
// SIX SYMBOLS and returns 0 from every one of them. A descriptor that lost its
// backend define would still compile, still link, and still pass all six other
// eui-neo members, while the tray silently stopped existing: "no tray" and "not
// tested" would read identically. That is the failure this member is built
// against.
//
// Two criteria were tried and only the second one works:
//
//   * `dlsym(RTLD_DEFAULT, "g_bus_get_sync") != nullptr` -- BLUNT, verified by
//     rebuilding with the define removed and watching it pass anyway. The
//     descriptor's `ldflags` carry `-lgio-2.0` unconditionally, so gio is in
//     DT_NEEDED and its symbols resolve whether or not the SNI arm was
//     compiled. It answered "is gio linked", not "is the backend real".
//
//   * initializeTray() under a session bus -- SHARP. Measured both ways on a
//     bare `dbus-run-session` with no panel and no display: the real backend
//     returns true (it exports its StatusNotifierItem object and waits for a
//     watcher), the stub returns false unconditionally.
//
// So on linux this test supplies its own private bus and asserts the tray comes
// up. It needs no display, no panel, and no desktop session, which is what lets
// it run on an ordinary CI runner.
//
// Windows and macOS get compile-and-link coverage only. Their backends are
// unconditional in the descriptor, and neither has an equivalent cheap probe
// that a headless runner can perform.

#include "core/platform/platform.h"

#if defined(__linux__)
#include <limits.h>
#include <unistd.h>
#endif

import std;

namespace {

// What a consumer actually writes. Everything else in this file is about
// proving the backend is real; this is the feature.
int runTray() {
    core::platform::TrayOptions options;
    options.tooltip  = "EUI NEO tray example";
    options.iconPath = "";   // empty: the panel substitutes a placeholder icon

    if (!core::platform::initializeTray(options)) {
        std::println("tray unavailable (no session bus)");
        return 1;
    }

    std::println("tray is live -- right click it for Show / Exit");
    while (!core::platform::consumeTrayExitRequested()) {
        core::platform::pollTray(false);
        if (core::platform::consumeTrayShowRequested()) std::println("  -> Show");
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }

    core::platform::shutdownTray();
    std::println("tray shut down");
    return 0;
}

#if defined(__linux__)
// Re-run this same executable with a private session bus around it. Returns
// only on failure; on success `dbus-run-session` replaces this process and the
// second entry takes the branch below it.
void reexec_under_private_bus(const char* marker) {
    ::setenv(marker, "1", 1);

    char self[PATH_MAX];
    const ssize_t n = ::readlink("/proc/self/exe", self, sizeof(self) - 1);
    if (n <= 0) return;
    self[n] = '\0';

    char* const argv[] = { const_cast<char*>("dbus-run-session"),
                           const_cast<char*>("--"), self, nullptr };
    ::execvp("dbus-run-session", argv);
}
#endif

} // namespace

int main() {
    // Safe on every platform and before any backend has been touched: the state
    // is a plain bool and the stub's eui_tray_is_initialized() also returns 0.
    // This pins the query, not the backend.
    if (core::platform::isTrayInitialized()) {
        std::println(stderr, "isTrayInitialized() is true before initializeTray()");
        return 1;
    }

    if (std::getenv("MCPP_RUN_TRAY") != nullptr) return runTray();

#if defined(__linux__)
    constexpr const char* kMarker = "EUI_TRAY_TEST_HAS_BUS";

    if (std::getenv("DBUS_SESSION_BUS_ADDRESS") == nullptr) {
        if (std::getenv(kMarker) != nullptr) {
            // dbus-run-session ran but produced no bus address. Do not report
            // this as a pass: an unverifiable backend is exactly what this
            // member exists to prevent.
            std::println(stderr,
                         "dbus-run-session left no DBUS_SESSION_BUS_ADDRESS, so "
                         "the linux tray backend could not be verified");
            return 1;
        }
        reexec_under_private_bus(kMarker);
        std::println(stderr,
                     "could not exec dbus-run-session, so the linux tray backend "
                     "could not be verified. It ships with dbus; install that "
                     "package on this runner.");
        return 1;
    }

    // THE ASSERTION. True only when tray_bridge.c compiled a real backend --
    // the EUI_TRAY_HAS_BACKEND=0 stub returns 0 here no matter what the bus is.
    core::platform::TrayOptions options;
    options.tooltip = "compat.eui-neo tray smoke test";
    if (!core::platform::initializeTray(options)) {
        std::println(stderr,
                     "compat.eui-neo was built WITHOUT its linux tray backend: a "
                     "session bus is present, yet initializeTray() failed, which "
                     "is what tray_bridge.c's EUI_TRAY_HAS_BACKEND=0 stub does "
                     "unconditionally. Expected -DEUI_TRAY_SNI=1 and glib on the "
                     "link line (see pkgs/e/compat.eui-neo.lua).");
        return 1;
    }

    if (!core::platform::isTrayInitialized()) {
        std::println(stderr, "initializeTray() succeeded but isTrayInitialized() is false");
        return 1;
    }
    core::platform::shutdownTray();
    std::println("linux tray backend verified over a private session bus");
#else
    std::println("tray path compiled and linked; run with MCPP_RUN_TRAY=1 to show it");
#endif
    return 0;
}

// Verify compat.eui-neo's `vulkan` feature actually swaps the render backend.
//
// Two things have to hold, and only one of them is about Vulkan:
//
//  1. The backend define really flipped. EUI_RENDER_BACKEND_VULKAN must be
//     visible here and EUI_RENDER_BACKEND_OPENGL must NOT — if `default` had
//     leaked through alongside the explicit feature, both would be set and
//     core/render/render_backend.cpp would have silently compiled the OpenGL
//     path (its dispatch is `#if OPENGL … #elif VULKAN`, so OpenGL wins).
//     That failure is invisible at runtime without a GPU, so it is asserted at
//     COMPILE time below.
//
//  2. The Vulkan translation units are linked. compat.vulkan's loader entry
//     points must resolve from a consumer that reached them through eui-neo's
//     feature-scoped dependency, not through a direct one.
//
// Everything else about the Vulkan backend needs a device, a surface and a
// window, none of which exist on a CI runner — see the design doc.
//
// HAVE_EUI_VULKAN is set by THIS project's own [target.'cfg(...)'.build]
// cxxflags: compat.vulkan has no windows build, so on windows the member takes
// the default OpenGL configuration instead and asserts THAT.
#include <eui_neo.h>
#if defined(HAVE_EUI_VULKAN)
#include <vulkan/vulkan.h>
#endif
import std;

#if defined(HAVE_EUI_VULKAN)
#  if !defined(EUI_RENDER_BACKEND_VULKAN)
#    error "vulkan feature requested but EUI_RENDER_BACKEND_VULKAN is not defined"
#  endif
#  if defined(EUI_RENDER_BACKEND_OPENGL)
#    error "EUI_RENDER_BACKEND_OPENGL leaked in alongside the vulkan feature"
#  endif
#else
// The default (OpenGL) build publishes NO interface define — the package
// resolves it in its own preprocessor, which the consumer never sees. So the
// only thing assertable from here is the absence of the vulkan one.
#  if defined(EUI_RENDER_BACKEND_VULKAN)
#    error "EUI_RENDER_BACKEND_VULKAN present without the vulkan feature"
#  endif
#endif

namespace app {

const DslAppConfig& dslAppConfig() {
    static const DslAppConfig config = DslAppConfig{}.title("vulkan backend test");
    return config;
}

void compose(eui::Ui&, const eui::Screen&) {}

