int main() {
    // The loader answers this without any ICD, so it is safe on a driverless
    // runner while still proving compat.vulkan came along with the feature.
#if defined(HAVE_EUI_VULKAN)
    std::uint32_t apiVersion = 0;
    if (vkEnumerateInstanceVersion(&apiVersion) != VK_SUCCESS) {
        std::println("vkEnumerateInstanceVersion failed");
        return 1;
    }
#endif

    // Still the eui-neo library underneath: assert on a headless facade that
    // lives in core/platform/json.cpp, so a build that dropped the base
    // sources while chasing the feature fails here.
    eui::json::Document doc;
    if (!doc.parse(R"({"backend": "vulkan"})")) {
        std::println("parse failed: {}", doc.error().message);
        return 2;
    }
    std::string backend;
    if (!doc.stringAt("/backend", backend) || backend != "vulkan") {
        std::println("unexpected /backend: '{}'", backend);
        return 3;
    }

#if defined(HAVE_EUI_VULKAN)
    std::println("compat.eui-neo[vulkan]: ok (backend={}, loader api {}.{}.{})",
                 backend, VK_VERSION_MAJOR(apiVersion), VK_VERSION_MINOR(apiVersion),
                 VK_VERSION_PATCH(apiVersion));
#else
    std::println("compat.eui-neo[vulkan]: skipped, default opengl build asserted instead (parsed {})",
                 backend);
#endif
    return 0;
}

// compat.eui-neo with a HAND-WRITTEN main(): the own-main shape, and the only
// place in this index that builds an eui-neo window.
//
// tests/examples/eui-neo covers the headless surface (json, platform flags) and
// tests/examples/eui-neo-app-main covers the framework-main shape. What is left,
// and what this member pins, is everything between window creation and a
// presented frame: core::window::createWindow(), the OpenGL render backend,
// app::initialize/update/render, ScopedRenderBackend, and the freetype text path.
//
// Without `app-main` the package contributes no entry point, so the five things
// upstream's glfw_app_main.cpp does have to be done by hand — see runWindow().
// That is the point: a consumer must be able to drive EUI itself, and the public
// surface it needs (core::window, core::render, app::*) must actually be reachable
// through the descriptor's include_dirs.
//
// The window run needs a display, so it is opt-in via MCPP_RUN_WINDOW=1, exactly
// as in tests/examples/imgui-window. Headless CI compiles and links the whole
// loop — which is where a descriptor regression would surface — and returns 0.
//
// Builds on all three platforms. Every core/ header below is platform-clean (no
// windows.h, no Cocoa, no GL), and every GLFW entry point used here is portable,
// so there is no reason to cfg-gate this the way the X11-consuming members are.
#include <eui_neo.h>

// 0.5.6 dropped `eui/detail/dsl_app_impl.h` from the umbrella `eui_neo.h`
// (upstream scoped it to the app-main entry points, which include it directly).
// This member is the OWN-main shape — nothing in the package drives the loop —
// so app::initialize/update/render/shutdown are emitted HERE by including the
// impl header, exactly as upstream's core/app/glfw_app_main.cpp does.
#include "eui/detail/dsl_app_impl.h"

#include "core/input/input_state.h"
#include "core/platform/platform.h"
#include "core/render/render_backend.h"
#include "core/window/window_backend.h"

// GLFW would otherwise pull a GL header of its own choosing (GL/gl.h on Windows,
// the deprecated OpenGL/gl.h on macOS). EUI reaches GL through compat.glad, so
// this TU wants the GLFW API and nothing else — the same thing
// core/input/input_state.h does before its own include.
#ifndef GLFW_INCLUDE_NONE
#define GLFW_INCLUDE_NONE
#endif
#include <GLFW/glfw3.h>

import std;

namespace {

// Rendered frames to require before exiting, so the opt-in run terminates on its
// own. Also the assertion: fewer than this means the loop stalled.
constexpr int kFrameBudget = 60;

struct Loop {
    float elapsed = 0.0f;
    int frames = 0;
    // Accumulated from core::render::lastRenderFrameStats(). A frame counter only
    // proves app::update() ran — these prove the OpenGL backend actually issued
    // geometry, i.e. that the render half is wired too. Without them this member
    // would pass just as happily against a null backend.
    long long rectDraws = 0;
    long long textDraws = 0;
};

Loop g_loop;

} // namespace

namespace app {

const DslAppConfig& dslAppConfig() {
    static const DslAppConfig config = DslAppConfig{}
        .title("compat.eui-neo — own main")
        .pageId("eui_neo_own_main")
        .clearColor({0.06f, 0.07f, 0.09f, 1.0f})
        .windowSize(420, 240)
        .fps(60.0)
        .showDebugStatsInTitle(false);
    return config;
}

void compose(eui::Ui& ui, const eui::Screen& screen) {
    // A node carrying .onFrame() marks the runtime as animating, which is what
    // turns a redraw-on-demand retained-mode UI into a continuously running loop.
    ui.stack("loop.driver")
        .size(1.0f, 1.0f)
        .onFrame([](float deltaSeconds) {
            // app::update() runs the runtime twice per frame — the second pass
            // with deltaSeconds == 0, to settle the re-compose that onFrame
            // itself requested — so this fires twice per rendered frame.
            if (deltaSeconds <= 0.0f) {
                return;
            }
            g_loop.elapsed += deltaSeconds;
            ++g_loop.frames;
        })
        .build();

    // Text exercises the freetype + font-fallback path, rects the OpenGL
    // primitive path.
    const float trackWidth = std::max(120.0f, screen.width - 64.0f);

    ui.text("title")
        .position(32.0f, 40.0f)
        .size(trackWidth, 30.0f)
        .text("own main")
        .fontSize(22.0f)
        .lineHeight(28.0f)
        .color({0.94f, 0.96f, 1.0f, 1.0f})
        .build();

    ui.text("stats")
        .position(32.0f, 76.0f)
        .size(trackWidth, 24.0f)
        .text(std::format("frame {} / {}   t = {:.2f}s", g_loop.frames, kFrameBudget, g_loop.elapsed))
        .fontSize(15.0f)
        .lineHeight(20.0f)
        .color({0.58f, 0.68f, 0.80f, 1.0f})
        .build();

    const float progress = static_cast<float>(g_loop.frames) / static_cast<float>(kFrameBudget);

    ui.rect("track")
        .position(32.0f, 150.0f)
        .size(trackWidth, 6.0f)
        .radius(3.0f)
        .color({0.16f, 0.19f, 0.24f, 1.0f})
        .build();

    ui.rect("fill")
        .position(32.0f, 150.0f)
        .size(std::min(1.0f, progress) * trackWidth, 6.0f)
        .radius(3.0f)
        .color({0.98f, 0.55f, 0.36f, 1.0f})
        .build();
}

} // namespace app

namespace {

float dpiScaleOf(GLFWwindow* window) {
    float scaleX = 1.0f;
    float scaleY = 1.0f;
    glfwGetWindowContentScale(window, &scaleX, &scaleY);
    return (scaleX + scaleY) * 0.5f;
}

// Framebuffer pixels per window point; EUI needs it to map cursor coordinates
// onto the framebuffer.
float pointerScaleOf(GLFWwindow* window) {
    int windowWidth = 0;
    int windowHeight = 0;
    int framebufferWidth = 0;
    int framebufferHeight = 0;
    glfwGetWindowSize(window, &windowWidth, &windowHeight);
    glfwGetFramebufferSize(window, &framebufferWidth, &framebufferHeight);
    if (windowWidth <= 0 || windowHeight <= 0) {
        return 1.0f;
    }
    return 0.5f * (static_cast<float>(framebufferWidth) / static_cast<float>(windowWidth) +
                   static_cast<float>(framebufferHeight) / static_cast<float>(windowHeight));
}

int runWindow() {
    core::platform::repairCurrentWorkingDirectory();
    core::render::initializeRenderBackendLoader();

    glfwSetErrorCallback([](int code, const char* description) {
        std::println("glfw error {}: {}", code, description != nullptr ? description : "");
    });

    if (!glfwInit()) {
        std::println("glfwInit() failed");
        return 10;
    }

    const app::DslAppConfig& config = app::dslAppConfig();

    core::window::WindowCreateRequest request;
    request.width = config.windowWidthValue;
    request.height = config.windowHeightValue;
    request.title = config.titleValue.c_str();
    request.renderApi = core::render::windowRenderApi();

    auto* window = static_cast<GLFWwindow*>(core::window::createWindow(request));
    if (window == nullptr) {
        std::println("core::window::createWindow() failed");
        glfwTerminate();
        return 11;
    }

    auto backend = core::render::createRenderBackend(window);
    if (!backend || !backend->initialize()) {
        std::println("core::render::createRenderBackend() failed");
        core::window::destroyWindow(window);
        glfwTerminate();
        return 12;
    }

    if (!app::initialize(window)) {
        std::println("app::initialize() failed");
        backend.reset();
        core::window::destroyWindow(window);
        glfwTerminate();
        return 13;
    }

    // Frame pacing is NOT optional in a hand-written loop: the OpenGL backend
    // calls glfwSwapInterval(0) in initialize(), so present() never blocks on
    // vsync and an unpaced loop runs at thousands of fps and pins a core.
    // Upstream's main does the same thing with monitor refresh-rate detection on
    // top.
    const double frameInterval = config.fpsValue > 0.0 ? 1.0 / config.fpsValue : 0.0;
    double lastFrameTime = core::window::timeSeconds();
    double nextFrameTime = lastFrameTime;

    while (!glfwWindowShouldClose(window) && g_loop.frames < kFrameBudget) {
        glfwPollEvents();

        const double now = core::window::timeSeconds();
        const float deltaSeconds = static_cast<float>(now - lastFrameTime);
        lastFrameTime = now;

        int framebufferWidth = 0;
        int framebufferHeight = 0;
        glfwGetFramebufferSize(window, &framebufferWidth, &framebufferHeight);
        if (framebufferWidth <= 0 || framebufferHeight <= 0) {
            glfwWaitEvents();
            lastFrameTime = core::window::timeSeconds();
            nextFrameTime = lastFrameTime;
            continue;
        }

        const float dpiScale = dpiScaleOf(window);
        const float pointerScale = pointerScaleOf(window);

        backend->makeCurrent();

        // Layout + compose() + input dispatch; also fires the .onFrame()
        // callback that advances g_loop.
        app::update(window, deltaSeconds, framebufferWidth, framebufferHeight, dpiScale, pointerScale);

        backend->beginFrame({
            window,
            core::window::nativeWindowInfo(window),
            framebufferWidth,
            framebufferHeight,
            dpiScale
        });
        {
            // app::render() draws through core::render::activeRenderBackend();
            // this guard is what installs ours as the active one. Without it the
            // frame is silently dropped.
            core::render::ScopedRenderBackend scopedBackend(*backend);
            app::render(framebufferWidth, framebufferHeight, dpiScale);
        }
        backend->present();

        // app::render() -> Runtime::render() calls beginRenderFrameStats(); this
        // moves the counters into lastRenderFrameStats() so they can be read.
        core::render::publishRenderFrameStats();
        const core::render::RenderFrameStats& stats = core::render::lastRenderFrameStats();
        g_loop.rectDraws += stats.rectDraws;
        g_loop.textDraws += stats.textDraws;

        nextFrameTime += frameInterval;
        const double slack = nextFrameTime - core::window::timeSeconds();
        if (slack > 0.0) {
            std::this_thread::sleep_for(std::chrono::duration<double>(slack));
        } else {
            // Fell behind: resynchronise instead of accumulating debt.
            nextFrameTime = core::window::timeSeconds();
        }
    }

    core::releaseInputQueue(window);
    backend->makeCurrent();
    backend->releaseRenderCache();
    {
        core::render::ScopedRenderBackend scopedBackend(*backend);
        app::shutdown();
    }
    backend.reset();
    core::window::destroyWindow(window);
    glfwTerminate();

    if (g_loop.frames < kFrameBudget) {
        std::println("loop stalled: {} of {} frames in {:.2f}s",
                     g_loop.frames, kFrameBudget, g_loop.elapsed);
        return 14;
    }
    if (g_loop.rectDraws <= 0) {
        std::println("no rect geometry reached the backend over {} frames", g_loop.frames);
        return 15;
    }
    if (g_loop.textDraws <= 0) {
        // Text needs the freetype path AND a usable font. On a box with no
        // system font at any of upstream's Linux fallback paths this is the
        // failure you get, and it is worth distinguishing from a dead backend.
        std::println("no text geometry reached the backend over {} frames "
                     "(freetype path or system font missing)", g_loop.frames);
        return 16;
    }

    std::println("compat.eui-neo[own main]: ok ({} frames in {:.2f}s, {} rect / {} text draws)",
                 g_loop.frames, g_loop.elapsed, g_loop.rectDraws, g_loop.textDraws);
    return 0;
}

} // namespace

int main() {
    // Compiling + linking runWindow() is the headless test: it is the only thing
    // in this index that instantiates core::window / core::render / app::* from a
    // consumer TU. The run itself needs a display (opt-in).
    if (std::getenv("MCPP_RUN_WINDOW") != nullptr) {
        return runWindow();
    }
    std::println("compat.eui-neo[own main]: linked; window run is opt-in (MCPP_RUN_WINDOW=1)");
    return 0;
}

// Behavioral test — verify compat.eui-neo builds, exposes its umbrella header
// to a Form A consumer, and links against real symbols from the built lib.
//
// `#include <eui_neo.h>` is the whole point of the header-compat shape. The
// umbrella declares the DSL app surface (eui/dsl_app.h) and leaves two symbols
// for the application to supply — app::dslAppConfig() and app::compose().
// Since 0.5.6 the umbrella no longer pulls in eui/detail/dsl_app_impl.h (the
// impl lives in the app-main entry points instead), but THIS TU only defines
// the two app symbols and never calls app::initialize/update/render — so it
// links without the impl header, and defining the app symbols is exactly what
// upstream's examples/*.cpp do, making this test a faithful minimal consumer.
//
// The assertion itself runs on eui::json::Document: it lives in
// core/platform/json.cpp, so a package that compiled zero translation units
// fails at LINK time instead of silently passing — which is how an earlier
// revision of this descriptor shipped an empty lib behind a green CI. It is
// also the cheapest entry point that is genuinely headless (no window, no GL
// context), which matters because CI runners have no display.
#include <eui_neo.h>
import std;

namespace app {

const DslAppConfig& dslAppConfig() {
    static const DslAppConfig config = DslAppConfig{}
        .title("compat.eui-neo smoke test")
        .windowSize(320, 240);
    return config;
}

// Never invoked: the test asserts on the headless JSON facade instead of
// entering the render loop. It exists so the DSL app skeleton links.
void compose(eui::Ui&, const eui::Screen&) {}

} // namespace app

int main() {
    // The umbrella header really did reach us, with the DSL app config intact.
    if (app::dslAppConfig().windowWidthValue != 320) {
        std::println("dslAppConfig() not wired: width={}", app::dslAppConfig().windowWidthValue);
        return 1;
    }

    eui::json::Document doc;
    if (!doc.parse(R"({"framework": {"name": "eui-neo", "version": 3}})")) {
        std::println("parse failed: {}", doc.error().message);
        return 2;
    }

    std::string name;
    if (!doc.stringAt("/framework/name", name) || name != "eui-neo") {
        std::println("unexpected /framework/name: '{}'", name);
        return 3;
    }

    // number() rather than signedInteger(): yyjson tags a positive literal as
    // an UNSIGNED integer, so yyjson_is_sint() — and therefore
    // Value::signedInteger() — is false for `3`.
    double version = 0.0;
    if (!doc.atPointer("/framework/version").number(version) || version != 3.0) {
        std::println("unexpected /framework/version: {}", version);
        return 4;
    }

    // Forces core/platform/platform.cpp into the link. That TU emits
    // `platform.o`, which collides with compat.glfw's src/platform.c in mcpp's
    // flat per-link obj/ directory (mcpp#233/#240) and used to be dropped
    // silently — the descriptor now routes it through a uniquely named
    // generated stub. Referencing a symbol only that TU defines turns a
    // regression into an undefined reference instead of a passing test.
    // Read-only on purpose: requestFrame() would reach glfwPostEmptyEvent()
    // with no window, and CI runners are headless. Both flags start clear.
    if (core::platform::consumeFrameRequest() || core::platform::consumeUiUpdate()) {
        std::println("platform frame flags did not start clear");
        return 5;
    }

    // NEGATIVE verification for the `markdown` feature, which is NOT requested
    // by this member. components/markdown.h ships two definitions of
    // parseMarkdownBlocks: the md4c one, and — when EUI_HAS_MD4C is absent — a
    // degenerate fallback that wraps the entire source in a single Paragraph.
    // Getting the fallback here proves the feature's interface define really is
    // gated off by default. tests/examples/eui-neo-markdown asserts the other
    // side of the same switch.
    const auto blocks = components::detail::parseMarkdownBlocks("# Heading\n\nBody text.\n");
    if (blocks.size() != 1 || blocks[0].kind != components::detail::MarkdownBlockKind::Paragraph) {
        std::println("markdown feature leaked into the default build: {} block(s)", blocks.size());
        return 6;
    }

    std::println("compat.eui-neo smoke test: ok (parsed {} v{}, markdown gated off)", name, version);
    return 0;
}

// compat.expat — behavioral test. It parses a document rather than checking
// that symbols resolve, because the interesting failures are configuration
// ones: XML_DTD, XML_GE and XML_NS are feature switches compiled into
// expat_config.h, and getting them wrong yields a parser that links perfectly
// and then rejects (or mis-splits) input.

#ifdef __linux__

#include <expat.h>

#include <dlfcn.h>
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

namespace {

int failures = 0;

void check(bool ok, const char *what)
{
    std::printf("%-58s %s\n", what, ok ? "ok" : "FAILED");
    if (!ok) ++failures;
}

struct Collected {
    std::vector<std::string> elements;
    std::string text;
};

void XMLCALL on_start(void *ud, const XML_Char *name, const XML_Char **atts)
{
    auto *c = static_cast<Collected *>(ud);
    c->elements.emplace_back(name);
    for (int i = 0; atts != nullptr && atts[i] != nullptr; i += 2) {
        c->elements.emplace_back(std::string("@") + atts[i] + "=" + atts[i + 1]);
    }
}

void XMLCALL on_text(void *ud, const XML_Char *s, int len)
{
    static_cast<Collected *>(ud)->text.append(s, static_cast<std::size_t>(len));
}

} // namespace

int main()
{
    // ── 1. A namespaced parse, which is XML_NS ───────────────────────────
    // The separator argument only does anything when XML_NS was compiled in;
    // without it the element name comes back as "w:seat" instead of the
    // expanded "urn:test|seat", and wayland-scanner would misread every
    // protocol file.
    {
        Collected c;
        XML_Parser p = XML_ParserCreateNS(nullptr, '|');
        check(p != nullptr, "XML_ParserCreateNS returns a parser");
        XML_SetUserData(p, &c);
        XML_SetElementHandler(p, on_start, nullptr);
        XML_SetCharacterDataHandler(p, on_text);

        static const char doc[] =
            "<w:proto xmlns:w='urn:test'><w:seat name='seat0'>hi</w:seat></w:proto>";
        const bool ok = XML_Parse(p, doc, (int)std::strlen(doc), 1) == XML_STATUS_OK;
        check(ok, "XML_Parse accepts a namespaced document");
        check(c.elements.size() >= 2 && c.elements[0] == "urn:test|proto",
              "XML_NS expanded the prefix (urn:test|proto)");
        check(c.text == "hi", "character data reached the handler");
        XML_ParserFree(p);
    }

    // ── 2. An internal DTD entity, which is XML_DTD + XML_GE ─────────────
    // Built without general-entity support this parse fails outright, so it
    // separates a correct expat_config.h from a plausible one.
    {
        Collected c;
        XML_Parser p = XML_ParserCreate(nullptr);
        XML_SetUserData(p, &c);
        XML_SetCharacterDataHandler(p, on_text);

        static const char doc[] =
            "<!DOCTYPE r [<!ENTITY who 'wayland'>]><r>&who;</r>";
        const bool ok = XML_Parse(p, doc, (int)std::strlen(doc), 1) == XML_STATUS_OK;
        check(ok, "XML_Parse accepts an internal DTD entity");
        check(c.text == "wayland", "the general entity expanded to 'wayland'");
        XML_ParserFree(p);
    }

    // ── 3. Malformed input is rejected ───────────────────────────────────
    {
        XML_Parser p = XML_ParserCreate(nullptr);
        static const char bad[] = "<a><b></a>";
        check(XML_Parse(p, bad, (int)std::strlen(bad), 1) == XML_STATUS_ERROR,
              "mismatched tags are an error, not silence");
        XML_ParserFree(p);
    }

    // ── 4. It is THIS build that ran ─────────────────────────────────────
    // The package is `kind = "lib"`, so these objects are merged into the
    // consumer and dladdr reports the EXECUTABLE. The check that matters is
    // the same either way: the code that just parsed must not have come from
    // the ecosystem's `xim:expat`, which is present whenever Mesa is and would
    // otherwise answer silently.
    //
    // A STATICALLY LINKED BINARY CANNOT ANSWER THIS, AND THAT IS NOT A
    // FAILURE. musl's `dladdr` is `weak_alias(stub_dladdr, dladdr)` returning
    // 0 (src/ldso/dladdr.c); the dynamic loader overrides it, and a static
    // link has no loader to do so. An openkal program is statically linked, so
    // the call returns 0 for every address, and the risk this check exists for
    // cannot arise there either: nothing was loaded at runtime, so the only
    // expat in the process is the one that was linked in.
    //
    // SKIPPING IT SILENTLY WOULD MAKE "no loader" AND "the loader answered
    // wrongly" THE SAME READING, so the fallback asserts what distinguishes
    // them. `main` is in this executable by construction; if `dladdr` cannot
    // locate that either, there is no dynamic symbol information at all and
    // the question is moot. If it locates `main` but not `XML_ParserCreate`,
    // something is wrong and the check fails as before.
    {
        Dl_info info{};
        const bool located =
            ::dladdr(reinterpret_cast<void *>(&XML_ParserCreate), &info) != 0
            && info.dli_fname != nullptr;
        if (located) {
            const std::string from = info.dli_fname;
            std::printf("   resolved from: %s\n", from.c_str());
            check(from.find("xim-x-expat") == std::string::npos,
                  "it is not the ecosystem payload's libexpat");
        } else {
            Dl_info self{};
            const bool anyAnswer =
                ::dladdr(reinterpret_cast<void *>(&main), &self) != 0;
            std::printf("   dladdr answers nothing in this image%s\n",
                        anyAnswer ? " EXCEPT main" : " at all (static link)");
            check(!anyAnswer,
                  "dladdr locates the code that parsed, or locates nothing");
        }
    }

    std::printf("\n%d check(s) failed\n", failures);
    return failures == 0 ? 0 : 1;
}

#else

int main() { return 0; }

#endif

// Public ffmpeg module package end-to-end assertion: import-only consumption
// (`import ffmpeg.av;`), libavutil version of the FFmpeg 8.1.x train, core
// decoders present, demuxer registry populated. Builds on linux+macOS+windows.
import std;
import ffmpeg.av;

int main() {
    unsigned v { avutil_version() };
    std::println("libavutil {}.{} module package ok", v >> 16, (v >> 8) & 0xff);
    if ((v >> 16) != 60u) {   // libavutil major of the FFmpeg 8.1.x train
        return 1;
    }

    for (auto name : { "h264", "hevc", "av1", "aac" }) {
        const AVCodec* dec { avcodec_find_decoder_by_name(name) };
        if (dec == nullptr) {
            std::println("decoder {} MISSING", name);
            return 2;
        }
    }

    void* it { nullptr };
    long demuxers { 0 };
    while (av_demuxer_iterate(&it)) ++demuxers;
    std::println("{} demuxers registered", demuxers);
    return demuxers > 300 ? 0 : 3;
}

// compat.ffmpeg end-to-end assertion: the full-profile source build must
// expose its major decoders and demuxers, and library versions must match the
// vendored 8.1.2 release. Linux-only (see mcpp.toml).
#if defined(__linux__) || defined(__APPLE__) || defined(_WIN32)
extern "C" {
#include <libavcodec/avcodec.h>
#include <libavformat/avformat.h>
}

int main() {
    if ((avutil_version() >> 16) != 60) return 1;   // n8.1.x: libavutil major 60
    if ((avcodec_version() >> 16) != 62) return 2;
    if ((avformat_version() >> 16) != 62) return 3;

    const char* decoders[] { "h264", "hevc", "av1", "aac" };
    for (const char* name : decoders)
        if (!avcodec_find_decoder_by_name(name)) return 4;

    void* it { nullptr };
    int demuxers { 0 };
    while (av_demuxer_iterate(&it)) ++demuxers;
    if (demuxers <= 300) return 5;                  // full profile registers 358

    return 0;
}
