    if (copy.toString() != "galay" || buffer.length() != 0) return 5;

    const Host host(IPType::IPV4, "127.0.0.1", 9080);
    if (!host.valid() || host.ip() != "127.0.0.1" || host.port() != 9080) return 6;

    return 0;
}

