// Behavioral test — compat.glm delivers a real glm, not an empty include root.
//
// The criterion is arithmetic, not compilation: a wrong include root fails to
// compile, but a header set that resolved to the wrong thing would still need
// to produce these numbers. Every value below is fixed by linear algebra or by
// glm's documented conventions.
#include <glm/glm.hpp>
#include <glm/gtc/matrix_transform.hpp>
#include <glm/gtx/norm.hpp>

import std;

int main() {
    // Cross product, right-handed: x cross y is z.
    const glm::vec3 x{1.0f, 0.0f, 0.0f};
    const glm::vec3 y{0.0f, 1.0f, 0.0f};
    if (glm::cross(x, y) != glm::vec3(0.0f, 0.0f, 1.0f)) {
        std::println("cross(x, y) is not z");
        return 1;
    }

    // Column-major storage is part of glm's ABI, and it is what a consumer
    // relies on when it memcpy's a mat4 into a uniform buffer.
    glm::mat4 m{1.0f};
    m[3] = glm::vec4(2.0f, 3.0f, 4.0f, 1.0f);
    if (m[3][0] != 2.0f || m[3][1] != 3.0f || m[3][2] != 4.0f) {
        std::println("mat4 translation column is not where column-major puts it");
        return 2;
    }
    const glm::vec4 moved = m * glm::vec4(1.0f, 1.0f, 1.0f, 1.0f);
    if (moved != glm::vec4(3.0f, 4.0f, 5.0f, 1.0f)) {
        std::println("mat4 * vec4 did not translate");
        return 3;
    }

    // GLM_FORCE_DEPTH_ZERO_TO_ONE, set by THIS project: with it, the near
    // plane maps to 0 (Vulkan). Without it glm would map it to -1 (OpenGL),
    // and this is the assertion that tells the two apart.
    const glm::mat4 proj = glm::perspective(glm::radians(45.0f), 16.0f / 9.0f, 0.1f, 100.0f);
    const glm::vec4 nearPoint = proj * glm::vec4(0.0f, 0.0f, -0.1f, 1.0f);
    const float ndcNear = nearPoint.z / nearPoint.w;
    if (std::abs(ndcNear) > 1e-4f) {
        std::println("near plane maps to {} — GLM_FORCE_DEPTH_ZERO_TO_ONE did not take", ndcNear);
        return 4;
    }

    // gtx/, reached only because GLM_ENABLE_EXPERIMENTAL is defined.
    if (std::abs(glm::length2(glm::vec3(3.0f, 4.0f, 0.0f)) - 25.0f) > 1e-4f) {
        std::println("glm::length2 wrong");
        return 5;
    }

    std::println("compat.glm: ok (cross/column-major/zero-to-one depth/gtx all correct)");
    return 0;
}

// gmodule — dynamic loading, checked by actually loading something.
//
// WHAT THIS ASSERTS AND WHY
//
// gmodule is two source files, so "did it compile" is nearly free — and nearly
// worthless. The value is in `gmoduleconf.h`, which build.mcpp generates and
// which decides WHICH loader is compiled in. `G_MODULE_IMPL_NONE` produces a
// library that builds, links, and returns "dynamic loading not supported" for
// everything.
//
// So the checks are: does it claim to support loading, and does a load
// actually work. `g_module_open(NULL)` opens the CURRENT EXECUTABLE — the one
// case that needs no test fixture on disk — and a symbol looked up in it must
// be one this binary really has.

#ifdef __linux__

// ⚠️ NO extern "C" WRAPPER, and adding one BREAKS THIS UNDER libc++: glib
// decorates every header with G_BEGIN_DECLS (which IS `extern "C" {`), and
// glib.h pulls <stdlib.h>, which libc++ routes through <cstdlib> — templates
// inside an extern "C" block. `templates must have C++ linkage`, dozens of
// times, against a header this test never names. libstdc++ does not, so gcc is
// green and llvm is a wall. Wrap a C header only if it has none of its own.
#include <gmodule.h>

#include <cstdio>
#include <cstring>

namespace {

int failures = 0;

void check(bool ok, const char *what)
{
    std::printf("%-56s %s\n", what, ok ? "ok" : "FAILED");
    if (!ok) {
        ++failures;
    }
}

} // namespace

int main()
{
    // ── 1. gmoduleconf.h selected a real loader ──────────────────────────
    // G_MODULE_IMPL_NONE here would mean build.mcpp filled the template with
    // the "no loader" answer, and everything below would fail in a way that
    // reads like a broken system rather than a wrong generated header.
    std::printf("   g_module_supported = %d, suffix = %s\n",
                g_module_supported(), G_MODULE_SUFFIX);
    check(g_module_supported(), "g_module_supported — gmoduleconf.h chose the dl loader");
    check(std::strcmp(G_MODULE_SUFFIX, "so") == 0,
          "G_MODULE_SUFFIX is \"so\", from the generated glibconfig.h");

    // ── 2. a load that needs no fixture ──────────────────────────────────
    // NULL means "this executable". It exercises the same dlopen path a plugin
    // would, without needing a .so to have been built alongside the test.
    GModule *self = g_module_open(nullptr, G_MODULE_BIND_LAZY);
    check(self != nullptr, "g_module_open(NULL) opens the running executable");
    if (self != nullptr) {
        // ⚠️ NO SYMBOL LOOKUP HERE, and the reason is a property of this
        // package rather than a gap in the test.
        //
        // `dlsym` on the main program sees only the DYNAMIC symbol table, which
        // needs `-rdynamic`. And gnome.glib is `kind = "lib"`: its objects are
        // merged into the consumer, so there is no libglib-2.0.so in the link
        // map either. Both halves of the obvious assertion — a symbol of this
        // executable's, or one of glib's — are therefore absent by
        // construction, and a test that asserted them would be measuring the
        // link line.
        //
        // What IS observable without a fixture on disk is that the loader
        // answers at all, and that it distinguishes present from absent.
        gpointer missing = nullptr;
        check(!g_module_symbol(self, "mcpp_no_such_symbol_at_all", &missing),
              "a name that is not there is reported as absent, not crashed on");

        std::printf("   g_module_name = %s\n", g_module_name(self));
        check(g_module_close(self), "g_module_close");
    }

    // ── 2b. g_module_build_path — G_MODULE_SUFFIX in use ─────────────────
    // The one place the generated glibconfig.h value becomes a STRING a caller
    // sees. On Windows this would be "plugin.dll"; getting it wrong would make
    // every plugin host look for the wrong filename.
    {
        gchar *p = g_module_build_path("/opt/plug", "demo");
        std::printf("   g_module_build_path = %s\n", p ? p : "(null)");
        check(p != nullptr && std::strcmp(p, "/opt/plug/libdemo.so") == 0,
              "g_module_build_path applies the lib prefix and .so suffix");
        g_free(p);
    }

    // ── 3. the error path says something ─────────────────────────────────
    // G_MODULE_IMPL_NONE would also reach here, so this is checked after the
    // success case rather than instead of it.
    GModule *nope = g_module_open("/nonexistent/definitely-not-a-module.so",
                                  G_MODULE_BIND_LAZY);
    check(nope == nullptr, "opening a missing module fails");
    const gchar *err = g_module_error();
    std::printf("   g_module_error = %s\n", err ? err : "(null)");
    // G_MODULE_HAVE_DLERROR is one of the four values build.mcpp fills into
    // gmoduleconf.h; without it the message would be a generic placeholder
    // rather than the loader's own text.
    check(err != nullptr && std::strstr(err, "definitely-not-a-module") != nullptr,
          "…and dlerror's message names the file — G_MODULE_HAVE_DLERROR is on");

    std::printf("\n%d check(s) failed\n", failures);
    return failures == 0 ? 0 : 1;
}

#else
int main() { return 0; }
#endif

// ⭐ THE MODULE, WHICH IS WHAT THE NAMESPACE PROMISES.
//
// In this index the namespace is the contract: `compat.xxx` is consumed with
// `#include`, an owner namespace like `gnome.xxx` exposes `import`. The test
// next to this file consumes gnome.gmodule through its headers; this one consumes
// the same package through its module, so both doors are checked from the
// OUTSIDE — which is what an index example is for.
//
// ⚠️ THE TWO DOORS DO NOT COMPOSE, and that is GCC's rule rather than a choice
// here. A TU that imports the module AND textually includes a glib header
// reaches <time.h> twice — once through the module's global fragment, once
// directly — and the same `struct tm` from the same file becomes two entities:
//
//     error: conflicting declaration 'struct tm'
//     note: previous declaration as 'struct tm'   (of module gnome.glib)
//
// So a consumer picks ONE route, and which one is decided by macros: a module
// cannot carry them, and glib's are half its API. Code using `G_DEFINE_TYPE`,
// `G_OBJECT` or `G_TYPE_*` takes the header route. Code using the FUNCTION API
// — most of gio, and much of glib — imports and includes nothing.
#ifdef __linux__

import gnome.gmodule;   // re-exports gnome.glib

#include <cstdio>
#include <cstring>

int main()
{
    int failures = 0;
    auto check = [&](bool ok, const char *what) {
        std::printf("%-58s %s\n", what, ok ? "ok" : "FAILED");
        if (!ok) ++failures;
    };

    std::printf("import gnome.gmodule\n\n");

    check(g_module_supported(), "g_module_supported() through the module");

    // An enumerator, reached through its typedef — glib writes
    // `typedef enum { … } GModuleFlags;` and exporting the typedef is what
    // makes G_MODULE_BIND_LAZY visible. Nothing names it individually.
    GModuleFlags f = G_MODULE_BIND_LAZY;
    check(static_cast<int>(f) == 1, "an enumerator arrives with its typedef");

    GModule *m = g_module_open("/nonexistent/definitely-not-a-module.so", f);
    check(m == nullptr, "opening a missing module fails");
    const char *err = g_module_error();
    check(err != nullptr && std::strstr(err, "definitely-not-a-module") != nullptr,
          "…and g_module_error names the file — the dl loader is wired up");

    // ⭐ gnome.glib ARRIVES THROUGH gnome.gmodule, and it has to: glib is a
    // workspace PATH dependency, so a consumer that named it as well would get
    //   error: dependency 'gnome.glib' is requested as both a version dep
    //          and a path dep
    // gmodule.h includes glib.h, so the module re-exports gnome.glib to match.
    char *p = g_strdup("re-exported");
    check(p != nullptr && std::strcmp(p, "re-exported") == 0,
          "g_strdup — gnome.glib came through gnome.gmodule");
    g_free(p);

    std::printf("\n%s\n", failures == 0 ? "all ok" : "FAILURES");
    return failures == 0 ? 0 : 1;
}

