// compat.gmp `gmpxx` feature: the C++ bindings compile against the consumer's
// own toolchain and link.
//
// The stream operators are the load-bearing part. Everything else in gmpxx.h is
// inline in the header, so a member that only did arithmetic would link with
// the feature TURNED OFF and prove nothing. `os << mpz_class` resolves to
// __gmp_ostream_operator, which lives in cxx/osmpz.cc — one of the eleven
// sources the feature gates.
//
// It is also the one place where "compiled by the consumer's toolchain" is
// actually tested: those symbols carry std::ostream / std::string in their
// mangled names, so a prebuilt libgmpxx would resolve on libstdc++ and fail on
// libc++.

#include <gmpxx.h>

#include <cstdio>
#include <iostream>
#include <sstream>
#include <string>

namespace {

int check_mpz_class() {
    // 128-bit-ish multiply, formatted through the ostream operator.
    mpz_class a("123456789012345678901234567890");
    mpz_class b = a * a;
    std::ostringstream os;
    os << b;
    if (os.str() != "15241578753238836750495351562536198787501905199875019052100")
        return 20;

    // Operator overloading across mixed types, and the comparison operators.
    mpz_class c = a + 10;
    if (c - 10 != a) return 21;
    if (!(a < b) || !(b > a)) return 22;

    // Number-theoretic helpers reached through the C++ names.
    mpz_class g = gcd(mpz_class(123456789), mpz_class(987654321));
    if (g != 9) return 23;

    // get_str / set_str round trip via std::string.
    std::string hex = b.get_str(16);
    mpz_class back(hex, 16);
    if (back != b) return 24;

    // istream operator — the other half of the gated sources (cxx/ismpz.cc).
    std::istringstream is("999999999999999999999999999999");
    mpz_class parsed;
    is >> parsed;
    if (parsed != mpz_class("999999999999999999999999999999")) return 25;
    return 0;
}

int check_mpq_class() {
    mpq_class q(1, 3);
    q += mpq_class(1, 6);          // 1/2
    q.canonicalize();
    std::ostringstream os;
    os << q;
    if (os.str() != "1/2") return 30;
    if (q.get_num() != 1 || q.get_den() != 2) return 31;

    mpq_class r = q * mpq_class(4, 3);   // 2/3
    r.canonicalize();
    if (r != mpq_class(2, 3)) return 32;
    return 0;
}

int check_mpf_class() {
    mpf_class two(2, 256);
    mpf_class root = sqrt(two);
    if (!(root > 1.41 && root < 1.42)) return 40;
    // Squaring it back has to land within the working precision.
    mpf_class err = abs(root * root - 2);
    if (!(err < mpf_class(1e-30, 256))) return 41;

    std::ostringstream os;
    os << mpf_class(1.5, 64);
    if (os.str() != "1.5") return 42;
    return 0;
}

}  // namespace

int main() {
    int rc = check_mpz_class();
    if (rc == 0) rc = check_mpq_class();
    if (rc == 0) rc = check_mpf_class();
    if (rc != 0) {
        std::fprintf(stderr, "compat.gmp gmpxx: check failed, code %d\n", rc);
        return rc;
    }
    std::cout << "compat.gmp gmpxx: mpz_class/mpq_class/mpf_class + streams ok"
              << std::endl;
    return 0;
}

// compat.gmp end-to-end, C API: gmp.h resolves, the library links, and every
// source directory the descriptor compiles actually works.
//
// One assertion group per directory in the package's source list, because a
// build described by globs is exactly the kind that can lose a whole directory
// without anything failing to compile:
//
//   mpn/generic  every group below (mpz/mpq/mpf all bottom out in mpn)
//   mpz          factorial / powm / gcd / string round-trip / import-export
//   mpq          rational arithmetic and canonicalisation
//   mpf          the float layer, incl. mpf_sqrt
//   printf       gmp_snprintf
//   scanf        gmp_sscanf
//   rand         gmp_randinit / mpz_urandomm
//
// The expected values are precomputed independently of GMP (Python
// int/fractions), so a library that silently picked up a host libgmp, or one
// built from the wrong tables, fails instead of agreeing with itself.

#include <gmp.h>

#include <cstdio>
#include <cstring>
#include <cstdlib>

namespace {

// GMP allocates the result of mpz_get_str with ITS allocator, which is not
// necessarily the one behind std::free. The documented way to give it back is
// the free function GMP reports, and it is the only way that stays correct if a
// consumer ever installs custom memory functions.
void gmp_free(char* p) {
    if (p == nullptr) return;
    void (*freefunc)(void*, size_t) = nullptr;
    mp_get_memory_functions(nullptr, nullptr, &freefunc);
    freefunc(p, std::strlen(p) + 1);
}

int check_limb_shape() {
    // The descriptor vendors tables generated for limb=64/nail=0 and its
    // config.h refuses to compile without a 64-bit unsigned type. If gmp.h and
    // the compiled library ever disagreed about the limb — the LP64/LLP64
    // mistake a configure-baked header makes when it reaches Windows — every
    // other assertion here would still pass while mp_limb_t was half-width.
    if (GMP_LIMB_BITS != 64) return 10;
    if (sizeof(mp_limb_t) * 8 != GMP_LIMB_BITS) return 11;
    if (GMP_NAIL_BITS != 0) return 12;
    if (mp_bits_per_limb != GMP_LIMB_BITS) return 13;
    return 0;
}

int check_mpz() {
    // 100! — a known 158-digit value, compared digit by digit.
    {
        mpz_t f;
        mpz_init(f);
        mpz_fac_ui(f, 100);
        char* s = mpz_get_str(nullptr, 10, f);
        const char* expected =
            "93326215443944152681699238856266700490715968264381621468592963895217599993229915"
            "608941463976156518286253697920827223758251185210916864000000000000000000000000";
        int ok = s != nullptr && std::strcmp(s, expected) == 0;
        gmp_free(s);
        mpz_clear(f);
        if (!ok) return 20;
    }

    // Modular exponentiation, big enough to leave the single-limb paths:
    // 7^1234 mod (2^127 - 1).
    {
        mpz_t base, mod, res;
        mpz_init_set_ui(base, 7);
        mpz_init(mod);
        mpz_ui_pow_ui(mod, 2, 127);
        mpz_sub_ui(mod, mod, 1);
        mpz_init(res);
        mpz_powm_ui(res, base, 1234, mod);
        char* s = mpz_get_str(nullptr, 10, res);
        int ok = s != nullptr &&
                 std::strcmp(s, "55471114467826807814326117990010739464") == 0;
        gmp_free(s);
        mpz_clears(base, mod, res, nullptr);
        if (!ok) return 21;
    }

    // gcd / lcm on a pair with a known factorisation.
    //
    // The lcm is compared against an mpz built from a decimal string, not
    // through mpz_cmp_ui: that takes `unsigned long`, which is 32 bits on
    // LLP64 (Windows), so 13548070123626141 would be silently truncated and
    // the assertion would fail on Windows only. Every *_ui entry point in
    // this file is therefore kept under 2^32.
    {
        mpz_t a, b, g, l, expect;
        mpz_init_set_ui(a, 123456789);
        mpz_init_set_ui(b, 987654321);
        mpz_init(g);
        mpz_init(l);
        mpz_init_set_str(expect, "13548070123626141", 10);
        mpz_gcd(g, a, b);
        mpz_lcm(l, a, b);
        int ok = mpz_cmp_ui(g, 9) == 0 && mpz_cmp(l, expect) == 0;
        mpz_clears(a, b, g, l, expect, nullptr);
        if (!ok) return 22;
    }

    // Base-16 round trip through a 256-bit value, and mpz_sizeinbase.
    {
        const char* hex = "ffffffffffffffffffffffffffffffff"
                          "fffffffffffffffffffffffefffffc2f";  // secp256k1 p
        mpz_t p;
        mpz_init(p);
        if (mpz_set_str(p, hex, 16) != 0) { mpz_clear(p); return 23; }
        if (mpz_sizeinbase(p, 2) != 256) { mpz_clear(p); return 24; }
        char* back = mpz_get_str(nullptr, 16, p);
        int ok = back != nullptr && std::strcmp(back, hex) == 0;
        gmp_free(back);
        // It is prime, which walks probab_prime_p -> mpn_trialdiv -> the
        // vendored trialdivtab.h, and millerrabin -> mpz_powm.
        if (ok && mpz_probab_prime_p(p, 25) == 0) ok = 0;
        mpz_clear(p);
        if (!ok) return 25;
    }

    // import/export: the limb-order path, which is where a wrong
    // HAVE_LIMB_LITTLE_ENDIAN would show up.
    {
        const unsigned char be[] = {0x01, 0x23, 0x45, 0x67, 0x89, 0xab, 0xcd, 0xef,
                                    0xfe, 0xdc, 0xba, 0x98};
        mpz_t v;
        mpz_init(v);
        mpz_import(v, sizeof(be), 1 /*most significant word first*/, 1, 0, 0, be);
        char* s = mpz_get_str(nullptr, 16, v);
        int ok = s != nullptr && std::strcmp(s, "123456789abcdeffedcba98") == 0;
        gmp_free(s);
        unsigned char out[sizeof(be)] = {0};
        size_t count = 0;
        mpz_export(out, &count, 1, 1, 0, 0, v);
        if (count != sizeof(be) || std::memcmp(out, be, sizeof(be)) != 0) ok = 0;
        mpz_clear(v);
        if (!ok) return 26;
    }

    return 0;
}

int check_mpq() {
    mpq_t q, r;
    mpq_init(q);
    mpq_init(r);
    mpq_set_ui(q, 1, 2);
    mpq_set_ui(r, 1, 3);
    mpq_add(q, q, r);                       // 5/6
    int ok = mpq_cmp_ui(q, 5, 6) == 0;
    mpq_set_ui(r, 10, 4);                   // canonicalises to 5/2
    mpq_canonicalize(r);
    if (mpz_cmp_ui(mpq_numref(r), 5) != 0 || mpz_cmp_ui(mpq_denref(r), 2) != 0) ok = 0;
    mpq_div(q, q, r);                       // (5/6) / (5/2) = 1/3
    if (mpq_cmp_ui(q, 1, 3) != 0) ok = 0;
    mpq_clear(q);
    mpq_clear(r);
    return ok ? 0 : 30;
}

int check_mpf() {
    mpf_set_default_prec(256);
    mpf_t x, s, one;
    mpf_init_set_ui(x, 2);
    mpf_init(s);
    mpf_init_set_ui(one, 1);
    mpf_sqrt(s, x);                          // sqrt(2)
    int ok = mpf_cmp_d(s, 1.0) > 0 && mpf_cmp_d(s, 2.0) < 0;
    // s*s must be 2 to well within the working precision.
    mpf_mul(x, s, s);
    mpf_sub_ui(x, x, 2);
    mpf_abs(x, x);
    mpf_div_2exp(one, one, 200);             // 2^-200
    if (mpf_cmp(x, one) >= 0) ok = 0;
    mpf_clears(x, s, one, nullptr);
    return ok ? 0 : 40;
}

int check_printf_scanf() {
    // printf/ — gmp_snprintf with the %Zd conversion.
    mpz_t v;
    mpz_init(v);
    mpz_ui_pow_ui(v, 3, 40);                 // 12157665459056928801
    char buf[64] = {0};
    int n = gmp_snprintf(buf, sizeof(buf), "[%Zd]", v);
    int ok = n == 22 && std::strcmp(buf, "[12157665459056928801]") == 0;
    mpz_clear(v);
    if (!ok) return 50;

    // scanf/ — the same value back out of a string.
    mpz_t w;
    mpz_init(w);
    if (gmp_sscanf("12157665459056928801", "%Zd", w) != 1) { mpz_clear(w); return 51; }
    mpz_t expect;
    mpz_init(expect);
    mpz_ui_pow_ui(expect, 3, 40);
    ok = mpz_cmp(w, expect) == 0;
    mpz_clears(w, expect, nullptr);
    return ok ? 0 : 52;
}

int check_rand() {
    // rand/ — a seeded Mersenne Twister is deterministic, so this asserts the
    // generator runs AND that every draw lands in range.
    gmp_randstate_t st;
    gmp_randinit_mt(st);
    gmp_randseed_ui(st, 20260810u);
    mpz_t n, x;
    mpz_init(n);
    mpz_ui_pow_ui(n, 10, 30);
    mpz_init(x);
    int ok = 1;
    for (int i = 0; i < 64; ++i) {
        mpz_urandomm(x, st, n);
        if (mpz_sgn(x) < 0 || mpz_cmp(x, n) >= 0) { ok = 0; break; }
    }
    mpz_clears(n, x, nullptr);
    gmp_randclear(st);
    return ok ? 0 : 60;
}

}  // namespace

int main() {
    int rc = check_limb_shape();
    if (rc == 0) rc = check_mpz();
    if (rc == 0) rc = check_mpq();
    if (rc == 0) rc = check_mpf();
    if (rc == 0) rc = check_printf_scanf();
    if (rc == 0) rc = check_rand();
    if (rc != 0) {
        std::fprintf(stderr, "compat.gmp: check failed, code %d\n", rc);
        return rc;
    }
    std::printf("compat.gmp %s: mpz/mpq/mpf/printf/scanf/rand ok (limb %d bits)\n",
                gmp_version, GMP_LIMB_BITS);
    return 0;
}

// gobject — the type system, exercised rather than merely linked.
//
// WHAT THIS ASSERTS AND WHY
//
// GObject is the kind of library where "it linked" proves nothing: GType is a
// runtime registry, so a build that compiled half of it still links and then
// fails the first time something registers a type. Every check below makes the
// library DO something and reads back a value it computed:
//
//   g_type_init-era registry   a fundamental type's name, from gtype.c
//   the GENERATED enum types   g_unicode_script_get_type(), which exists only
//                              because build.mcpp reproduced glib-mkenums
//   a derived type             registered at run time, with a property
//   properties                 set through GValue and read back
//   signals                    connected, emitted, and observed to have run
//   GBinding                   two objects kept in step, which is gbinding.c
//
// The enum-type check is the one that matters most for this fork: it is the
// only evidence that the mkenums reimplementation produced a REGISTERABLE type
// rather than a header that merely compiles.

#ifdef __linux__

// ⚠️ NO extern "C" WRAPPER, and adding one BREAKS THIS UNDER libc++.
//
// glib decorates every header with G_BEGIN_DECLS/G_END_DECLS, which IS
// `extern "C" {`, so a wrapper is redundant. It is also harmful: glib.h pulls
// <stdlib.h> and <string.h>, and libc++ routes those through
// <cstdlib>/<cstring>, which define TEMPLATES. Inside an extern "C" block that
// is
//
//   __type_traits/add_cv_quals.h:20: error: templates must have C++ linkage
//
// reported dozens of times against a standard-library header this test never
// names. libstdc++ does not route them that way, so the gcc leg is green and
// the llvm leg is a wall of errors — the same asymmetry that caught a missing
// <sstream> in the cairo fork.
//
// The rule: wrap a C header ONLY if it has no extern "C" of its own.
// compat.libseat and freedesktop.libdisplay-info need it; glib does not.
#include <glib-object.h>
#include <gobject/glib-enumtypes.h>

#include <cstdio>
#include <cstring>

namespace {

int failures = 0;

void check(bool ok, const char *what)
{
    std::printf("%-58s %s\n", what, ok ? "ok" : "FAILED");
    if (!ok) {
        ++failures;
    }
}

// A minimal derived type, declared the way every GObject library does it.
// Registering it exercises gtype.c, gobject.c, gparam.c and gvalue.c at once.
struct TestThing {
    GObject parent;
    gint answer;
};
struct TestThingClass {
    GObjectClass parent;
};

enum { PROP_0, PROP_ANSWER, N_PROPS };
GParamSpec *props[N_PROPS] = {};

GType test_thing_get_type(void);
G_DEFINE_TYPE(TestThing, test_thing, G_TYPE_OBJECT)

void test_thing_set_property(GObject *o, guint id, const GValue *v, GParamSpec *p)
{
    if (id == PROP_ANSWER) {
        reinterpret_cast<TestThing *>(o)->answer = g_value_get_int(v);
    } else {
        G_OBJECT_WARN_INVALID_PROPERTY_ID(o, id, p);
    }
}

void test_thing_get_property(GObject *o, guint id, GValue *v, GParamSpec *p)
{
    if (id == PROP_ANSWER) {
        g_value_set_int(v, reinterpret_cast<TestThing *>(o)->answer);
    } else {
        G_OBJECT_WARN_INVALID_PROPERTY_ID(o, id, p);
    }
}

guint sig_changed = 0;

void test_thing_class_init(TestThingClass *klass)
{
    GObjectClass *oc = G_OBJECT_CLASS(klass);
    oc->set_property = test_thing_set_property;
    oc->get_property = test_thing_get_property;
    props[PROP_ANSWER] = g_param_spec_int("answer", nullptr, nullptr,
                                          G_MININT, G_MAXINT, 0,
                                          static_cast<GParamFlags>(G_PARAM_READWRITE));
    g_object_class_install_properties(oc, N_PROPS, props);

    sig_changed = g_signal_new("changed", test_thing_get_type(), G_SIGNAL_RUN_LAST,
                               0, nullptr, nullptr, nullptr, G_TYPE_NONE, 1, G_TYPE_INT);
}

void test_thing_init(TestThing *) {}

int seen = -1;
void on_changed(TestThing *, gint value, gpointer) { seen = value; }

} // namespace

int main()
{
    // ── 1. the type registry answers about its own fundamentals ──────────
    std::printf("   glib %d.%d.%d\n", glib_major_version, glib_minor_version,
                glib_micro_version);
    check(glib_major_version == 2 && glib_minor_version == 82,
          "glib_*_version report 2.82, the version the manifest declares");
    check(std::strcmp(g_type_name(G_TYPE_INT), "gint") == 0,
          "g_type_name(G_TYPE_INT) is \"gint\" — the registry is initialised");
    check(g_type_is_a(G_TYPE_OBJECT, G_TYPE_OBJECT), "g_type_is_a on GObject itself");

    // ── 2. THE GENERATED ENUM TYPES ──────────────────────────────────────
    // These exist only because build.mcpp reproduced glib-mkenums over
    // glib/gunicode.h. Registering one and reading a value back is the only
    // thing that proves the generator produced working code rather than a
    // header that happens to compile.
    const GType script = g_unicode_script_get_type();
    check(script != 0, "g_unicode_script_get_type() registered a GType");
    GEnumClass *ec = static_cast<GEnumClass *>(g_type_class_ref(script));
    check(ec != nullptr, "…and its class can be referenced");
    if (ec != nullptr) {
        GEnumValue *v = g_enum_get_value(ec, G_UNICODE_SCRIPT_HAN);
        std::printf("   G_UNICODE_SCRIPT_HAN = %s / %s\n",
                    v ? v->value_name : "(null)", v ? v->value_nick : "(null)");
        check(v != nullptr && std::strcmp(v->value_name, "G_UNICODE_SCRIPT_HAN") == 0,
              "…and G_UNICODE_SCRIPT_HAN is in it under its own name");
        // The nick is mkenums' derived form: prefix stripped, lower case,
        // underscores to hyphens. Getting it right is the fiddly half of the
        // generator, so it is asserted rather than assumed.
        check(v != nullptr && std::strcmp(v->value_nick, "han") == 0,
              "…with the nick mkenums derives, \"han\"");
        g_type_class_unref(ec);
    }
    check(g_unicode_type_get_type() != 0 && g_unicode_break_type_get_type() != 0
              && g_normalize_mode_get_type() != 0,
          "all four generated enum types register");

    // ⭐ THE MACRO NAMES, WHICH ARE A DIFFERENT OUTPUT OF THE SAME GENERATOR.
    //
    // Everything above reads the FUNCTION and the NICK, and an earlier 2.82.5
    // tarball got both of those right while defining `G_UNICODE_TYPE_TYPE`
    // where upstream defines `G_TYPE_UNICODE_TYPE`. glib-mkenums has two
    // prefixes — one from the ENUMERATORS (drives nicks), one from the TYPE
    // NAME (drives this macro) — and conflating them changes only the macro.
    //
    // So it compiled, linked, and passed this very test. The four lines below
    // are what it would NOT have passed: naming the macro is a compile error
    // if it is spelled wrong, and it is the only spelling upstream has.
    check(G_TYPE_UNICODE_TYPE == g_unicode_type_get_type()
              && G_TYPE_UNICODE_SCRIPT == g_unicode_script_get_type()
              && G_TYPE_UNICODE_BREAK_TYPE == g_unicode_break_type_get_type()
              && G_TYPE_NORMALIZE_MODE == g_normalize_mode_get_type(),
          "the G_TYPE_* macros are upstream's, not the enumerator prefix");

    // ── 3. a derived type, its property, its signal ──────────────────────
    const GType thing = test_thing_get_type();
    check(thing != 0 && g_type_is_a(thing, G_TYPE_OBJECT),
          "a derived type registers and is a GObject");
    std::printf("   registered %s\n", g_type_name(thing));

    GObject *o = static_cast<GObject *>(g_object_new(thing, "answer", 42, nullptr));
    check(o != nullptr, "g_object_new with a construct property");

    gint got = 0;
    g_object_get(o, "answer", &got, nullptr);
    std::printf("   answer = %d\n", got);
    check(got == 42, "…and g_object_get reads it back through GValue");

    g_signal_connect(o, "changed", G_CALLBACK(on_changed), nullptr);
    g_signal_emit(o, sig_changed, 0, 7);
    std::printf("   the handler saw %d\n", seen);
    check(seen == 7, "a signal is emitted and the handler runs");

    // ── 4. GBinding — gbinding.c, and a real use of the property system ──
    GObject *b = static_cast<GObject *>(g_object_new(thing, nullptr));
    g_object_bind_property(o, "answer", b, "answer", G_BINDING_DEFAULT);
    g_object_set(o, "answer", 99, nullptr);
    gint mirrored = 0;
    g_object_get(b, "answer", &mirrored, nullptr);
    std::printf("   bound object followed to %d\n", mirrored);
    check(mirrored == 99, "g_object_bind_property keeps two objects in step");

    g_object_unref(b);
    g_object_unref(o);
    check(true, "objects destroyed without a warning");

    std::printf("\n%d check(s) failed\n", failures);
    return failures == 0 ? 0 : 1;
}

