// Behavioral test — compat.libassert decomposes an expression and reports the
// values in it, which is the whole reason to use it over <cassert>.
//
// A passing assertion proves almost nothing, so the test drives the FAILING
// path: it installs a failure handler, provokes a failed assertion, and reads
// what libassert produced. `LIBASSERT_ASSERT` carries `LIBASSERT_NOP_ACTION`,
// so a handler that returns lets execution continue — which is what makes this
// testable in-process rather than through an abort.
//
// It is also the proof that the transitive dependency arrives: the failure
// object hands back a `cpptrace::stacktrace`, and this project declares only
// libassert.
//
// No `import std;` — libassert's headers are textual over the standard library.
#include <libassert/assert.hpp>
#include <libassert/version.hpp>
// libassert's own header only FORWARD-declares cpptrace::stacktrace
// (cpptrace/forward.hpp), so calling .frames on it needs the complete type.
// Including cpptrace's public header here works only because compat.cpptrace's
// include directory reaches this project transitively through libassert — this
// project declares no cpptrace dependency of its own. The include is therefore
// part of the assertion, not incidental.
#include <cpptrace/cpptrace.hpp>

#include <cstdio>
#include <string>

#if LIBASSERT_VERSION != LIBASSERT_TO_VERSION(2, 2, 1)
#  error "libassert/version.hpp does not describe 2.2.1 — the generated header drifted from the tarball"
#endif

// Both packages build objects rather than shared libraries, so the
// declarations this TU sees must be plain. Each delivers that with a shim in
// front of the one header that reads its macro — no descriptor key carries a
// define into a consumer's TUs. On Linux the difference is only a visibility
// attribute, so a regression is invisible; on the MSVC ABI it is `dllimport`
// against a locally defined symbol, which is exactly how this member first
// failed on the windows CI leg.
#if !defined(LIBASSERT_STATIC_DEFINE)
#  error "LIBASSERT_STATIC_DEFINE is not set — the compat.libassert platform.hpp shim was not reached"
#endif
#if !defined(CPPTRACE_STATIC_DEFINE)
#  error "CPPTRACE_STATIC_DEFINE is not set — compat.cpptrace's basic.hpp shim did not reach a transitive consumer"
#endif

static std::string captured;
static std::size_t trace_frames = 0;
static int failures = 0;

static void record(const libassert::assertion_info& info) {
    ++failures;
    captured = info.to_string(0, libassert::color_scheme::blank);
    trace_frames = info.get_stacktrace().frames.size();
}

int main() {
    libassert::set_failure_handler(record);

    const int limit = 3;
    const int index = 7;

    // A true assertion must not reach the handler.
    LIBASSERT_ASSERT(limit < index);
    if (failures != 0) {
        std::printf("a true assertion fired the handler\n");
        return 1;
    }

    // A false one must, exactly once.
    LIBASSERT_ASSERT(index < limit, "index out of range", index, limit);
    if (failures != 1) {
        std::printf("failure handler fired %d times, expected 1\n", failures);
        return 2;
    }

    // The report has to carry the EXPRESSION TEXT — that is the part a plain
    // `assert` also manages — and then the two things it does not: the message
    // and the decomposed operand values.
    if (captured.find("index < limit") == std::string::npos) {
        std::printf("report does not carry the expression text:\n%s\n", captured.c_str());
        return 3;
    }
    if (captured.find("index out of range") == std::string::npos) {
        std::printf("report does not carry the message:\n%s\n", captured.c_str());
        return 4;
    }
    if (captured.find("7") == std::string::npos || captured.find("3") == std::string::npos) {
        std::printf("report does not carry the decomposed values:\n%s\n", captured.c_str());
        return 5;
    }

    // cpptrace, reached transitively. Frame COUNT rather than symbol names:
    // compat.cpptrace resolves symbols with dladdr and documents that it
    // carries no file:line, so asserting on names would be testing the
    // backend choice rather than the dependency edge.
    if (trace_frames == 0) {
        std::printf("assertion carried no stack trace — cpptrace did not arrive\n");
        return 6;
    }

    std::printf("compat.libassert: ok (expression, message and values decomposed; %zu trace frames)\n",
                trace_frames);
    return 0;
}

// Behavioral test — compat.libcoro actually schedules coroutines.
//
// Every assertion here needs a resumed coroutine to be true, so a package that
// compiled the headers but linked none of the eight core TUs fails: the
// thread_pool, event, mutex and sync_wait entry points all live in those.
//
// Networking is deliberately untouched — see the descriptor. `coro/coro.hpp`
// is NOT included for the same reason; it opens the net/ headers behind
// LIBCORO_FEATURE_NETWORKING, which this build does not define.
//
// No `import std;`: libcoro's headers are textual over the standard library.
#include <coro/event.hpp>
#include <coro/generator.hpp>
#include <coro/mutex.hpp>
#include <coro/sync_wait.hpp>
#include <coro/task.hpp>
#include <coro/thread_pool.hpp>
#include <coro/when_all.hpp>

#include <atomic>
#include <cstdio>
#include <vector>

int main() {
    // A task returning a value, driven to completion synchronously.
    auto add = [](int a, int b) -> coro::task<int> { co_return a + b; };
    if (coro::sync_wait(add(2, 3)) != 5) {
        std::printf("sync_wait(task) did not produce the value\n");
        return 1;
    }

    // A generator is lazy: nothing runs until the range is iterated.
    auto squares = [](int n) -> coro::generator<int> {
        for (int i = 1; i <= n; ++i) co_yield i * i;
    };
    int sum = 0;
    for (int v : squares(4)) sum += v;
    if (sum != 1 + 4 + 9 + 16) {
        std::printf("generator produced %d, expected 30\n", sum);
        return 2;
    }

    // The thread pool really moves work off this thread, and coro::mutex
    // serialises it. Both are compiled TUs, not header inlines — this is the
    // link-time proof for src/thread_pool.cpp and src/mutex.cpp.
    // 0.16.0 makes the constructor private: a pool is created through the
    // make_unique factory, which lives in src/thread_pool.cpp — so this line
    // is also the link-time proof that the TU is compiled in.
    auto pool_ptr = coro::thread_pool::make_unique(coro::thread_pool::options{.thread_count = 4});
    coro::thread_pool& pool = *pool_ptr;
    coro::mutex mutex;
    int guarded = 0;

    std::vector<coro::task<void>> tasks;
    tasks.reserve(200);
    for (int i = 0; i < 200; ++i) {
        tasks.emplace_back([](coro::thread_pool& p, coro::mutex& m, int& counter) -> coro::task<void> {
            co_await p.schedule();
            auto lock = co_await m.scoped_lock();
            ++counter;
            co_return;
        }(pool, mutex, guarded));
    }
    coro::sync_wait(coro::when_all(std::move(tasks)));

    if (guarded != 200) {
        std::printf("200 coroutines incremented the counter to %d — the mutex did not serialise them\n", guarded);
        return 3;
    }

    // coro::event: a coroutine suspends until another thread sets it.
    coro::event started;
    std::atomic<bool> observed{false};
    auto waiter = [&]() -> coro::task<void> {
        co_await started;
        observed = true;
        co_return;
    };
    auto setter = [&]() -> coro::task<void> {
        co_await pool.schedule();
        started.set();
        co_return;
    };
    coro::sync_wait(coro::when_all(waiter(), setter()));
    if (!observed) {
        std::printf("coro::event never released the waiter\n");
        return 4;
    }

    std::printf("compat.libcoro: ok (task, generator, 200 pooled tasks under a coro::mutex, event)\n");
    return 0;
}

// freedesktop.libdisplay-info — parse a real monitor's EDID.
//
// EDID parsing needs no device, no compositor and no permissions: it is a
// function from 128 bytes to a struct. So unlike most of this stack, the whole
// library is honestly testable on a CI runner.
//
// THE BLOB IS INLINE, not read from the package's own test data. A test member
// resolves its dependency into the mcpp store, and reaching into that tree by
// relative path would tie this file to a layout that is mcpp's business. 256
// bytes of a real Acer P1276's EDID, taken from upstream's
// `test/data/acer-p1276.edid`, is cheaper than that coupling.
//
// THE EXPECTED VALUES ARE UPSTREAM'S, from the `.ref` beside that blob:
//
//     EDID Structure Version & Revision: 1.3
//     Manufacturer: ACR
//     Model: 5654                       (0x1616)
//
// WHAT IS ACTUALLY UNDER TEST is the generated PNP table. "ACR" is the raw
// vendor id in the blob; turning it into "Acer Technologies" is what
// `pnp-id-table.c` does — the file this package is a fork in order to
// pre-generate. A build that used the host's pnp.ids instead of the pinned one
// would still parse the EDID and could still answer differently here.

#ifdef __linux__

// NO extern "C" WRAPPER, and that is the point of the module.
//
// Not one of libdisplay-info's seven public headers contains an `extern "C"`
// block — zero occurrences, measured — so a C++ translation unit that
// #includes them mangles every declaration and fails to link with
// `undefined reference to di_info_get_make(di_info const*)`, naming a symbol
// that is right there in the library. This file did exactly that before the
// module existed.
//
// `import displayinfo;` does the wrapping once, inside the module
// purview. The module is GENERATED by the package's build.mcpp from the public
// headers — 206 names — so it cannot fall behind them.
import displayinfo;

#include <cstdio>
#include <cstring>
#include <cstdlib>

namespace {

int failures = 0;

void check(bool ok, const char *what)
{
    std::printf("%-58s %s\n", what, ok ? "ok" : "FAILED");
    if (!ok) {
        ++failures;
    }
}

