// compat.libudev — behavioral test against /sys, no daemon.
//
// libudev-zero reads /sys directly instead of talking to udevd, which is the
// whole reason it is here: a subos has no udev daemon, and an implementation
// that needed one would work on a developer's machine and nowhere else. So the
// test enumerates REAL devices — that is the thing that would silently return
// nothing if the package were built wrong.

#ifdef __linux__

#include <libudev.h>

#include <dlfcn.h>
#include <cstdio>
#include <cstring>
#include <string>

namespace {
int failures = 0;
void check(bool ok, const char *what)
{
    std::printf("%-58s %s\n", what, ok ? "ok" : "FAILED");
    if (!ok) ++failures;
}
} // namespace

int main()
{
    // ── 1. The context comes up without a daemon ─────────────────────────
    udev *ctx = udev_new();
    check(ctx != nullptr, "udev_new without a running udevd");
    if (ctx == nullptr) {
        std::printf("\n%d check(s) failed\n", failures);
        return 1;
    }

    // ── 2. …and it is THIS build, not the host's libudev ─────────────────
    // systemd's libudev carries the same soname. Only one is ever mapped and
    // nothing warns about the other, so the identity has to be pinned.
    {
        void *sym = ::dlsym(RTLD_DEFAULT, "udev_new");
        Dl_info info{};
        if (sym != nullptr && ::dladdr(sym, &info) != 0 && info.dli_fname != nullptr) {
            const std::string from = info.dli_fname;
            std::printf("   udev_new came from: %s\n", from.c_str());
            check(from.find("/usr/lib") == std::string::npos
                  && from.find("/lib/x86_64") == std::string::npos,
                  "the loaded libudev is not the host's");
        }
    }

    // ── 3. Real enumeration off /sys ─────────────────────────────────────
    // Every Linux machine has input devices under /sys/class/input, including
    // a container: the kernel exposes them regardless of who may open them.
    // Finding none means the /sys walk is broken, which is the failure this
    // package can actually have.
    udev_enumerate *e = udev_enumerate_new(ctx);
    check(e != nullptr, "udev_enumerate_new");
    if (e != nullptr) {
        udev_enumerate_add_match_subsystem(e, "input");
        check(udev_enumerate_scan_devices(e) == 0, "udev_enumerate_scan_devices(input)");

        int n = 0;
        const char *first = nullptr;
        for (udev_list_entry *le = udev_enumerate_get_list_entry(e);
             le != nullptr; le = udev_list_entry_get_next(le)) {
            if (first == nullptr) {
                first = udev_list_entry_get_name(le);
            }
            ++n;
        }
        std::printf("   %d input device node(s); first: %s\n", n, first ? first : "(none)");
        check(n > 0, "the /sys walk found input devices");

        // A device object out of that path, with its subsystem read back —
        // this is the call libinput makes for every device it opens.
        if (first != nullptr) {
            udev_device *d = udev_device_new_from_syspath(ctx, first);
            check(d != nullptr, "udev_device_new_from_syspath");
            if (d != nullptr) {
                const char *sub = udev_device_get_subsystem(d);
                std::printf("   subsystem: %s\n", sub ? sub : "(null)");
                check(sub != nullptr && std::strcmp(sub, "input") == 0,
                      "…and its subsystem reads back as \"input\"");
                udev_device_unref(d);
            }
        }
        udev_enumerate_unref(e);
    }

    udev_unref(ctx);
    std::printf("\n%d check(s) failed\n", failures);
    return failures == 0 ? 0 : 1;
}

#else
int main() { return 0; }
#endif

// Behavioral test: encode a synthetic image and decode it back.
//
// Linking is not the interesting question for this package — the source list is
// five directory globs including every SIMD variant, and a variant that failed
// to self-gate would still LINK while producing wrong pixels. So the assertions
// are on the pixels: lossless must round-trip exactly, lossy must stay close,
// and the encoder must actually respond to its quality knob.
#include <webp/decode.h>
#include <webp/encode.h>

#include <cassert>
#include <cstdint>
#include <cstdlib>
#include <vector>

namespace {

constexpr int kW = 64;
constexpr int kH = 48;

// A gradient with a hard edge: smooth enough for the lossy path to do well,
// structured enough that a broken transform shows up as a large delta.
std::vector<uint8_t> make_rgba() {
    std::vector<uint8_t> px(static_cast<std::size_t>(kW) * kH * 4);
    for (int y = 0; y < kH; ++y) {
        for (int x = 0; x < kW; ++x) {
            uint8_t* p = &px[(static_cast<std::size_t>(y) * kW + x) * 4];
            p[0] = static_cast<uint8_t>(x * 4);
            p[1] = static_cast<uint8_t>(y * 5);
            p[2] = static_cast<uint8_t>(x < kW / 2 ? 30 : 220);
            p[3] = 255;
        }
    }
    return px;
}

}  // namespace

int main() {
    const std::vector<uint8_t> src = make_rgba();
    const int stride = kW * 4;

    // --- the header round-trips the dimensions ---
    uint8_t* lossless = nullptr;
    const std::size_t lossless_size =
        WebPEncodeLosslessRGBA(src.data(), kW, kH, stride, &lossless);
    assert(lossless_size > 0 && lossless != nullptr);

    int w = 0, h = 0;
    assert(WebPGetInfo(lossless, lossless_size, &w, &h) == 1);
    assert(w == kW && h == kH);

    // --- lossless must be EXACT ---
    uint8_t* decoded = WebPDecodeRGBA(lossless, lossless_size, &w, &h);
    assert(decoded != nullptr && w == kW && h == kH);
    for (std::size_t i = 0; i < src.size(); ++i) assert(decoded[i] == src[i]);
    WebPFree(decoded);

    // --- lossy must be close, and quality must have an effect ---
    uint8_t* q90 = nullptr;
    const std::size_t q90_size = WebPEncodeRGBA(src.data(), kW, kH, stride, 90.0f, &q90);
    assert(q90_size > 0 && q90 != nullptr);

    uint8_t* q10 = nullptr;
    const std::size_t q10_size = WebPEncodeRGBA(src.data(), kW, kH, stride, 10.0f, &q10);
    assert(q10_size > 0 && q10 != nullptr);
    assert(q10_size < q90_size);   // a lower quality must produce a smaller file

    decoded = WebPDecodeRGBA(q90, q90_size, &w, &h);
    assert(decoded != nullptr && w == kW && h == kH);
    long total = 0;
    for (std::size_t i = 0; i < src.size(); ++i)
        total += std::abs(static_cast<int>(decoded[i]) - static_cast<int>(src[i]));
    const double mean_abs_error = static_cast<double>(total) / static_cast<double>(src.size());
    assert(mean_abs_error < 8.0);  // quality 90 on a smooth image
    WebPFree(decoded);

    WebPFree(lossless);
    WebPFree(q90);
    WebPFree(q10);
    return 0;
}

// libxkbcommon, exercised through the generated parser.
//
// The package is a fork for exactly one reason: `src/xkbcomp/parser.y` is
// bison's input and the 3,960-line parser is generated. So the test compiles a
// keymap FROM A STRING — that runs the parser end to end and needs no
// xkeyboard-config data on disk, which is what makes it runnable on a CI
// machine and in a sandbox.
//
// A package that linked but whose parser was generated without
// `-p _xkbcommon_`, or not regenerated after a version bump, fails here rather
// than in somebody's compositor.

#ifdef __linux__

#include <xkbcommon/xkbcommon.h>

#include <cstdio>
#include <cstring>
#include <cstdlib>

namespace {

int failures = 0;

void check(bool ok, const char *what)
{
    std::printf("%-58s %s\n", what, ok ? "ok" : "FAILED");
    if (!ok) {
        ++failures;
    }
}

// A complete, minimal keymap. Every section the parser knows about appears at
// least once, so compiling it exercises the grammar rather than a corner of it.
const char *const KEYMAP =
    "xkb_keymap {\n"
    "  xkb_keycodes { <esc> = 9; <q> = 24; };\n"
    "  xkb_types { type \"ONE_LEVEL\" {\n"
    "      modifiers = none;\n"
    "      level_name[1] = \"Any\";\n"
    "  }; };\n"
    "  xkb_compat { };\n"
    "  xkb_symbols {\n"
    "    key <esc> { [ Escape ] };\n"
    "    key <q>   { [ q ] };\n"
    "  };\n"
    "};";

} // namespace

int main()
{
    // ── 1. A context with no data root ───────────────────────────────────
    // XKB_CONTEXT_NO_DEFAULT_INCLUDES because this package compiles in an
    // EMPTY DFLT_XKB_CONFIG_ROOT on purpose — there is no dataset to include,
    // and asking for one would be asking for the host's.
    xkb_context *ctx = xkb_context_new(XKB_CONTEXT_NO_DEFAULT_INCLUDES);
    check(ctx != nullptr, "xkb_context_new");
    if (ctx == nullptr) {
        std::printf("\n%d check(s) failed\n", failures);
        return 1;
    }

    // ── 2. THE PARSER. This is what the fork exists for ──────────────────
    xkb_keymap *km = xkb_keymap_new_from_string(
        ctx, KEYMAP, XKB_KEYMAP_FORMAT_TEXT_V1, XKB_KEYMAP_COMPILE_NO_FLAGS);
    check(km != nullptr, "xkb_keymap_new_from_string compiled the keymap");
    if (km == nullptr) {
        xkb_context_unref(ctx);
        std::printf("\n%d check(s) failed\n", failures);
        return 1;
    }

    // ── 3. The compiled keymap answers about itself ──────────────────────
    const xkb_keycode_t min = xkb_keymap_min_keycode(km);
    const xkb_keycode_t max = xkb_keymap_max_keycode(km);
    std::printf("   keycodes %u..%u\n", min, max);
    check(min <= 9 && max >= 24, "…and its keycode range covers both keys");

    // ── 4. A key press produces the right keysym ─────────────────────────
    // This is the whole job: keycode in, keysym out, through the state
    // machine the compat and types sections drive.
    xkb_state *st = xkb_state_new(km);
    check(st != nullptr, "xkb_state_new");
    if (st != nullptr) {
        const xkb_keysym_t sym = xkb_state_key_get_one_sym(st, 24);
        char name[64] = {0};
        xkb_keysym_get_name(sym, name, sizeof name);
        std::printf("   keycode 24 -> keysym %s\n", name);
        check(sym == XKB_KEY_q, "keycode 24 resolves to the keysym 'q'");

        char buf[16] = {0};
        const int n = xkb_state_key_get_utf8(st, 24, buf, sizeof buf);
        std::printf("   utf8: \"%s\" (%d byte(s))\n", buf, n);
        check(n == 1 && buf[0] == 'q', "…and to the UTF-8 text \"q\"");

        const xkb_keysym_t esc = xkb_state_key_get_one_sym(st, 9);
        check(esc == XKB_KEY_Escape, "keycode 9 resolves to Escape");

        xkb_state_unref(st);
    }

    // ── 5. The keysym tables, which are their own generated data ─────────
    check(xkb_keysym_from_name("Escape", XKB_KEYSYM_NO_FLAGS) == XKB_KEY_Escape,
          "xkb_keysym_from_name resolves a name to its keysym");

    // ── 6. RMLVO, if a dataset is reachable ──────────────────────────────
    //
    // This is the OTHER half of libxkbcommon, and the half this package
    // deliberately cannot satisfy on its own: `xkb_keymap_new_from_names`
    // takes rules/model/layout/variant/options and reads them out of
    // xkeyboard-config's data tree. DFLT_XKB_CONFIG_ROOT is compiled in EMPTY
    // here on purpose, so the path has to come from the environment —
    // XKB_CONFIG_ROOT, which is what an ecosystem package declares.
    //
    // Reported rather than asserted when unset: a machine with no dataset is
    // not a defect in this package. When it IS set, the compile must succeed,
    // because then the dataset is the thing under test.
    {
        const char *root = std::getenv("XKB_CONFIG_ROOT");
        std::printf("\n   XKB_CONFIG_ROOT = %s\n",
                    root ? root : "(unset — the ecosystem declares it)");
        if (root != nullptr) {
            xkb_context *c2 = xkb_context_new(XKB_CONTEXT_NO_FLAGS);
            xkb_rule_names names{};
            names.rules  = "evdev";
            names.model  = "pc105";
            names.layout = "us";
            xkb_keymap *k2 = c2 ? xkb_keymap_new_from_names(
                c2, &names, XKB_KEYMAP_COMPILE_NO_FLAGS) : nullptr;
            check(k2 != nullptr,
                  "xkb_keymap_new_from_names(evdev/pc105/us) against that root");
            if (k2 != nullptr) {
                xkb_state *s2 = xkb_state_new(k2);
                if (s2 != nullptr) {
                    char b[16] = {0};
                    xkb_state_key_get_utf8(s2, 24, b, sizeof b);
                    std::printf("   real layout: keycode 24 -> \"%s\"\n", b);
                    check(b[0] == 'q',
                          "…and the real us layout maps keycode 24 to \"q\"");
                    xkb_state_unref(s2);
                }
                xkb_keymap_unref(k2);
            }
            if (c2) xkb_context_unref(c2);
        }
    }

    xkb_keymap_unref(km);
    xkb_context_unref(ctx);

    std::printf("\n%d check(s) failed\n", failures);
    return failures == 0 ? 0 : 1;
}

