// compat.mimalloc — assert the allocator is real, not just that it links.
//
// Every check below can fail: mi_usable_size reports what mimalloc actually
// reserved (so it proves the pointer came from mimalloc's own bookkeeping and
// not from a fallback), mi_zalloc must return zeroed memory, and a private
// heap must be able to hand out and destroy blocks independently of the
// default heap.
#include <mimalloc.h>
import std;

int main() {
    bool ok = true;

    auto check = [&](bool cond, std::string_view what) {
        if (!cond) {
            std::println("FAIL: {}", what);
            ok = false;
        }
    };

    // 1. Basic allocation, and mimalloc knows the block's real size.
    void* p = mi_malloc(1024);
    check(p != nullptr, "mi_malloc(1024) returned null");
    if (p) {
        // mimalloc rounds up to a size class, so usable >= requested.
        check(mi_usable_size(p) >= 1024, "mi_usable_size < requested size");
        std::memset(p, 0xAB, 1024);
        check(static_cast<unsigned char*>(p)[1023] == 0xAB, "written byte did not survive");
        mi_free(p);
    }

    // 2. mi_zalloc must actually zero.
    constexpr std::size_t n = 512;
    auto* z = static_cast<unsigned char*>(mi_zalloc(n));
    check(z != nullptr, "mi_zalloc returned null");
    if (z) {
        check(std::all_of(z, z + n, [](unsigned char c) { return c == 0; }),
              "mi_zalloc did not zero the block");
        mi_free(z);
    }

    // 3. Aligned allocation honours the alignment.
    void* a = mi_malloc_aligned(256, 64);
    check(a != nullptr, "mi_malloc_aligned returned null");
    if (a) {
        check(reinterpret_cast<std::uintptr_t>(a) % 64 == 0, "alignment not honoured");
        mi_free(a);
    }

    // 4. A private heap allocates and tears down independently.
    mi_heap_t* heap = mi_heap_new();
    check(heap != nullptr, "mi_heap_new returned null");
    if (heap) {
        void* hp = mi_heap_malloc(heap, 4096);
        check(hp != nullptr, "mi_heap_malloc returned null");
        check(mi_heap_contains(heap, hp), "heap does not contain its own block");
        mi_heap_destroy(heap);  // frees hp with it
    }

    std::println("compat.mimalloc smoke test: {}", ok ? "ok" : "FAILED");
    return ok ? 0 : 1;
}

// compat.miniaudio — encode a WAV, decode it back, and assert the samples
// survive the round trip.
//
// Deliberately DEVICE-FREE. A CI runner has no sound card, so ma_device_init
// would fail for reasons that say nothing about the package. The encoder,
// decoder and the WAV codec behind them are the parts that can be asserted
// anywhere, and they still prove the implementation TU (miniaudio.c) is
// compiled and linked -- none of these symbols exist without it.
#include <miniaudio.h>
import std;

int main() {
    bool ok = true;
    auto check = [&](bool cond, std::string_view what) {
        if (!cond) {
            std::println("FAIL: {}", what);
            ok = false;
        }
    };

    constexpr ma_uint32 RATE     = 48000;
    constexpr ma_uint32 CHANNELS = 1;
    constexpr ma_uint64 FRAMES   = 4800;      // 100 ms
    const std::string   path     = "miniaudio_roundtrip.wav";

    // A 480 Hz sine: 10 whole cycles in 4800 frames, so the signal is
    // continuous and its extremes are hit exactly.
    std::vector<float> written(FRAMES);
    for (ma_uint64 i = 0; i < FRAMES; ++i) {
        written[i] = 0.5f * std::sin(2.0f * std::numbers::pi_v<float> *
                                     480.0f * static_cast<float>(i) / RATE);
    }

    // ---- encode ----------------------------------------------------------
    {
        ma_encoder_config cfg =
            ma_encoder_config_init(ma_encoding_format_wav, ma_format_f32, CHANNELS, RATE);
        ma_encoder enc;
        check(ma_encoder_init_file(path.c_str(), &cfg, &enc) == MA_SUCCESS,
              "encoder opened the output file");

        ma_uint64 put = 0;
        check(ma_encoder_write_pcm_frames(&enc, written.data(), FRAMES, &put) == MA_SUCCESS,
              "encoder accepted the frames");
        check(put == FRAMES, "encoder wrote every frame");
        ma_encoder_uninit(&enc);
    }

    // ---- decode ----------------------------------------------------------
    {
        ma_decoder_config cfg = ma_decoder_config_init(ma_format_f32, CHANNELS, RATE);
        ma_decoder dec;
        check(ma_decoder_init_file(path.c_str(), &cfg, &dec) == MA_SUCCESS,
              "decoder opened the file just written");

        check(dec.outputSampleRate == RATE, "decoded sample rate matches");
        check(dec.outputChannels == CHANNELS, "decoded channel count matches");

        ma_uint64 total = 0;
        check(ma_decoder_get_length_in_pcm_frames(&dec, &total) == MA_SUCCESS,
              "decoder reported a length");
        check(total == FRAMES, "decoded length matches what was encoded");

        std::vector<float> read(FRAMES, 0.0f);
        ma_uint64 got = 0;
        check(ma_decoder_read_pcm_frames(&dec, read.data(), FRAMES, &got) == MA_SUCCESS,
              "decoder returned frames");
        check(got == FRAMES, "decoder returned every frame");

        // f32 WAV is lossless, so this is an equality check within float noise.
        float worst = 0.0f;
        for (ma_uint64 i = 0; i < got; ++i) {
            worst = std::max(worst, std::abs(read[i] - written[i]));
        }
        check(worst < 1e-5f, "samples survive the round trip");

        // Guard against the degenerate pass: silence would also round-trip.
        float peak = 0.0f;
        for (float v : read) peak = std::max(peak, std::abs(v));
        check(peak > 0.45f, "decoded signal is the sine, not silence");

        ma_decoder_uninit(&dec);
    }

    std::error_code ec;
    std::filesystem::remove(path, ec);

    if (ok) std::println("miniaudio OK");
    return ok ? 0 : 1;
}

// Behavioral test — compat.mio actually maps a file.
//
// The test writes its own file into the working directory, maps it, reads
// through the mapping and then writes through a second mapping. Nothing here
// depends on the runner's filesystem layout beyond "can create a file", which
// is true on all three CI platforms.
#include <mio/mmap.hpp>

#include <cstdio>
#include <fstream>
#include <string>
#include <system_error>

int main() {
    const std::string path = "mcpp_mio_test.bin";
    const std::string payload = "mcpp-index mio round trip";

    {
        std::ofstream out(path, std::ios::binary | std::ios::trunc);
        out.write(payload.data(), static_cast<std::streamsize>(payload.size()));
    }

    std::error_code ec;
    // Read mapping: the bytes must come back through the mapping, not through
    // a copy — a broken include root cannot get this far, but a mio that
    // mapped nothing would return an empty range.
    mio::mmap_source ro = mio::make_mmap_source(path, 0, mio::map_entire_file, ec);
    if (ec) { std::printf("make_mmap_source failed: %s\n", ec.message().c_str()); std::remove(path.c_str()); return 1; }
    if (ro.size() != payload.size() || std::string(ro.begin(), ro.end()) != payload) {
        std::printf("mapped content differs\n");
        std::remove(path.c_str());
        return 2;
    }
    ro.unmap();

    // Write mapping: mutate through the map, flush, and read the file back
    // with ordinary I/O. This is the half that proves it is a real mapping and
    // not a buffered read.
    mio::mmap_sink rw = mio::make_mmap_sink(path, 0, mio::map_entire_file, ec);
    if (ec) { std::printf("make_mmap_sink failed: %s\n", ec.message().c_str()); std::remove(path.c_str()); return 3; }
    rw[0] = 'M';
    rw.sync(ec);
    if (ec) { std::printf("sync failed: %s\n", ec.message().c_str()); std::remove(path.c_str()); return 4; }
    rw.unmap();

    std::string back;
    {
        std::ifstream in(path, std::ios::binary);
        back.assign(std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>());
    }
    std::remove(path.c_str());

    if (back.empty() || back[0] != 'M') { std::printf("write through the mapping did not reach the file\n"); return 5; }

    std::printf("compat.mio: ok (mapped %zu bytes, read back and wrote through)\n", payload.size());
    return 0;
}

// compat.msdfgen — generate a real multi-channel signed distance field and
// assert its contents, not just that the library links.
//
// The shape is a square built by hand, so the test needs no font file and no
// ext/ importer. What makes the assertions real:
//   * the field must be signed -- inside the square the distance is positive,
//     outside it is negative. A blank or all-zero bitmap fails both.
//   * edge colouring must have run, otherwise the three channels are identical
//     and the "multi-channel" part of MSDF did nothing.
//
// The `msdfgen/` include prefix is the one this package generates; using it
// here is what keeps the shim covered by CI.
#include <msdfgen/msdfgen.h>
#include <msdfgen/msdfgen-ext.h>
import std;

int main() {
    bool ok = true;

    auto check = [&](bool cond, std::string_view what) {
        if (!cond) {
            std::println("FAIL: {}", what);
            ok = false;
        }
    };

    // A 16x16 axis-aligned square, inset from the 32x32 bitmap so that both
    // the inside and the outside are sampled.
    msdfgen::Shape shape;
    msdfgen::Contour& contour = shape.addContour();
    const msdfgen::Point2 p0(8, 8), p1(24, 8), p2(24, 24), p3(8, 24);
    contour.addEdge(msdfgen::EdgeHolder(p0, p1));
    contour.addEdge(msdfgen::EdgeHolder(p1, p2));
    contour.addEdge(msdfgen::EdgeHolder(p2, p3));
    contour.addEdge(msdfgen::EdgeHolder(p3, p0));

    shape.normalize();
    check(shape.validate(), "hand-built shape did not validate");

    // Winding decides the sign of the field, and the order above is not
    // guaranteed to be the one msdfgen calls "inside". orientContours() is
    // upstream's own normalizer for exactly this (its standalone tool runs it
    // on imported geometry), so the assertions below can talk about inside and
    // outside without depending on how the contour happened to be written.
    shape.orientContours();

    msdfgen::edgeColoringSimple(shape, 3.0);

    msdfgen::Bitmap<float, 3> msdf(32, 32);
    msdfgen::SDFTransformation t(
        msdfgen::Projection(msdfgen::Vector2(1.0), msdfgen::Vector2(0.0)),
        msdfgen::Range(4.0));
    msdfgen::generateMSDF(msdf, shape, t);

    // Median of the three channels is the reconstructed signed distance.
    auto median_at = [&](int x, int y) {
        const float* px = msdf(x, y);
        return msdfgen::median(px[0], px[1], px[2]);
    };

    // Centre of the square is inside → positive; a corner of the bitmap is
    // far outside → negative. msdfgen encodes 0.5 as the edge.
    const float inside = median_at(16, 16);
    const float outside = median_at(0, 0);
    check(inside > 0.5f, std::format("centre should read inside, got {}", inside));
    check(outside < 0.5f, std::format("corner should read outside, got {}", outside));

    // Multi-channel: at least one pixel must have channels that differ,
    // otherwise edge colouring never ran and this is a plain SDF.
    bool multi_channel = false;
    for (int y = 0; y < 32 && !multi_channel; ++y) {
        for (int x = 0; x < 32; ++x) {
            const float* px = msdf(x, y);
            if (px[0] != px[1] || px[1] != px[2]) {
                multi_channel = true;
                break;
            }
        }
    }
    check(multi_channel, "all three channels identical — edge colouring did not run");

    // ext/import-font is compiled in: initializing FreeType through msdfgen
    // proves the FreeType-backed half of the package is present, and that the
    // transitive compat.freetype dependency reached the link line.
    msdfgen::FreetypeHandle* ft = msdfgen::initializeFreetype();
    check(ft != nullptr, "msdfgen::initializeFreetype returned null");
    if (ft) {
        msdfgen::deinitializeFreetype(ft);
    }

    std::println("compat.msdfgen smoke test: {} (inside={:.3f} outside={:.3f})",
                 ok ? "ok" : "FAILED", inside, outside);
    return ok ? 0 : 1;
}

// compat.mtdev — behavioral test, no input device required.
//
// mtdev translates kernel multitouch protocol A into protocol B. The test
// exercises the translator's own state machine rather than a device: the
// interesting failure is a package that links but whose slot machinery was
// compiled out, and that shows up here rather than on a touchscreen.

#ifdef __linux__

#include <mtdev.h>
#include <mtdev-plumbing.h>
#include <linux/input.h>

#include <cstdio>
#include <cstring>

namespace {
int failures = 0;
void check(bool ok, const char *what)
{
    std::printf("%-58s %s\n", what, ok ? "ok" : "FAILED");
    if (!ok) ++failures;
}
} // namespace

int main()
{
    // ── 1. A device object can be created and configured ─────────────────
    // mtdev_new/mtdev_init are the plumbing entry points: they set up the
    // slot state without needing an fd, which is what makes this testable.
    mtdev *dev = mtdev_new();
    check(dev != nullptr, "mtdev_new allocates a translator");
    if (dev == nullptr) {
        std::printf("\n%d check(s) failed\n", failures);
        return 1;
    }
    check(mtdev_init(dev) == 0, "mtdev_init sets up the slot state machine");

    // ── 2. It reports what it can translate ──────────────────────────────
    // ABS_MT_POSITION_X is the axis every protocol-A device carries; asking
    // about it exercises the capability table the translator is built from.
    mtdev_set_mt_event(dev, ABS_MT_POSITION_X, 1);
    check(mtdev_has_mt_event(dev, ABS_MT_POSITION_X) != 0,
          "a multitouch axis can be declared and read back");
    mtdev_set_mt_event(dev, ABS_MT_POSITION_X, 0);
    check(mtdev_has_mt_event(dev, ABS_MT_POSITION_X) == 0,
          "…and cleared again");

    // ── 3. With nothing fed in, nothing comes out ────────────────────────
    // mtdev_empty is the drain check libinput calls in its read loop. On a
    // fresh translator it must be true — a package whose buffers were
    // compiled wrong tends to report data that was never written.
    check(mtdev_empty(dev) != 0, "a fresh translator has no pending events");

    mtdev_close(dev);
    mtdev_delete(dev);
    check(true, "mtdev_close and mtdev_delete complete");

    std::printf("\n%d check(s) failed\n", failures);
    return failures == 0 ? 0 : 1;
}

#else
int main() { return 0; }
#endif

