// compat.plf-hive — assert the guarantee that distinguishes a hive from a
// vector or a deque: an element's ADDRESS stays valid while its neighbours are
// erased and while new elements are inserted. If the package silently resolved
// to something else, or the header were stubbed, these checks fail rather than
// passing vacuously.
#include <plf_hive.h>
import std;

int main() {
    bool ok = true;
    auto check = [&](bool cond, std::string_view what) {
        if (!cond) {
            std::println("FAIL: {}", what);
            ok = false;
        }
    };

    plf::hive<int> h;

    // Fill, and remember where a few elements physically live.
    std::vector<plf::hive<int>::iterator> its;
    for (int i = 0; i < 200; ++i) its.push_back(h.insert(i));
    check(h.size() == 200, "size after 200 inserts");

    const int* addr_of_50  = &*its[50];
    const int* addr_of_150 = &*its[150];

    // Erase every even element. In a vector this would invalidate everything
    // after the first erasure; in a hive nothing moves.
    std::size_t erased = 0;
    for (int i = 0; i < 200; i += 2) {
        h.erase(its[static_cast<std::size_t>(i)]);
        ++erased;
    }
    check(erased == 100, "erased 100 elements");
    check(h.size() == 100, "size after erasures");
    check(&*its[51] != nullptr, "surviving iterator still dereferenceable");
    check(addr_of_50 != nullptr && addr_of_150 != nullptr, "addresses captured");

    // Odd elements survived, at their original addresses.
    const int* addr_of_51 = &*its[51];
    check(*its[51] == 51, "surviving element keeps its value");

    // Inserting again reuses the erased slots -- and must not relocate anything.
    for (int i = 0; i < 100; ++i) h.insert(1000 + i);
    check(h.size() == 200, "size after refill");
    check(&*its[51] == addr_of_51, "address stable across erase + insert");
    check(*its[51] == 51, "value stable across erase + insert");

    // The surviving originals are exactly the odd numbers.
    long odd_sum = 0;
    long expected = 0;
    for (int v : h) if (v < 1000) odd_sum += v;
    for (int i = 1; i < 200; i += 2) expected += i;
    check(odd_sum == expected, "surviving elements are exactly the odd ones");

    // Erasing through the range interface and clearing must leave it empty.
    h.clear();
    check(h.empty(), "empty after clear");
    check(h.begin() == h.end(), "begin == end when empty");

    if (ok) std::println("plf::hive OK");
    return ok ? 0 : 1;
}

// Behavioral test for compat.protobuf's `gzip` feature.
//
// io/gzip_stream.cc is wrapped head-to-toe in `#if HAVE_ZLIB`, so with the
// feature OFF the TU is empty and GzipOutputStream / GzipInputStream have no
// definitions — this member therefore fails to LINK without the feature,
// which is the negative half of the verification (see the design doc).
//
// With it on: compress a payload, assert the compressed form is actually
// smaller and is a real gzip stream (magic 0x1f 0x8b), then decompress and
// assert byte equality.
#include <string>

#include "google/protobuf/io/coded_stream.h"
#include "google/protobuf/io/gzip_stream.h"
#include "google/protobuf/io/zero_copy_stream_impl_lite.h"

namespace gpb = google::protobuf;

namespace {

std::string make_payload() {
    // Highly repetitive, so a working deflate must shrink it a lot. Random
    // data would leave "compressed" ~= "original" and make the size assertion
    // meaningless.
    std::string s;
    for (int i = 0; i < 2000; ++i) s += "the quick brown fox jumps over the lazy dog\n";
    return s;
}

bool compress(const std::string& in, std::string* out) {
    gpb::io::StringOutputStream sink(out);
    gpb::io::GzipOutputStream::Options opts;
    opts.format = gpb::io::GzipOutputStream::GZIP;
    gpb::io::GzipOutputStream gz(&sink, opts);
    {
        // GzipOutputStream is a ZeroCopyOutputStream (Next/BackUp); CodedOutputStream
        // is the adapter that turns that into a plain buffer write. It must be
        // destroyed — i.e. flushed back into gz — before gz.Close().
        gpb::io::CodedOutputStream coded(&gz);
        coded.WriteRaw(in.data(), static_cast<int>(in.size()));
        if (coded.HadError()) return false;
    }
    return gz.Close();
}

bool decompress(const std::string& in, std::string* out) {
    gpb::io::ArrayInputStream source(in.data(), static_cast<int>(in.size()));
    gpb::io::GzipInputStream gz(&source, gpb::io::GzipInputStream::GZIP);

    const void* chunk = nullptr;
    int size = 0;
    while (gz.Next(&chunk, &size)) {
        if (size > 0) out->append(static_cast<const char*>(chunk), static_cast<std::size_t>(size));
    }
    return gz.ZlibErrorMessage() == nullptr;
}

}  // namespace

int main() {
    const std::string original = make_payload();

    std::string compressed;
    if (!compress(original, &compressed)) return 1;

    // A real gzip member starts with the 0x1f 0x8b magic.
    if (compressed.size() < 2) return 1;
    if (static_cast<unsigned char>(compressed[0]) != 0x1f) return 1;
    if (static_cast<unsigned char>(compressed[1]) != 0x8b) return 1;

    // Repetitive input must compress substantially; this also proves deflate
    // ran rather than the stream passing bytes through.
    if (compressed.size() >= original.size() / 10) return 1;

    std::string restored;
    if (!decompress(compressed, &restored)) return 1;

    return restored == original ? 0 : 1;
}

// Behavioral test for compat.protobuf's `protoc` target.
//
// Every type used here was emitted DURING THIS BUILD by a protoc that mcpp
// compiled from the same package that provides the runtime being linked. The
// test therefore asserts the thing that actually matters about a code
// generator shipped as a dependency: that its output and the runtime agree.
//
// What it drives, and what would break first on a generator/runtime mismatch:
//
//   nested message + accessors    generated_message_reflection.cc
//   enum                          generated_enum_util.cc
//   repeated message field        repeated_ptr_field.cc
//   map field                     map_field.cc
//   oneof                         the generated case() discriminator
//   well-known type import        timestamp.pb.cc  (proves the -I resolved)
//   serialize -> parse round trip wire_format_lite.cc, parse_context.cc
//   reflection over generated msg descriptor.cc against the generated pool
//
// Returns non-zero on any mismatch.
#include <cstdio>
#include <string>

// compat.protobuf declares no `protoc` target on windows, so nothing was
// generated and there is nothing to assert. A loud skip beats a test that
// passes without exercising anything.
#ifdef _WIN32
int main() {
    std::puts("skipped: compat.protobuf has no protoc target on windows");
    return 0;
}
#else

#include "google/protobuf/util/time_util.h"

#include "inventory.pb.h"

namespace {

int failures = 0;

void check(bool ok, const char* what) {
    if (!ok) {
        std::fprintf(stderr, "FAIL: %s\n", what);
        ++failures;
    }
}

}  // namespace

int main() {
    GOOGLE_PROTOBUF_VERIFY_VERSION;

    inventory::Inventory inv;

    inventory::Item* widget = inv.add_items();
    widget->set_sku("WIDGET-1");
    widget->set_quantity(7);
    widget->set_grade(inventory::GRADE_A);
    widget->mutable_dimensions()->set_width(2.5);
    widget->mutable_dimensions()->set_height(4.0);
    widget->set_supplier("acme");

    inventory::Item* gizmo = inv.add_items();
    gizmo->set_sku("GIZMO-2");
    gizmo->set_quantity(3);
    gizmo->set_grade(inventory::GRADE_B);
    gizmo->set_warehouse("east");

    (*inv.mutable_totals_by_grade())["A"] = 7;
    (*inv.mutable_totals_by_grade())["B"] = 3;

    // The well-known type. Reaching this line at all proves protoc resolved
    // the import, and setting it proves timestamp.pb.cc is in the runtime.
    *inv.mutable_updated_at() =
        google::protobuf::util::TimeUtil::SecondsToTimestamp(1735689600);

    std::string wire;
    check(inv.SerializeToString(&wire), "serialize");
    check(!wire.empty(), "wire is non-empty");

    inventory::Inventory back;
    check(back.ParseFromString(wire), "parse");

    check(back.items_size() == 2, "two items survived the round trip");
    check(back.items(0).sku() == "WIDGET-1", "item 0 sku");
    check(back.items(0).quantity() == 7, "item 0 quantity");
    check(back.items(0).grade() == inventory::GRADE_A, "item 0 enum");
    check(back.items(0).dimensions().width() == 2.5, "nested message field");
    check(back.items(0).source_case() == inventory::Item::kSupplier,
          "oneof discriminator (supplier)");
    check(back.items(0).supplier() == "acme", "oneof value");
    check(back.items(1).source_case() == inventory::Item::kWarehouse,
          "oneof discriminator (warehouse)");
    check(back.totals_by_grade().size() == 2, "map size");
    check(back.totals_by_grade().at("A") == 7, "map lookup");
    check(google::protobuf::util::TimeUtil::TimestampToSeconds(
              back.updated_at()) == 1735689600,
          "well-known Timestamp round trip");

    // Reflection over the generated pool: the descriptor protoc emitted has to
    // describe the C++ class it emitted beside it.
    const google::protobuf::Descriptor* d = inventory::Item::descriptor();
    check(d != nullptr && d->full_name() == "inventory.Item",
          "descriptor full name");
    check(d != nullptr && d->FindFieldByName("sku") != nullptr,
          "descriptor knows the sku field");
    check(d != nullptr && d->oneof_decl_count() == 1,
          "descriptor knows the oneof");

    google::protobuf::ShutdownProtobufLibrary();

    if (failures != 0) {
        std::fprintf(stderr, "%d check(s) failed\n", failures);
        return 1;
    }
    std::puts("protoc-generated code round-trips against the linked runtime");
    return 0;
}

