// Behavioral test for compat.protobuf's `upb` feature.
//
// Drives BOTH runtimes across the same bytes, which is the strongest thing
// this member can assert: the C++ runtime builds a FileDescriptorProto and
// serializes it, then upb parses those bytes and loads them into a upb_DefPool
// and answers reflection queries about them.
//
// What that reaches:
//   upb_Arena / upb_DefPool        -> upb/mem/arena.c, reflection/def_pool.c
//   parse of a descriptor message  -> upb/wire/decode.c, message/*.c, mini_table/*.c
//   AddFile + name lookups         -> upb/reflection/{file,message,field}_def.c
//   the descriptor tables themselves -> upb/reflection/cmake/…/descriptor.upb_minitable.c
//
// That last one is the reason this test exists in this shape: those tables are
// NOT in upstream's libupb_srcs, they come from cmake/libupb.cmake's
// bootstrap_sources, and leaving them out fails only at LINK time. Anything
// that merely compiles upb would not notice.
//
// Returns non-zero on any mismatch.
#include <cstddef>
#include <string>

#include "google/protobuf/descriptor.pb.h"

// NOT wrapped in extern "C": upb's headers manage their own linkage, and
// upb/message/accessors.h deliberately declares C++ OVERLOADS outside the
// extern "C" block. Forcing the whole tree into C linkage makes those overloads
// collide with their C counterparts ("conflicting declaration of C function").
#include "google/protobuf/descriptor.upb.h"
#include "upb/base/status.h"
#include "upb/mem/arena.h"
#include "upb/reflection/def_pool.h"
#include "upb/reflection/field_def.h"
#include "upb/reflection/file_def.h"
#include "upb/reflection/message_def.h"

namespace gpb = google::protobuf;

namespace {

// Build the schema with the C++ runtime and hand upb its wire bytes.
std::string make_descriptor_bytes() {
    gpb::FileDescriptorProto file;
    file.set_name("mcpp_upb_test.proto");
    file.set_package("mcpp.test");
    file.set_syntax("proto3");

    gpb::DescriptorProto* msg = file.add_message_type();
    msg->set_name("Person");

    gpb::FieldDescriptorProto* name = msg->add_field();
    name->set_name("name");
    name->set_number(1);
    name->set_type(gpb::FieldDescriptorProto::TYPE_STRING);
    name->set_label(gpb::FieldDescriptorProto::LABEL_OPTIONAL);

    gpb::FieldDescriptorProto* id = msg->add_field();
    id->set_name("id");
    id->set_number(2);
    id->set_type(gpb::FieldDescriptorProto::TYPE_INT32);
    id->set_label(gpb::FieldDescriptorProto::LABEL_OPTIONAL);

    return file.SerializeAsString();
}

}  // namespace

int main() {
    const std::string wire = make_descriptor_bytes();
    if (wire.empty()) return 1;

    upb_Arena* arena = upb_Arena_New();
    if (arena == nullptr) return 1;

    // upb parses what the C++ runtime wrote.
    google_protobuf_FileDescriptorProto* parsed =
        google_protobuf_FileDescriptorProto_parse(wire.data(), wire.size(), arena);
    if (parsed == nullptr) {
        upb_Arena_Free(arena);
        return 1;
    }

    upb_DefPool* pool = upb_DefPool_New();
    if (pool == nullptr) {
        upb_Arena_Free(arena);
        return 1;
    }

    upb_Status status;
    upb_Status_Clear(&status);
    const upb_FileDef* file_def = upb_DefPool_AddFile(pool, parsed, &status);

    int rc = 1;
    if (file_def != nullptr) {
        const upb_MessageDef* msg = upb_DefPool_FindMessageByName(pool, "mcpp.test.Person");
        if (msg != nullptr && upb_MessageDef_FieldCount(msg) == 2) {
            const upb_FieldDef* f_name = upb_MessageDef_FindFieldByName(msg, "name");
            const upb_FieldDef* f_id = upb_MessageDef_FindFieldByName(msg, "id");
            const bool names_ok =
                std::string(upb_FileDef_Name(file_def)) == "mcpp_upb_test.proto" &&
                std::string(upb_MessageDef_FullName(msg)) == "mcpp.test.Person";
            // A name that was never declared must NOT resolve — otherwise a
            // stub lookup returning something would pass everything above.
            const bool absent_ok =
                upb_DefPool_FindMessageByName(pool, "mcpp.test.Missing") == nullptr;
            if (f_name != nullptr && f_id != nullptr && names_ok && absent_ok &&
                upb_FieldDef_Number(f_name) == 1 && upb_FieldDef_Number(f_id) == 2) {
                rc = 0;
            }
        }
    }

    upb_DefPool_Free(pool);
    upb_Arena_Free(arena);
    return rc;
}

// Behavioral test for compat.protobuf (the libprotobuf runtime).
//
// Deliberately uses NO protoc-generated code: the package ships the runtime,
// not the compiler, so this drives the surface a consumer actually gets —
//
//   .proto text -> descriptor      compiler/parser.cc, io/tokenizer.cc
//   descriptor -> message          descriptor.cc, dynamic_message.cc
//   set/get fields                 generated_message_reflection.cc, map_field.cc
//   serialize / parse              wire_format.cc, parse_context.cc, coded_stream.cc
//   TextFormat                     text_format.cc
//   JSON                           json/json.cc + json/internal/*.cc
//   well-known types               timestamp.pb.cc, struct.pb.cc, util/time_util.cc
//   MessageDifferencer             util/message_differencer.cc
//   UTF-8 validation               third_party/utf8_range/utf8_range.c
//
// Returns non-zero on any mismatch.
#include <memory>
#include <string>

#include "google/protobuf/compiler/parser.h"
#include "google/protobuf/descriptor.h"
#include "google/protobuf/descriptor.pb.h"
#include "google/protobuf/dynamic_message.h"
#include "google/protobuf/io/tokenizer.h"
#include "google/protobuf/io/zero_copy_stream_impl_lite.h"
#include "google/protobuf/json/json.h"
#include "google/protobuf/struct.pb.h"
#include "google/protobuf/text_format.h"
#include "google/protobuf/timestamp.pb.h"
#include "google/protobuf/util/message_differencer.h"
#include "google/protobuf/util/time_util.h"

namespace gpb = google::protobuf;

namespace {

// Collects parse errors instead of printing them, so a broken schema shows up
// as a failed assertion rather than noise on stderr.
class SilentErrorCollector : public gpb::io::ErrorCollector {
public:
    void RecordError(int line, gpb::io::ColumnNumber col, absl::string_view msg) override {
        ++errors;
        (void)line;
        (void)col;
        (void)msg;
    }
    int errors = 0;
};

constexpr const char* kSchema = R"(
    syntax = "proto3";
    package mcpp.test;
    message Person {
      string name = 1;
      int32  id = 2;
      repeated string tags = 3;
      map<string, int32> scores = 4;
    }
)";

// Parse the .proto TEXT above into a FileDescriptorProto. This is the runtime's
// own parser (compiler/parser.cc), not protoc.
bool build_pool(gpb::DescriptorPool& pool, const gpb::Descriptor** out) {
    gpb::io::ArrayInputStream raw(kSchema, static_cast<int>(std::string(kSchema).size()));
    SilentErrorCollector collector;
    gpb::io::Tokenizer tokenizer(&raw, &collector);

    gpb::FileDescriptorProto file;
    gpb::compiler::Parser parser;
    parser.RecordErrorsTo(&collector);
    if (!parser.Parse(&tokenizer, &file) || collector.errors != 0) return false;
    file.set_name("mcpp_test.proto");

    const gpb::FileDescriptor* fd = pool.BuildFile(file);
    if (fd == nullptr) return false;
    *out = pool.FindMessageTypeByName("mcpp.test.Person");
    return *out != nullptr;
}

bool dynamic_message_roundtrip(const gpb::Descriptor* desc) {
    gpb::DynamicMessageFactory factory;
    const gpb::Message* prototype = factory.GetPrototype(desc);
    if (prototype == nullptr) return false;

    std::unique_ptr<gpb::Message> msg(prototype->New());
    const gpb::Reflection* ref = msg->GetReflection();

    ref->SetString(msg.get(), desc->FindFieldByName("name"), "Ada");
    ref->SetInt32(msg.get(), desc->FindFieldByName("id"), 1815);
    const gpb::FieldDescriptor* tags = desc->FindFieldByName("tags");
    ref->AddString(msg.get(), tags, "math");
    ref->AddString(msg.get(), tags, "engine");

    // Wire round-trip.
    std::string wire;
    if (!msg->SerializeToString(&wire)) return false;
    std::unique_ptr<gpb::Message> back(prototype->New());
    if (!back->ParseFromString(wire)) return false;
    if (!gpb::util::MessageDifferencer::Equals(*msg, *back)) return false;

    // TextFormat round-trip.
    std::string text;
    if (!gpb::TextFormat::PrintToString(*back, &text)) return false;
    if (text.find("name: \"Ada\"") == std::string::npos) return false;
    if (text.find("id: 1815") == std::string::npos) return false;
    std::unique_ptr<gpb::Message> from_text(prototype->New());
    if (!gpb::TextFormat::ParseFromString(text, from_text.get())) return false;
    if (!gpb::util::MessageDifferencer::Equals(*msg, *from_text)) return false;

    // A truncated payload must be REJECTED — proves parsing is real and not a
    // no-op that accepts anything.
    std::unique_ptr<gpb::Message> truncated(prototype->New());
    if (!wire.empty() && truncated->ParseFromString(wire.substr(0, wire.size() - 1))) return false;

    return ref->GetRepeatedString(*back, tags, 1) == "engine";
}

bool json_ok(const gpb::Descriptor* desc) {
    gpb::DynamicMessageFactory factory;
    std::unique_ptr<gpb::Message> msg(factory.GetPrototype(desc)->New());
    const gpb::Reflection* ref = msg->GetReflection();
    ref->SetString(msg.get(), desc->FindFieldByName("name"), "Grace");
    ref->SetInt32(msg.get(), desc->FindFieldByName("id"), 1906);

    std::string json;
    if (!gpb::json::MessageToJsonString(*msg, &json).ok()) return false;
    if (json.find("\"name\":\"Grace\"") == std::string::npos) return false;

    std::unique_ptr<gpb::Message> back(factory.GetPrototype(desc)->New());
    if (!gpb::json::JsonStringToMessage(json, back.get()).ok()) return false;
    return gpb::util::MessageDifferencer::Equals(*msg, *back);
}

// The well-known types are generated code that upstream CHECKS IN, so they are
// compiled into this package and usable with no protoc anywhere.
bool well_known_types_ok() {
    gpb::Timestamp ts;
    if (!gpb::util::TimeUtil::FromString("2026-08-04T12:34:56Z", &ts)) return false;
    if (gpb::util::TimeUtil::ToString(ts) != "2026-08-04T12:34:56Z") return false;

    gpb::Struct s;
    (*s.mutable_fields())["pi"].set_number_value(3.5);
    (*s.mutable_fields())["name"].set_string_value("mcpp");
    if (s.fields().size() != 2) return false;
    if (s.fields().at("pi").number_value() != 3.5) return false;

    std::string wire;
    if (!s.SerializeToString(&wire)) return false;
    gpb::Struct back;
    return back.ParseFromString(wire) && back.fields().at("name").string_value() == "mcpp";
}

// proto3 string fields are UTF-8 validated, which routes into
// third_party/utf8_range/utf8_range.c — the one C TU in this package.
bool utf8_validation_ok(const gpb::Descriptor* desc) {
    gpb::DynamicMessageFactory factory;
    std::unique_ptr<gpb::Message> msg(factory.GetPrototype(desc)->New());
    msg->GetReflection()->SetString(msg.get(), desc->FindFieldByName("name"), "héllo-世界");

    std::string wire;
    if (!msg->SerializeToString(&wire)) return false;
    std::unique_ptr<gpb::Message> back(factory.GetPrototype(desc)->New());
    if (!back->ParseFromString(wire)) return false;
    return back->GetReflection()->GetString(*back, desc->FindFieldByName("name")) == "héllo-世界";
}

}  // namespace

int main() {
    gpb::DescriptorPool pool;
    const gpb::Descriptor* person = nullptr;
    if (!build_pool(pool, &person)) return 1;

    const bool ok = dynamic_message_roundtrip(person) && json_ok(person)
                    && well_known_types_ok() && utf8_validation_ok(person);
    return ok ? 0 : 1;
}

// Behavioral test: JavaScript evaluated by the engine, checked by value.
//
// The package compiles four sources, and each group below needs one of them to
// be present and built with the right flags, so a missing or mis-built TU shows
// up as a wrong answer rather than only as a link error:
//
//   quickjs.c     evaluation, closures, exceptions, the promise job queue
//   dtoa.c        shortest round-trip number formatting (0.1 + 0.2, 5e-324)
//   libregexp.c   named groups, case-insensitive and sticky matching
//   libunicode.c  full case mapping, NFC normalization, script properties
//
// The expected strings are what the ECMAScript specification requires, written
// out by hand; none is computed by the code under test.
//
// The runtime is freed at the end. The package does not define NDEBUG, so
// JS_FreeRuntime asserts that no object is still alive (quickjs.c:2699) and an
// object this test forgot to free aborts it.

#ifdef __linux__

#include <quickjs.h>

#include <cstdio>
#include <cstring>
#include <string>

// The descriptor exposes quickjs.h alone. The engine's private headers sit next
// to it in the tarball and must not reach a consumer.
#if __has_include(<cutils.h>) || __has_include(<libregexp.h>)
#error "compat.quickjs-ng put the engine's private headers on the include path"
#endif

namespace {

int failures = 0;

std::string to_std_string(JSContext* ctx, JSValueConst v) {
    const char* s = JS_ToCString(ctx, v);
    std::string out = s ? s : "<ToCString failed>";
    JS_FreeCString(ctx, s);
    return out;
}

// Global code; the completion value of the last statement is the result.
std::string run_js(JSContext* ctx, const char* src) {
    JSValue v = JS_Eval(ctx, src, std::strlen(src), "<test>", JS_EVAL_TYPE_GLOBAL);
    std::string out;
    if (JS_IsException(v)) {
        JSValue exc = JS_GetException(ctx);
        out = "exception " + to_std_string(ctx, exc);
        JS_FreeValue(ctx, exc);
    } else {
        out = to_std_string(ctx, v);
    }
    JS_FreeValue(ctx, v);
    return out;
}

void expect(JSContext* ctx, const char* src, const char* want) {
    std::string got = run_js(ctx, src);
    if (got != want) {
        std::fprintf(stderr, "FAIL %s\n  want: %s\n  got:  %s\n", src, want, got.c_str());
        ++failures;
    }
}

}  // namespace

int main() {
    // The library and the header it was built from agree on the version.
    char header_version[32];
    std::snprintf(header_version, sizeof header_version, "%d.%d.%d%s",
                  QJS_VERSION_MAJOR, QJS_VERSION_MINOR, QJS_VERSION_PATCH, QJS_VERSION_SUFFIX);
    std::printf("QuickJS-ng %s\n", JS_GetVersion());
    if (std::strcmp(JS_GetVersion(), "0.17.0") != 0 ||
        std::strcmp(JS_GetVersion(), header_version) != 0) {
        std::fprintf(stderr, "FAIL version: library %s, header %s\n", JS_GetVersion(), header_version);
        ++failures;
    }

    JSRuntime* rt = JS_NewRuntime();
    JSContext* ctx = rt ? JS_NewContext(rt) : nullptr;
    if (ctx == nullptr) {
        std::fprintf(stderr, "FAIL could not create a runtime and context\n");
        return 1;
    }

    // quickjs.c
    expect(ctx, "const sq = [1, 2, 3].map(x => x * x); sq.reduce((a, b) => a + b, 0)", "14");
    expect(ctx, "(() => { let n = 0; const inc = () => ++n; inc(); inc(); return inc(); })()", "3");
    expect(ctx, "JSON.stringify({ a: [1, { b: null }], c: 'x' })", "{\"a\":[1,{\"b\":null}],\"c\":\"x\"}");
    expect(ctx, "throw new TypeError('boom')", "exception TypeError: boom");

    // dtoa.c
    expect(ctx, "String(0.1 + 0.2)", "0.30000000000000004");
    expect(ctx, "String(5e-324)", "5e-324");
    expect(ctx, "String(1e21)", "1e+21");
    expect(ctx, "(1.005).toFixed(2)", "1.00");
    expect(ctx, "(255).toString(16) + ' ' + parseFloat('2.5e-3') * 4", "ff 0.01");

    // libregexp.c
    expect(ctx, "const m = /(?<y>\\d{4})-(?<m>\\d{2})/.exec('on 2026-09'); m.groups.y + '/' + m.groups.m",
           "2026/09");
    expect(ctx, "'aXbxc'.split(/x/i).join(',')", "a,b,c");
    expect(ctx, "const re = /o/y; re.lastIndex = 1; re.test('foo') + ' ' + re.lastIndex", "true 2");

    // libunicode.c
    expect(ctx, "'straße'.toUpperCase()", "STRASSE");
    expect(ctx, "'\\u0041\\u030A'.normalize('NFC') === '\\u00C5'", "true");
    expect(ctx, "/^\\p{Script=Greek}+$/u.test('αβγ') + ' ' + /\\p{Script=Greek}/u.test('abc')", "true false");

    // quickjs.c, the job queue: a reaction runs only when the host drains it.
    expect(ctx, "var out = 'pending'; Promise.resolve(20).then(v => { out = 'resolved ' + (v + 1); }); out",
           "pending");
    JSContext* job_ctx = nullptr;
    int r;
    while ((r = JS_ExecutePendingJob(rt, &job_ctx)) > 0) {
    }
    if (r != 0) {
        std::fprintf(stderr, "FAIL a pending job threw\n");
        ++failures;
    }
    expect(ctx, "out", "resolved 21");

    JS_FreeContext(ctx);
    JS_FreeRuntime(rt);

    if (failures != 0) {
        std::fprintf(stderr, "%d check(s) failed\n", failures);
        return 1;
    }
    return 0;
}

