// Behavioral test for compat.re2.
//
// Exercises the parts of RE2 that gRPC's xds matchers actually use — full and
// partial match with captures, a pre-compiled RE2 object, replacement, and the
// RE2::Set multi-pattern API — so a package that compiled but linked nothing
// useful cannot pass:
//
//   RE2 ctor / FullMatch / PartialMatch  -> re2/re2.cc, parse.cc, compile.cc, prog.cc
//   captures + rewriting                 -> re2/re2.cc, regexp.cc, simplify.cc
//   RE2::Set                             -> re2/set.cc, dfa.cc, nfa.cc
//   invalid pattern reporting            -> re2/parse.cc, tostring.cc
//   UTF-8 handling                       -> util/rune.cc, unicode_groups.cc
//
// Returns non-zero on any mismatch.
#include <string>
#include <vector>

#include "re2/re2.h"
#include "re2/set.h"

namespace {

bool matching_ok() {
    if (!RE2::FullMatch("grpc-1.83.0", R"(grpc-\d+\.\d+\.\d+)")) return false;
    // A full match must NOT accept trailing junk — proves this is FullMatch
    // semantics and not an accidental substring search.
    if (RE2::FullMatch("grpc-1.83.0-rc1", R"(grpc-\d+\.\d+\.\d+)")) return false;
    return RE2::PartialMatch("grpc-1.83.0-rc1", R"(grpc-\d+\.\d+\.\d+)");
}

bool captures_ok() {
    const RE2 re(R"((\w+)://([^/:]+):(\d+))");   // pre-compiled, the way a matcher holds it
    if (!re.ok()) return false;

    std::string scheme, host;
    int port = 0;
    if (!RE2::FullMatch("dns://localhost:50051", re, &scheme, &host, &port)) return false;
    return scheme == "dns" && host == "localhost" && port == 50051;
}

bool rewrite_ok() {
    std::string s = "service/Echo, service/Ping";
    const int n = RE2::GlobalReplace(&s, R"(service/(\w+))", R"(grpc.\1)");
    return n == 2 && s == "grpc.Echo, grpc.Ping";
}

bool set_ok() {
    RE2::Set set(RE2::DefaultOptions, RE2::UNANCHORED);
    const int a = set.Add(R"(^/helloworld\.Greeter/)", nullptr);
    const int b = set.Add(R"(SayHello$)", nullptr);
    if (a < 0 || b < 0 || !set.Compile()) return false;

    std::vector<int> hits;
    if (!set.Match("/helloworld.Greeter/SayHello", &hits)) return false;
    if (hits.size() != 2) return false;

    std::vector<int> none;
    return !set.Match("/other.Service/Method", &none);
}

bool invalid_pattern_reported() {
    // An unbalanced group must be REJECTED with an error string, not silently
    // accepted — otherwise a broken matcher config would look valid.
    // log_errors(false) keeps RE2 from also printing the (expected) parse
    // failure to stderr, so real problems stay the only noise in the log.
    RE2::Options quiet;
    quiet.set_log_errors(false);
    const RE2 bad("(unclosed", quiet);
    return !bad.ok() && !bad.error().empty();
}

bool utf8_ok() {
    // '.' counts runes, not bytes, in UTF-8 mode (the default).
    return RE2::FullMatch("héllo", "h.llo") && RE2::PartialMatch("世界", "界");
}

}  // namespace

int main() {
    const bool ok = matching_ok() && captures_ok() && rewrite_ok() && set_ok()
                    && invalid_pattern_reported() && utf8_ok();
    return ok ? 0 : 1;
}

// compat.recastnavigation——三个按 feature 门控的组件，逐个让它做出
// 可观察的工作。
//
// `recastnavigation-features` 只点名 `crowd` 和 `debug-utils`。
// `tilecache` 没被点名，这是刻意的：上游的 DebugUtils 无条件链接
// DetourTileCache，所以描述符让 `debug-utils` imply `tilecache`。这条
// implication 哪天失效，本成员会在链接期失败，而不是悄悄发出一个没法
// 画调试图的包。
//
// 一切都通过生成的 `recastnavigation/` include 前缀行使——与上游自己的
// CMake 安装产出一致——所以 shim 层对 feature 头也有覆盖，不只是核心头。
#include <recastnavigation/Recast.h>
#include <recastnavigation/RecastAlloc.h>
#include <recastnavigation/DetourAlloc.h>
#include <recastnavigation/DetourCommon.h>
#include <recastnavigation/DetourNavMesh.h>
#include <recastnavigation/DetourNavMeshBuilder.h>
#include <recastnavigation/DetourNavMeshQuery.h>
#include <recastnavigation/DetourStatus.h>
#include <recastnavigation/DetourCrowd.h>
#include <recastnavigation/DetourTileCache.h>
#include <recastnavigation/DetourTileCacheBuilder.h>
#include <recastnavigation/DebugDraw.h>
#include <recastnavigation/DetourDebugDraw.h>
import std;

namespace {

constexpr float kSize = 20.0f;

constexpr float kAgentHeight = 2.0f;
constexpr float kAgentRadius = 0.6f;
constexpr float kAgentClimb = 0.9f;

// y=0 处一块 20x20 的平面四边形，俯视为顺时针绕序，使 rcCalcTriNormal
// 产出朝上的法线——rcMarkWalkableTriangles 测试 `norm[1] > threshold`，
// 绕序反了不会报错，只会得到空网格。
constexpr float kFloorVerts[] = { 0, 0, 0,  0, 0, kSize,  kSize, 0, kSize,  kSize, 0, 0 };
constexpr int   kFloorTris[]  = { 0, 1, 2,  0, 2, 3 };

void fillConfig(rcConfig& cfg, float cs) {
    cfg = rcConfig{};
    cfg.cs = cs;
    cfg.ch = 0.2f;
    cfg.walkableSlopeAngle = 45.0f;
    cfg.walkableHeight = static_cast<int>(std::ceil(kAgentHeight / cfg.ch));
    cfg.walkableClimb  = static_cast<int>(std::floor(kAgentClimb / cfg.ch));
    cfg.walkableRadius = static_cast<int>(std::ceil(kAgentRadius / cfg.cs));
    cfg.maxEdgeLen = static_cast<int>(12.0f / cfg.cs);
    cfg.maxSimplificationError = 1.3f;
    cfg.minRegionArea = static_cast<int>(rcSqr(8.0f));
    cfg.mergeRegionArea = static_cast<int>(rcSqr(20.0f));
    cfg.maxVertsPerPoly = 6;
    cfg.detailSampleDist = cfg.cs * 6.0f;
    cfg.detailSampleMaxError = cfg.ch * 1.0f;
    cfg.bmin[0] = 0.0f; cfg.bmin[1] = 0.0f; cfg.bmin[2] = 0.0f;
    cfg.bmax[0] = kSize; cfg.bmax[1] = 0.0f; cfg.bmax[2] = kSize;
}

// 两条流水线共用的前半段：栅格化、过滤、压缩。
rcCompactHeightfield* buildCompact(rcContext& ctx, const rcConfig& cfg) {
    rcHeightfield* solid = rcAllocHeightfield();
    if (!solid) return nullptr;
    if (!rcCreateHeightfield(&ctx, *solid, cfg.width, cfg.height, cfg.bmin, cfg.bmax, cfg.cs, cfg.ch)) {
        rcFreeHeightField(solid);
        return nullptr;
    }
    unsigned char triareas[2] = { 0, 0 };
    rcMarkWalkableTriangles(&ctx, cfg.walkableSlopeAngle, kFloorVerts, 4, kFloorTris, 2, triareas);
    rcRasterizeTriangles(&ctx, kFloorVerts, 4, kFloorTris, triareas, 2, *solid, cfg.walkableClimb);
    rcFilterLowHangingWalkableObstacles(&ctx, cfg.walkableClimb, *solid);
    rcFilterLedgeSpans(&ctx, cfg.walkableHeight, cfg.walkableClimb, *solid);
    rcFilterWalkableLowHeightSpans(&ctx, cfg.walkableHeight, *solid);

    rcCompactHeightfield* chf = rcAllocCompactHeightfield();
    if (!chf || !rcBuildCompactHeightfield(&ctx, cfg.walkableHeight, cfg.walkableClimb, *solid, *chf)) {
        rcFreeCompactHeightfield(chf);
        rcFreeHeightField(solid);
        return nullptr;
    }
    rcFreeHeightField(solid);
    return chf;
}

// dtTileCacheCompressor 是用户提供的接口——RecastDemo 往里接的是 fastlz。
// 对一个只关心 tile 能完整往返的测试来说，memcpy 就是很好的压缩方案，
// 还顺带把 fastlz 依赖挡在外面。
struct PassthroughCompressor final : dtTileCacheCompressor {
    int maxCompressedSize(const int bufferSize) override { return bufferSize; }
    dtStatus compress(const unsigned char* buffer, const int bufferSize,
                      unsigned char* compressed, const int maxCompressedSize, int* compressedSize) override {
        if (bufferSize > maxCompressedSize) return DT_FAILURE;
        std::memcpy(compressed, buffer, static_cast<std::size_t>(bufferSize));
        *compressedSize = bufferSize;
        return DT_SUCCESS;
    }
    dtStatus decompress(const unsigned char* compressed, const int compressedSize,
                        unsigned char* buffer, const int maxBufferSize, int* bufferSize) override {
        if (compressedSize > maxBufferSize) return DT_FAILURE;
        std::memcpy(buffer, compressed, static_cast<std::size_t>(compressedSize));
        *bufferSize = compressedSize;
        return DT_SUCCESS;
    }
};

// dtTileCache 把每块刚建好的 tile 交给 mesh process 打 flag。没有这一步，
// 多边形的 flags 会是 0，什么都查不了——这正是「tile 存在」这条断言
// 抓不住的失败模式。
struct FlagWalkable final : dtTileCacheMeshProcess {
    void process(dtNavMeshCreateParams* params, unsigned char* polyAreas, unsigned short* polyFlags) override {
        for (int i = 0; i < params->polyCount; ++i)
            polyFlags[i] = (polyAreas[i] == DT_TILECACHE_WALKABLE_AREA) ? 1 : 0;
    }
};

// 给 DebugUtils 向渲染器要的东西计数。duDebugDraw 是抽象接口，实现一个
// 是证明 DebugUtils 既编译过又链接得上的唯一办法——只做头的 DebugUtils
// 撑不过 begin()。
struct RecordingDraw final : duDebugDraw {
    int vertices = 0;
    int begins = 0;
    int triBatches = 0;

    void depthMask(bool) override {}
    void texture(bool) override {}
    void begin(duDebugDrawPrimitives prim, float) override {
        ++begins;
        if (prim == DU_DRAW_TRIS) ++triBatches;
    }
    void vertex(const float*, unsigned int) override { ++vertices; }
    void vertex(const float, const float, const float, unsigned int) override { ++vertices; }
    void vertex(const float*, unsigned int, const float*) override { ++vertices; }
    void vertex(const float, const float, const float, unsigned int, const float, const float) override { ++vertices; }
    void end() override {}
};

}  // namespace

int main() {
    bool ok = true;
    const auto check = [&](bool cond, std::string_view what) {
        if (!cond) {
            std::println("FAIL: {}", what);
            ok = false;
        }
    };

    rcContext ctx;

    // ══ Recast：一张独立网格，crowd 和 DebugUtils 都要用它 ═════════════════
    rcConfig cfg;
    fillConfig(cfg, 0.5f);
    rcCalcGridSize(cfg.bmin, cfg.bmax, cfg.cs, &cfg.width, &cfg.height);

    rcCompactHeightfield* chf = buildCompact(ctx, cfg);
    check(chf != nullptr, "compact heightfield");

    rcErodeWalkableArea(&ctx, cfg.walkableRadius, *chf);
    rcBuildDistanceField(&ctx, *chf);
    rcBuildRegions(&ctx, *chf, 0, cfg.minRegionArea, cfg.mergeRegionArea);

    rcContourSet* cset = rcAllocContourSet();
    rcBuildContours(&ctx, *chf, cfg.maxSimplificationError, cfg.maxEdgeLen, *cset);
    rcPolyMesh* pmesh = rcAllocPolyMesh();
    rcBuildPolyMesh(&ctx, *cset, cfg.maxVertsPerPoly, *pmesh);
    rcPolyMeshDetail* dmesh = rcAllocPolyMeshDetail();
    rcBuildPolyMeshDetail(&ctx, *pmesh, *chf, cfg.detailSampleDist, cfg.detailSampleMaxError, *dmesh);
    std::println("solo poly mesh: {} verts, {} polys", pmesh->nverts, pmesh->npolys);
    check(pmesh->npolys > 0, "core Recast build produced polygons");
    rcFreeCompactHeightfield(chf);
    rcFreeContourSet(cset);

    for (int i = 0; i < pmesh->npolys; ++i)
        pmesh->flags[i] = (pmesh->areas[i] == RC_WALKABLE_AREA) ? 1 : 0;

    dtNavMeshCreateParams params{};
    params.verts = pmesh->verts;
    params.vertCount = pmesh->nverts;
    params.polys = pmesh->polys;
    params.polyFlags = pmesh->flags;
    params.polyAreas = pmesh->areas;
    params.polyCount = pmesh->npolys;
    params.nvp = pmesh->nvp;
    params.detailMeshes = dmesh->meshes;
    params.detailVerts = dmesh->verts;
    params.detailVertsCount = dmesh->nverts;
    params.detailTris = dmesh->tris;
    params.detailTriCount = dmesh->ntris;
    params.walkableHeight = kAgentHeight;
    params.walkableRadius = kAgentRadius;
    params.walkableClimb = kAgentClimb;
    rcVcopy(params.bmin, pmesh->bmin);
    rcVcopy(params.bmax, pmesh->bmax);
    params.cs = cfg.cs;
    params.ch = cfg.ch;
    params.buildBvTree = true;

    unsigned char* navData = nullptr;
    int navDataSize = 0;
    check(dtCreateNavMeshData(&params, &navData, &navDataSize), "dtCreateNavMeshData");

    dtNavMesh* nav = dtAllocNavMesh();
    check(nav != nullptr, "dtAllocNavMesh");
    check(dtStatusSucceed(nav->init(navData, navDataSize, DT_TILE_FREE_DATA)), "dtNavMesh::init");
    dtNavMeshQuery* query = dtAllocNavMeshQuery();
    check(dtStatusSucceed(query->init(nav, 2048)), "dtNavMeshQuery::init");

    const float ext[3] = { 2.0f, 4.0f, 2.0f };
    dtQueryFilter filter;
    filter.setIncludeFlags(1);
    filter.setExcludeFlags(0);

    // ══ crowd ══════════════════════════════════════════════════════════════
    dtCrowd crowd;
    check(crowd.init(4, kAgentRadius, nav), "dtCrowd::init");

    dtCrowdAgentParams agentParams{};
    agentParams.radius = kAgentRadius;
    agentParams.height = kAgentHeight;
    agentParams.maxAcceleration = 8.0f;
    agentParams.maxSpeed = 3.5f;
    agentParams.collisionQueryRange = kAgentRadius * 12.0f;
    agentParams.pathOptimizationRange = kAgentRadius * 30.0f;
    agentParams.updateFlags = DT_CROWD_ANTICIPATE_TURNS | DT_CROWD_OBSTACLE_AVOIDANCE | DT_CROWD_OPTIMIZE_VIS;
    agentParams.obstacleAvoidanceType = 3;
    agentParams.separationWeight = 2.0f;

    const float start[3] = { 2.0f, 0.2f, 2.0f };
    const float goal[3] = { 18.0f, 0.2f, 18.0f };
    const int agent = crowd.addAgent(start, &agentParams);
    check(agent >= 0, "crowd.addAgent");

    dtPolyRef goalRef = 0;
    float goalNear[3] = { 0, 0, 0 };
    check(dtStatusSucceed(query->findNearestPoly(goal, ext, &filter, &goalRef, goalNear)), "findNearestPoly(goal)");
    check(crowd.requestMoveTarget(agent, goalRef, goalNear), "crowd.requestMoveTarget");

    const float distanceBefore = dtVdist(start, goal);
    for (int i = 0; i < 400; ++i) crowd.update(1.0f / 60.0f, nullptr);
    const dtCrowdAgent* moved = crowd.getAgent(agent);
    check(moved != nullptr, "crowd agent survives 400 updates");
    if (moved) {
        const float distanceAfter = dtVdist(moved->npos, goal);
        std::println("crowd: {} -> {} from goal (state {})", distanceBefore, distanceAfter, moved->state);
        // dtCrowd 在这里约 6.7 秒的模拟时间内完成引导；一步都没有积分过的
        // agent 会仍然待在起点。
        check(distanceAfter < distanceBefore - 5.0f, "crowd agent actually walked toward the goal");
    }

    // ══ tilecache ══════════════════════════════════════════════════════════
    // rcBuildHeightfieldLayers 需要可走区域外有一圈不可通行的边界，这就是
    // 为什么这里是第二次、单独配置的栅格化，而不是复用上面的 compact
    // heightfield。
    rcConfig tcfg;
    fillConfig(tcfg, 0.5f);
    const int tileSizeVoxels = 40;                    // 一块 tile 盖住整个地面
    tcfg.walkableRadius = static_cast<int>(std::ceil(kAgentRadius / tcfg.cs));
    tcfg.tileSize = tileSizeVoxels;
    tcfg.borderSize = tcfg.walkableRadius + 3;
    const float tileWorldSize = static_cast<float>(tileSizeVoxels) * tcfg.cs;
    tcfg.bmin[0] -= tcfg.borderSize * tcfg.cs;
    tcfg.bmin[2] -= tcfg.borderSize * tcfg.cs;
    tcfg.bmax[0] += tcfg.borderSize * tcfg.cs;
    tcfg.bmax[2] += tcfg.borderSize * tcfg.cs;
    rcCalcGridSize(tcfg.bmin, tcfg.bmax, tcfg.cs, &tcfg.width, &tcfg.height);

    rcCompactHeightfield* tchf = buildCompact(ctx, tcfg);
    check(tchf != nullptr, "tiled compact heightfield");
    rcErodeWalkableArea(&ctx, tcfg.walkableRadius, *tchf);

    rcHeightfieldLayerSet* lset = rcAllocHeightfieldLayerSet();
    check(rcBuildHeightfieldLayers(&ctx, *tchf, tcfg.borderSize, tcfg.walkableHeight, *lset),
          "rcBuildHeightfieldLayers");
    std::println("heightfield layers: {}", lset->nlayers);
    check(lset->nlayers > 0, "heightfield layers were built");
    rcFreeCompactHeightfield(tchf);

    dtNavMesh* tiledNav = dtAllocNavMesh();
    dtNavMeshParams navParams{};
    rcVcopy(navParams.orig, cfg.bmin);
    navParams.tileWidth = tileWorldSize;
    navParams.tileHeight = tileWorldSize;
    navParams.maxTiles = 8;
    navParams.maxPolys = 128;
    check(dtStatusSucceed(tiledNav->init(&navParams)), "tiled navmesh init");

    PassthroughCompressor compressor;
    FlagWalkable meshProcess;
    dtTileCacheAlloc tileAlloc;
    dtTileCache tileCache;

    dtTileCacheParams tcParams{};
    rcVcopy(tcParams.orig, cfg.bmin);
    tcParams.cs = tcfg.cs;
    tcParams.ch = tcfg.ch;
    tcParams.width = tileSizeVoxels;
    tcParams.height = tileSizeVoxels;
    tcParams.walkableHeight = kAgentHeight;
    tcParams.walkableRadius = kAgentRadius;
    tcParams.walkableClimb = kAgentClimb;
    tcParams.maxSimplificationError = tcfg.maxSimplificationError;
    tcParams.maxTiles = 8;
    tcParams.maxObstacles = 32;
    check(dtStatusSucceed(tileCache.init(&tcParams, &tileAlloc, &compressor, &meshProcess)), "dtTileCache::init");

    const rcHeightfieldLayer* rlayer = &lset->layers[0];
    dtTileCacheLayerHeader header{};
    header.magic = DT_TILECACHE_MAGIC;
    header.version = DT_TILECACHE_VERSION;
    header.tx = 0;
    header.ty = 0;
    header.tlayer = 0;
    rcVcopy(header.bmin, rlayer->bmin);
    rcVcopy(header.bmax, rlayer->bmax);
    header.width = static_cast<unsigned char>(rlayer->width);
    header.height = static_cast<unsigned char>(rlayer->height);
    header.minx = static_cast<unsigned char>(rlayer->minx);
    header.maxx = static_cast<unsigned char>(rlayer->maxx);
    header.miny = static_cast<unsigned char>(rlayer->miny);
    header.maxy = static_cast<unsigned char>(rlayer->maxy);
    header.hmin = static_cast<unsigned short>(rlayer->hmin);
    header.hmax = static_cast<unsigned short>(rlayer->hmax);

    // DetourTileCache 的 builder 半边，在同一层上端到端驱动一遍。
    dtTileCacheLayer layer{};
    layer.header = &header;
    layer.heights = rlayer->heights;
    layer.areas = rlayer->areas;
    layer.cons = rlayer->cons;
    layer.regs = static_cast<unsigned char*>(dtAlloc(rlayer->width * rlayer->height, DT_ALLOC_TEMP));
    std::memset(layer.regs, 0xff, static_cast<std::size_t>(rlayer->width) * rlayer->height);

    check(dtStatusSucceed(dtBuildTileCacheRegions(&tileAlloc, layer, tcfg.walkableClimb)),
          "dtBuildTileCacheRegions");
    // dtFreeTileCacheContourSet / dtFreeTileCachePolyMesh 连容器本身带载荷
    // 一起释放，所以两者都必须用配套的 dtAlloc* 辅助函数从堆上取——
    // 释放栈上对象会直接崩。
    dtTileCacheContourSet* contours = dtAllocTileCacheContourSet(&tileAlloc);
    check(contours != nullptr, "dtAllocTileCacheContourSet");
    check(dtStatusSucceed(dtBuildTileCacheContours(&tileAlloc, layer, tcfg.walkableClimb,
                                                   tcfg.maxSimplificationError, *contours)),
          "dtBuildTileCacheContours");
    dtTileCachePolyMesh* layerMesh = dtAllocTileCachePolyMesh(&tileAlloc);
    check(layerMesh != nullptr, "dtAllocTileCachePolyMesh");
    check(dtStatusSucceed(dtBuildTileCachePolyMesh(&tileAlloc, *contours, *layerMesh)), "dtBuildTileCachePolyMesh");
    std::println("tile cache poly mesh: {} polys", layerMesh->npolys);
    check(layerMesh->npolys > 0, "tile cache builder produced polygons");
    dtFreeTileCacheContourSet(&tileAlloc, contours);
    dtFreeTileCachePolyMesh(&tileAlloc, layerMesh);
    dtFree(layer.regs);

    // 缓存半边：压缩这一层，交给 dtTileCache，再让它从中物化出一块
    // 导航网格 tile。
    unsigned char* tileData = nullptr;
    int tileDataSize = 0;
    check(dtStatusSucceed(dtBuildTileCacheLayer(&compressor, &header, rlayer->heights, rlayer->areas,
                                                rlayer->cons, &tileData, &tileDataSize)),
          "dtBuildTileCacheLayer");
    dtCompressedTileRef tileRef = 0;
    check(dtStatusSucceed(tileCache.addTile(tileData, tileDataSize, DT_COMPRESSEDTILE_FREE_DATA, &tileRef)),
          "dtTileCache::addTile");
    check(tileRef != 0, "addTile returned a reference");
    check(dtStatusSucceed(tileCache.buildNavMeshTile(tileRef, tiledNav)), "dtTileCache::buildNavMeshTile");

    const dtMeshTile* built = tiledNav->getTileAt(0, 0, 0);
    check(built != nullptr, "the tile cache materialized a navmesh tile");
    if (built && built->header) std::println("cached tile polys: {}", built->header->polyCount);
    check(built != nullptr && built->header != nullptr && built->header->polyCount > 0,
          "that tile holds polygons");

    // ……以及它是可用的，而不只是存在：多边形 flags 为 0 的网格照样有
    // 几何，却什么查询都答不了。
    dtNavMeshQuery* tiledQuery = dtAllocNavMeshQuery();
    check(dtStatusSucceed(tiledQuery->init(tiledNav, 128)), "tiled query init");
    dtPolyRef tiledRef = 0;
    float tiledNear[3] = { 0, 0, 0 };
    const float middle[3] = { 10.0f, 0.2f, 10.0f };
    check(dtStatusSucceed(tiledQuery->findNearestPoly(middle, ext, &filter, &tiledRef, tiledNear)),
          "findNearestPoly on the cached tile");
    check(tiledRef != 0, "the cached tile answers queries");
    dtFreeNavMeshQuery(tiledQuery);

    // ══ debug-utils ════════════════════════════════════════════════════════
    RecordingDraw draw;
    duDebugDrawNavMesh(&draw, *nav, 0);
    std::println("debug draw: {} begins ({} triangle batches), {} vertices",
                 draw.begins, draw.triBatches, draw.vertices);
    check(draw.vertices > 0, "DebugUtils emitted vertices for the navmesh");
    check(draw.triBatches > 0, "DebugUtils emitted triangle batches");

    dtFreeNavMesh(tiledNav);
    dtFreeNavMeshQuery(query);
    dtFreeNavMesh(nav);
    rcFreeHeightfieldLayerSet(lset);
    rcFreePolyMesh(pmesh);
    rcFreePolyMeshDetail(dmesh);

    std::println("compat.recastnavigation feature test: {}", ok ? "ok" : "FAILED");
    return ok ? 0 : 1;
}

// compat.recastnavigation——烘一张导航网格，在上面走路，对路径做断言。
//
// 地面是 20x20、中间挖穿一个 4x4 洞的正方形，所以从 (2,2) 到 (18,18) 的
// 路线不可能是一条直线段。「包坏了但测试依然绿」的情况有三种，每一种
// 都被单独防住：
//
//   * 网格栅格化成了空集   -> 对 nverts/npolys 做断言
//   * 网格是一整块大四方形 -> 直线路径必须拐弯，洞若被构建器悄悄填平，
//     就在这里失败
//   * Detour 没被真正链接  -> findPath / findStraightPath 都被调用，
//     缺库在链接期就失败，根本到不了这里
//
// 两种 include 拼写是有意混用的：Recast 走生成的 `recastnavigation/`
// 前缀，Detour 走裸的 `<DetourNavMesh.h>`。上游的 CMake 安装把两条路径
// 都放到接口 include path 上；若只有一种能用，shim 层就是没被测到的。
#include <recastnavigation/Recast.h>
#include <recastnavigation/RecastAlloc.h>
#include <DetourAlloc.h>
#include <DetourCommon.h>
#include <DetourNavMesh.h>
#include <DetourNavMeshBuilder.h>
#include <DetourNavMeshQuery.h>
#include <DetourStatus.h>
import std;

namespace {

constexpr float kSize = 20.0f;    // 地面边长（x 与 z）
constexpr float kHoleLo = 8.0f;   // 洞在两根轴上都横跨 [8,12]
constexpr float kHoleHi = 12.0f;

constexpr float kAgentHeight = 2.0f;
constexpr float kAgentRadius = 0.6f;
constexpr float kAgentClimb = 0.9f;

struct Quad { float ax, az, bx, bz, cx, cz, dx, dz; };

// 四个四边形拼成环形。俯视（沿 -y 轴往下看）时角点顺序为顺时针——这正是
// rcCalcTriNormal 产出朝上法线的原因；rcMarkWalkableTriangles 测试的是
// `norm[1] > threshold`，绕序反了不会报错，只会静默得到一张空网格。
constexpr Quad kQuads[] = {
    { 0, 0,        0, kHoleLo,  kSize, kHoleLo, kSize, 0        },  // 南侧条带
    { 0, kHoleHi,  0, kSize,    kSize, kSize,   kSize, kHoleHi  },  // 北侧条带
    { 0, kHoleLo,  0, kHoleHi,  kHoleLo, kHoleHi, kHoleLo, kHoleLo },  // 西侧条带
    { kHoleHi, kHoleLo, kHoleHi, kHoleHi, kSize, kHoleHi, kSize, kHoleLo },  // 东侧条带
};

struct FloorMesh {
    std::vector<float> verts;
    std::vector<int>   tris;

    FloorMesh() {
        for (const Quad& q : kQuads) {
            const int base = static_cast<int>(verts.size()) / 3;
            const float corners[4][2] = {
                { q.ax, q.az }, { q.bx, q.bz }, { q.cx, q.cz }, { q.dx, q.dz }
            };
            for (const auto& c : corners) {
                verts.push_back(c[0]);
                verts.push_back(0.0f);
                verts.push_back(c[1]);
            }
            tris.insert(tris.end(), { base + 0, base + 1, base + 2 });
            tris.insert(tris.end(), { base + 0, base + 2, base + 3 });
        }
    }

    int vertCount() const { return static_cast<int>(verts.size()) / 3; }
    int triCount() const { return static_cast<int>(tris.size()) / 3; }
};

}  // namespace

int main() {
    bool ok = true;
    const auto check = [&](bool cond, std::string_view what) {
        if (!cond) {
            std::println("FAIL: {}", what);
            ok = false;
        }
    };

    const FloorMesh floor;
    std::println("geometry: {} verts, {} tris", floor.vertCount(), floor.triCount());

    rcContext ctx;

    rcConfig cfg{};
    cfg.cs = 0.3f;
    cfg.ch = 0.2f;
    cfg.walkableSlopeAngle = 45.0f;
    cfg.walkableHeight = static_cast<int>(std::ceil(kAgentHeight / cfg.ch));
    cfg.walkableClimb  = static_cast<int>(std::floor(kAgentClimb / cfg.ch));
    cfg.walkableRadius = static_cast<int>(std::ceil(kAgentRadius / cfg.cs));
    cfg.maxEdgeLen = static_cast<int>(12.0f / cfg.cs);
    cfg.maxSimplificationError = 1.3f;
    cfg.minRegionArea = static_cast<int>(rcSqr(8.0f));
    cfg.mergeRegionArea = static_cast<int>(rcSqr(20.0f));
    cfg.maxVertsPerPoly = 6;
    cfg.detailSampleDist = cfg.cs * 6.0f;
    cfg.detailSampleMaxError = cfg.ch * 1.0f;
    cfg.bmin[0] = 0.0f; cfg.bmin[1] = 0.0f; cfg.bmin[2] = 0.0f;
    cfg.bmax[0] = kSize; cfg.bmax[1] = 0.0f; cfg.bmax[2] = kSize;
    rcCalcGridSize(cfg.bmin, cfg.bmax, cfg.cs, &cfg.width, &cfg.height);
    std::println("grid: {}x{}", cfg.width, cfg.height);

    // ── Recast：原始三角形 -> 多边形网格 ──────────────────────────────────
    rcHeightfield* solid = rcAllocHeightfield();
    check(solid != nullptr, "rcAllocHeightfield");
    check(rcCreateHeightfield(&ctx, *solid, cfg.width, cfg.height, cfg.bmin, cfg.bmax, cfg.cs, cfg.ch),
          "rcCreateHeightfield");

    std::vector<unsigned char> triareas(static_cast<std::size_t>(floor.triCount()), 0);
    rcMarkWalkableTriangles(&ctx, cfg.walkableSlopeAngle, floor.verts.data(), floor.vertCount(),
                            floor.tris.data(), floor.triCount(), triareas.data());
    const int walkableTris = static_cast<int>(std::ranges::count(triareas, RC_WALKABLE_AREA));
    std::println("walkable triangles: {} / {}", walkableTris, floor.triCount());
    check(walkableTris == floor.triCount(), "every floor triangle is walkable (winding gives +y normals)");

    check(rcRasterizeTriangles(&ctx, floor.verts.data(), floor.vertCount(), floor.tris.data(),
                               triareas.data(), floor.triCount(), *solid, cfg.walkableClimb),
          "rcRasterizeTriangles");
    rcFilterLowHangingWalkableObstacles(&ctx, cfg.walkableClimb, *solid);
    rcFilterLedgeSpans(&ctx, cfg.walkableHeight, cfg.walkableClimb, *solid);
    rcFilterWalkableLowHeightSpans(&ctx, cfg.walkableHeight, *solid);

    rcCompactHeightfield* chf = rcAllocCompactHeightfield();
    check(rcBuildCompactHeightfield(&ctx, cfg.walkableHeight, cfg.walkableClimb, *solid, *chf),
          "rcBuildCompactHeightfield");
    rcFreeHeightField(solid);

    check(rcErodeWalkableArea(&ctx, cfg.walkableRadius, *chf), "rcErodeWalkableArea");
    check(rcBuildDistanceField(&ctx, *chf), "rcBuildDistanceField");
    check(rcBuildRegions(&ctx, *chf, 0, cfg.minRegionArea, cfg.mergeRegionArea), "rcBuildRegions");

    rcContourSet* cset = rcAllocContourSet();
    check(rcBuildContours(&ctx, *chf, cfg.maxSimplificationError, cfg.maxEdgeLen, *cset), "rcBuildContours");

    rcPolyMesh* pmesh = rcAllocPolyMesh();
    check(rcBuildPolyMesh(&ctx, *cset, cfg.maxVertsPerPoly, *pmesh), "rcBuildPolyMesh");
    std::println("poly mesh: {} verts, {} polys", pmesh->nverts, pmesh->npolys);
    check(pmesh->nverts > 0, "Recast produced vertices");
    check(pmesh->npolys > 0, "Recast produced polygons");

    rcPolyMeshDetail* dmesh = rcAllocPolyMeshDetail();
    check(rcBuildPolyMeshDetail(&ctx, *pmesh, *chf, cfg.detailSampleDist, cfg.detailSampleMaxError, *dmesh),
          "rcBuildPolyMeshDetail");
    rcFreeCompactHeightfield(chf);
    rcFreeContourSet(cset);

    // ── Detour：多边形网格 -> 可查询的导航网格 ────────────────────────────
    // Detour 只会走带查询过滤器所含 flag 的多边形。
    for (int i = 0; i < pmesh->npolys; ++i)
        pmesh->flags[i] = (pmesh->areas[i] == RC_WALKABLE_AREA) ? 1 : 0;

    dtNavMeshCreateParams params{};
    params.verts = pmesh->verts;
    params.vertCount = pmesh->nverts;
    params.polys = pmesh->polys;
    params.polyFlags = pmesh->flags;
    params.polyAreas = pmesh->areas;
    params.polyCount = pmesh->npolys;
    params.nvp = pmesh->nvp;
    params.detailMeshes = dmesh->meshes;
    params.detailVerts = dmesh->verts;
    params.detailVertsCount = dmesh->nverts;
    params.detailTris = dmesh->tris;
    params.detailTriCount = dmesh->ntris;
    params.walkableHeight = kAgentHeight;
    params.walkableRadius = kAgentRadius;
    params.walkableClimb = kAgentClimb;
    rcVcopy(params.bmin, pmesh->bmin);
    rcVcopy(params.bmax, pmesh->bmax);
    params.cs = cfg.cs;
    params.ch = cfg.ch;
    params.buildBvTree = true;

    unsigned char* navData = nullptr;
    int navDataSize = 0;
    check(dtCreateNavMeshData(&params, &navData, &navDataSize), "dtCreateNavMeshData");

    dtNavMesh* nav = dtAllocNavMesh();
    check(nav != nullptr, "dtAllocNavMesh");
    check(dtStatusSucceed(nav->init(navData, navDataSize, DT_TILE_FREE_DATA)), "dtNavMesh::init");

    dtNavMeshQuery* query = dtAllocNavMeshQuery();
    check(query != nullptr, "dtAllocNavMeshQuery");
    check(dtStatusSucceed(query->init(nav, 2048)), "dtNavMeshQuery::init");

    dtQueryFilter filter;
    filter.setIncludeFlags(1);
    filter.setExcludeFlags(0);

    const float ext[3] = { 2.0f, 4.0f, 2.0f };
    const float start[3] = { 2.0f, 0.0f, 2.0f };
    const float goal[3] = { 18.0f, 0.0f, 18.0f };

    dtPolyRef startRef = 0, endRef = 0;
    float startNear[3] = { 0, 0, 0 }, endNear[3] = { 0, 0, 0 };
    check(dtStatusSucceed(query->findNearestPoly(start, ext, &filter, &startRef, startNear)), "findNearestPoly(start)");
    check(dtStatusSucceed(query->findNearestPoly(goal, ext, &filter, &endRef, endNear)), "findNearestPoly(goal)");
    check(startRef != 0, "start polygon found");
    check(endRef != 0, "goal polygon found");

    std::vector<dtPolyRef> corridor(256);
    int corridorLen = 0;
    check(dtStatusSucceed(query->findPath(startRef, endRef, startNear, endNear, &filter,
                                          corridor.data(), &corridorLen, static_cast<int>(corridor.size()))),
          "findPath");
    std::println("path corridor: {} polys", corridorLen);
    check(corridorLen > 0, "findPath returned a corridor");

    std::vector<float> straight(256 * 3);
    std::vector<unsigned char> straightFlags(256);
    std::vector<dtPolyRef> straightRefs(256);
    int straightLen = 0;
    check(dtStatusSucceed(query->findStraightPath(startNear, endNear, corridor.data(), corridorLen,
                                                  straight.data(), straightFlags.data(), straightRefs.data(),
                                                  &straightLen, 256)),
          "findStraightPath");
    std::println("straight path: {} points", straightLen);

    check(straightLen >= 2, "straight path has a start and an end");
    // 洞挡住了直对角线，所以最短路径必须拐弯。只有两个点意味着查询笔直地
    // 穿过了洞——即洞没进网格，或者网格是一整块大四方形。
    check(straightLen >= 3, "path bends around the hole (>= 3 straight points)");

    if (straightLen >= 2) {
        const float* last = &straight[(straightLen - 1) * 3];
        const float gap = dtVdist(last, goal);
        std::println("endpoint distance to goal: {:.3f}", gap);
        check(gap < 2.0f, "path ends at the goal");

        float walked = 0.0f;
        for (int i = 1; i < straightLen; ++i)
            walked += dtVdist(&straight[(i - 1) * 3], &straight[i * 3]);
        const float direct = dtVdist(start, goal);
        std::println("path length {:.3f} vs direct {:.3f}", walked, direct);
        check(walked > direct + 0.5f, "path is longer than the direct line (it went around)");
    }

    dtFreeNavMeshQuery(query);
    dtFreeNavMesh(nav);
    rcFreePolyMesh(pmesh);
    rcFreePolyMeshDetail(dmesh);

    std::println("compat.recastnavigation smoke test: {}", ok ? "ok" : "FAILED");
    return ok ? 0 : 1;
}

// redis_test.cpp — offline behavioral test for the `async` feature of
// compat.redis-plus-plus (libuv-backed AsyncRedis).
//
// No redis-server binary and no network access: a minimal RESP server runs
// inside the process (raw loopback sockets, same platform abstraction as the
// websocket member) and the sw::redis::AsyncRedis client is driven against it.
// The async client can pipeline PING + SET into a single TCP segment, so the
// server parses complete RESP arrays instead of scanning for keywords.
#include <sw/redis++/async_redis++.h>

#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <string>
#include <thread>

// ── Platform socket abstraction (same as tests/examples/websocket) ─────────

#ifdef _WIN32
#include <winsock2.h>
#include <ws2tcpip.h>
using SockType = SOCKET;
constexpr SockType kInvalidSocket = INVALID_SOCKET;
using AddrLenType = int;
#else
#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <unistd.h>
using SockType = int;
constexpr SockType kInvalidSocket = -1;
using AddrLenType = socklen_t;
#endif

void init_sockets()
{
#ifdef _WIN32
    WSADATA wsa;
    WSAStartup(MAKEWORD(2, 2), &wsa);
#endif
}

void close_socket(SockType s)
{
#ifdef _WIN32
    closesocket(s);
#else
    ::close(s);
#endif
}

void set_recv_timeout(SockType s, int ms)
{
#ifdef _WIN32
    DWORD t = static_cast<DWORD>(ms);
    setsockopt(s, SOL_SOCKET, SO_RCVTIMEO, reinterpret_cast<const char*>(&t), sizeof(t));
#else
    timeval tv{};
    tv.tv_sec = ms / 1000;
    tv.tv_usec = (ms % 1000) * 1000;
    setsockopt(s, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
#endif
}

// ── Minimal RESP server: PING -> +PONG, SET -> +OK ─────────────────────────
// Parses complete RESP arrays so pipelined commands (async client) are served
// one reply each instead of one reply per recv().
class RespServer
{
public:
    ~RespServer()
    {
        if (client != kInvalidSocket) close_socket(client);
        if (listener != kInvalidSocket) close_socket(listener);
        if (thread.joinable()) thread.join();
    }

    bool start()
    {
        init_sockets();
        listener = socket(AF_INET, SOCK_STREAM, 0);
        if (listener == kInvalidSocket) return false;
        int one = 1;
#ifdef _WIN32
        setsockopt(listener, SOL_SOCKET, SO_REUSEADDR,
                   reinterpret_cast<const char*>(&one), sizeof(one));
#else
        setsockopt(listener, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));
#endif
        sockaddr_in addr{};
        addr.sin_family = AF_INET;
        addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        addr.sin_port = 0; // ephemeral
        if (bind(listener, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) != 0) return false;
        AddrLenType alen = sizeof(addr);
        getsockname(listener, reinterpret_cast<sockaddr*>(&addr), &alen);
        port = ntohs(addr.sin_port);
        if (listen(listener, 1) != 0) return false;
        thread = std::thread([this] { run(); });
        return true;
    }

    int port = 0;

private:
    void run()
    {
        SockType s = accept(listener, nullptr, nullptr);
        if (s == kInvalidSocket) return;
        client = s;
        set_recv_timeout(client, 5000);

        std::string buf;
        int served = 0;
        while (served < 16) {
            char tmp[1024];
            const int n = static_cast<int>(recv(client, tmp, sizeof(tmp), 0));
            if (n <= 0) break;
            buf.append(tmp, static_cast<size_t>(n));

            size_t off = 0;
            while (served < 16) {
                // `*<count>\r\n` then `<count>` bulk strings `$<len>\r\n<data>\r\n`.
                if (buf.size() < off + 3 || buf[off] != '*') break;
                const size_t nl = buf.find("\r\n", off);
                if (nl == std::string::npos) break;
                const int count = std::atoi(buf.substr(off + 1, nl - off - 1).c_str());
                off = nl + 2;
                std::string cmd;
                bool complete = true;
                for (int i = 0; i < count; ++i) {
                    if (buf.size() < off + 1 || buf[off] != '$') { complete = false; break; }
                    const size_t nl2 = buf.find("\r\n", off);
                    if (nl2 == std::string::npos) { complete = false; break; }
                    const int len = std::atoi(buf.substr(off + 1, nl2 - off - 1).c_str());
                    off = nl2 + 2;
                    if (buf.size() < off + static_cast<size_t>(len) + 2) { complete = false; break; }
                    if (i == 0) cmd.assign(buf, off, static_cast<size_t>(len));
                    off += static_cast<size_t>(len) + 2;
                }
                if (!complete) break;
                buf.erase(0, off);
                off = 0;

                if (cmd == "PING") {
                    static constexpr char kPong[] = "+PONG\r\n";
                    send(client, kPong, static_cast<int>(sizeof(kPong) - 1), 0);
                } else if (cmd == "SET") {
                    static constexpr char kOk[] = "+OK\r\n";
                    send(client, kOk, static_cast<int>(sizeof(kOk) - 1), 0);
                }
                ++served;
            }
        }
    }

    SockType listener = kInvalidSocket;
    SockType client = kInvalidSocket;
    std::thread thread;
};

int main()
{
    RespServer server;
    if (!server.start()) {
        std::cerr << "failed to start RESP server\n";
        return 1;
    }

    sw::redis::ConnectionOptions opts;
    opts.host = "127.0.0.1";
    opts.port = server.port;
    opts.connect_timeout = std::chrono::milliseconds(3000);
    opts.socket_timeout = std::chrono::milliseconds(3000);

    sw::redis::ConnectionPoolOptions pool_opts;
    pool_opts.size = 1;

    try {
        sw::redis::AsyncRedis redis(opts, pool_opts);

        // Fire both commands back-to-back; the libuv loop runs on a background
        // thread and the server may see them pipelined in one segment.
        auto ping_res = redis.ping();
        auto set_res = redis.set("mcpp", "async");

        const std::string pong = ping_res.get();
        if (pong != "PONG") {
            std::cerr << "unexpected async PING reply: '" << pong << "'\n";
            return 2;
        }
        if (!set_res.get()) {
            std::cerr << "async SET did not return OK\n";
            return 3;
        }

        std::cout << "OK: async PING -> " << pong << ", SET -> OK\n";
        return 0;
    } catch (const sw::redis::Error &e) {
        std::cerr << "redis error: " << e.what() << "\n";
        return 4;
    }
}

// redis_test.cpp — offline behavioral test for compat.redis-plus-plus.
//
// No redis-server binary and no network access: this test runs a minimal RESP
// server inside the process (raw loopback sockets, same platform abstraction
// as the websocket member) and drives the sw::redis::Redis sync client against
// it. That exercises the full stack the package must get right:
//   * both static libs actually link (redis++ + hiredis),
//   * hiredis connects and speaks the RESP protocol (PING -> +PONG),
//   * redis++ formats commands (SET -> +OK) and parses replies back to C++.
#include <sw/redis++/redis++.h>

#include <atomic>
#include <chrono>
#include <cstdint>
#include <iostream>
#include <string>
#include <string_view>
#include <thread>

// ── Platform socket abstraction (same as tests/examples/websocket) ─────────

#ifdef _WIN32
#include <winsock2.h>
#include <ws2tcpip.h>
using SockType = SOCKET;
constexpr SockType kInvalidSocket = INVALID_SOCKET;
using AddrLenType = int;
#else
#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <unistd.h>
using SockType = int;
constexpr SockType kInvalidSocket = -1;
using AddrLenType = socklen_t;
#endif

void init_sockets()
{
#ifdef _WIN32
    WSADATA wsa;
    WSAStartup(MAKEWORD(2, 2), &wsa);
#endif
}

void close_socket(SockType s)
{
#ifdef _WIN32
    closesocket(s);
#else
    ::close(s);
#endif
}

// Safety net: any read that stalls this long makes the server thread return so
// the test fails cleanly instead of hanging the process (and, on CI, a runner).
void set_recv_timeout(SockType s, int ms)
{
#ifdef _WIN32
    DWORD t = static_cast<DWORD>(ms);
    setsockopt(s, SOL_SOCKET, SO_RCVTIMEO, reinterpret_cast<const char*>(&t), sizeof(t));
#else
    timeval tv{};
    tv.tv_sec = ms / 1000;
    tv.tv_usec = (ms % 1000) * 1000;
    setsockopt(s, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
#endif
}

// ── Minimal RESP server: answers PING with +PONG, SET with +OK ─────────────

class RespServer
{
public:
    ~RespServer()
    {
        if (client != kInvalidSocket) close_socket(client);
        if (listener != kInvalidSocket) close_socket(listener);
        if (thread.joinable()) thread.join();
    }

    bool start()
    {
        init_sockets();
        listener = socket(AF_INET, SOCK_STREAM, 0);
        if (listener == kInvalidSocket) return false;
        int one = 1;
#ifdef _WIN32
        setsockopt(listener, SOL_SOCKET, SO_REUSEADDR,
                   reinterpret_cast<const char*>(&one), sizeof(one));
#else
        setsockopt(listener, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));
#endif
        sockaddr_in addr{};
        addr.sin_family = AF_INET;
        addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        addr.sin_port = 0; // ephemeral
        if (bind(listener, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) != 0) return false;
        AddrLenType alen = sizeof(addr);
        getsockname(listener, reinterpret_cast<sockaddr*>(&addr), &alen);
        port = ntohs(addr.sin_port);
        if (listen(listener, 1) != 0) return false;
        thread = std::thread([this] { run(); });
        return true;
    }

    int port = 0;

private:
    void run()
    {
        SockType s = accept(listener, nullptr, nullptr);
        if (s == kInvalidSocket) return;
        client = s;
        set_recv_timeout(client, 5000);

        char buf[1024];
        int served = 0;
        // The client keeps the connection open for the whole test; serve a
        // handful of commands, then stop so the client's next read fails
        // cleanly instead of hanging.
        while (served < 8) {
            const int n = static_cast<int>(recv(client, buf, sizeof(buf) - 1, 0));
            if (n <= 0) break;
            const std::string_view req(buf, static_cast<size_t>(n));
            if (req.find("PING") != std::string_view::npos) {
                static constexpr char kPong[] = "+PONG\r\n";
                send(client, kPong, static_cast<int>(sizeof(kPong) - 1), 0);
                ++served;
            } else if (req.find("SET") != std::string_view::npos) {
                static constexpr char kOk[] = "+OK\r\n";
                send(client, kOk, static_cast<int>(sizeof(kOk) - 1), 0);
                ++served;
            }
        }
    }

    SockType listener = kInvalidSocket;
    SockType client = kInvalidSocket;
    std::thread thread;
};

int main()
{
    RespServer server;
    if (!server.start()) {
        std::cerr << "failed to start RESP server\n";
        return 1;
    }

    sw::redis::ConnectionOptions opts;
    opts.host = "127.0.0.1";
    opts.port = server.port;
    opts.connect_timeout = std::chrono::milliseconds(3000);
    opts.socket_timeout = std::chrono::milliseconds(3000);

    try {
        sw::redis::Redis redis(opts);

        const std::string pong = redis.ping();
        if (pong != "PONG") {
            std::cerr << "unexpected PING reply: '" << pong << "'\n";
            return 2;
        }

        if (!redis.set("mcpp", "redis-plus-plus")) {
            std::cerr << "SET did not return OK\n";
            return 3;
        }

        std::cout << "OK: PING -> " << pong << ", SET -> OK\n";
        return 0;
    } catch (const sw::redis::Error &e) {
        std::cerr << "redis error: " << e.what() << "\n";
        return 4;
    }
}

