// Behavioral test: struct -> JSON -> struct, through the JSON backend.
//
// The package compiles two umbrella TUs plus the vendored yyjson. All three have
// to be present and agree: leave out src/yyjson.c and this fails to LINK; get the
// include roots wrong and rfl/json/save.hpp picks a different yyjson than the one
// compiled, which fails at runtime rather than at build time. So the assertions
// go all the way to parsed values.
#include <rfl.hpp>
#include <rfl/json.hpp>

#include <cassert>
#include <optional>
#include <string>
#include <vector>

struct Point {
    int x;
    int y;
};

struct Document {
    std::string name;
    int version;
    bool enabled;
    std::vector<Point> points;
    std::optional<std::string> note;
};

int main() {
    const Document doc{
        .name = "mcpp",
        .version = 23,
        .enabled = true,
        .points = {{1, 2}, {-3, 4}},
        .note = std::nullopt,
    };

    // --- round trip ---
    const std::string json = rfl::json::write(doc);
    assert(!json.empty());

    const auto parsed = rfl::json::read<Document>(json);
    assert(parsed && "a document this library just wrote must parse");
    const Document& back = parsed.value();
    assert(back.name == doc.name);
    assert(back.version == doc.version);
    assert(back.enabled == doc.enabled);
    assert(back.points.size() == 2);
    assert(back.points[0].x == 1 && back.points[0].y == 2);
    assert(back.points[1].x == -3 && back.points[1].y == 4);
    assert(!back.note.has_value());

    // --- the field-name rename processor, which is why callers reach for rfl ---
    const std::string camel = rfl::json::write<rfl::SnakeCaseToCamelCase>(doc);
    const auto camel_back = rfl::json::read<Document, rfl::SnakeCaseToCamelCase>(camel);
    assert(camel_back && camel_back.value().version == doc.version);

    // --- a malformed document must fail, not throw or crash ---
    const auto bad = rfl::json::read<Document>(R"({"name": 5})");
    assert(!bad && "a type mismatch must surface as an error, not a value");

    // --- to_generic / from_generic, the path an RPC layer uses when the
    //     concrete type is only known per method ---
    const auto generic = rfl::to_generic(doc);
    const auto from_generic = rfl::from_generic<Document>(generic);
    assert(from_generic && from_generic.value().name == doc.name);

    // --- the JSON Schema generator ---
    const std::string schema = rfl::json::to_schema<Document>();
    assert(schema.find("version") != std::string::npos);

    return 0;
}

// Behavioral test — verify compat.sdl2 builds an SDL that can actually run a
// video subsystem, create a window and pump events.
//
// SDL is the one backend in this family that CAN be exercised headlessly:
// its `dummy` video driver is a real, fully functional driver that just never
// touches a display. So unlike the OpenGL and Vulkan backends, this is not a
// link-only smoke test — SDL_Init, SDL_CreateWindow, SDL_GetWindowSize and the
// event pump all execute.
//
// The driver is selected through SDL_HINT_VIDEODRIVER rather than the
// SDL_VIDEODRIVER environment variable so the test is self-contained and does
// not depend on how CI invokes it.
// SDL_MAIN_HANDLED before <SDL.h>: on Windows SDL_main.h does
// `#define main SDL_main` and expects the real entry point to come from
// SDL2main (src/main/windows/SDL_windows_main.c). This package does not ship
// that — a library consumer should not be handed an entry point — so the test
// takes SDL's documented alternative and keeps its own main, pairing it with
// SDL_SetMainReady() below. Without this the link fails with
// "LNK1561: entry point must be defined".
#define SDL_MAIN_HANDLED
#include <SDL.h>
import std;

int main() {
    SDL_SetMainReady();
    SDL_SetHint(SDL_HINT_VIDEODRIVER, "dummy");

    if (SDL_Init(SDL_INIT_VIDEO | SDL_INIT_EVENTS) != 0) {
        std::println("SDL_Init failed: {}", SDL_GetError());
        return 1;
    }

    // A build whose video subsystem never registered a driver fails here, which
    // is the failure mode a bad SDL_config.h produces — upstream's Linux
    // fallback config (SDL_config_minimal.h) builds exactly that.
    const char* driver = SDL_GetCurrentVideoDriver();
    if (driver == nullptr) {
        std::println("no video driver active: {}", SDL_GetError());
        SDL_Quit();
        return 2;
    }

    SDL_Window* window = SDL_CreateWindow(
        "compat.sdl2", SDL_WINDOWPOS_UNDEFINED, SDL_WINDOWPOS_UNDEFINED,
        320, 240, SDL_WINDOW_HIDDEN);
    if (window == nullptr) {
        std::println("SDL_CreateWindow failed: {}", SDL_GetError());
        SDL_Quit();
        return 3;
    }

    int width = 0;
    int height = 0;
    SDL_GetWindowSize(window, &width, &height);
    if (width != 320 || height != 240) {
        std::println("unexpected window size: {}x{}", width, height);
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 4;
    }

    // Pumping events exercises the event subsystem end to end; SDL_QUIT is
    // pushed and read back rather than waited for, so nothing here can hang.
    SDL_Event pushed{};
    pushed.type = SDL_QUIT;
    if (SDL_PushEvent(&pushed) < 0) {
        std::println("SDL_PushEvent failed: {}", SDL_GetError());
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 5;
    }
    SDL_PumpEvents();

    bool sawQuit = false;
    SDL_Event event{};
    while (SDL_PollEvent(&event) != 0) {
        if (event.type == SDL_QUIT) sawQuit = true;
    }
    if (!sawQuit) {
        std::println("pushed SDL_QUIT never came back out of the event queue");
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 6;
    }

    SDL_version linked{};
    SDL_GetVersion(&linked);

    std::println("compat.sdl2: ok (SDL {}.{}.{}, driver={}, {}x{} window, events round-tripped)",
                 linked.major, linked.minor, linked.patch, driver, width, height);

    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}

// Behavioral test — compat.sdl3 builds a working SDL3, not just headers.
//
// SDL is a library where "it compiled" is especially weak evidence: most of it
// is backends selected by a config header, and a wrong config produces a
// library that links and then has no video driver at all. So the assertions
// below are about what the BUILD CONFIG decided:
//
//   * the runtime version matches the headers (one tarball, not two)
//   * the compiled-in video driver list contains dummy AND offscreen, which
//     are exactly what a config that fell through to SDL_build_config_minimal.h
//     would NOT have
//   * the dummy driver actually initialises, creates a window, and gives back
//     a surface of the requested size
//   * the timer subsystem advances
//
// No `import std;` — SDL's headers are textual C over the standard headers.
// SDL_MAIN_HANDLED + SDL_main.h: this test brings its own main(), so SDL must
// not rename it. SDL_SetMainReady() is declared in SDL_main.h, not SDL.h.
#define SDL_MAIN_HANDLED
#include <SDL3/SDL.h>
#include <SDL3/SDL_main.h>

#include <cstdio>
#include <cstring>

int main() {
    // Header/runtime agreement. SDL_VERSION is the compile-time constant from
    // the headers; SDL_GetVersion() is what the linked objects report.
    const int compiled = SDL_VERSION;
    const int linked   = SDL_GetVersion();
    if (compiled != linked) {
        std::printf("header says %d, library says %d — two different SDLs\n", compiled, linked);
        return 1;
    }
    if (linked != SDL_VERSIONNUM(3, 4, 2)) {
        std::printf("SDL version is %d, expected 3.4.2\n", linked);
        return 2;
    }

    SDL_SetMainReady();

    // The compiled-in driver list. A minimal config has none of these.
    const int drivers = SDL_GetNumVideoDrivers();
    if (drivers <= 0) {
        std::printf("no video drivers compiled in — the build config did not take\n");
        return 3;
    }
    bool haveDummy = false, haveOffscreen = false;
    for (int i = 0; i < drivers; ++i) {
        const char* name = SDL_GetVideoDriver(i);
        if (!name) continue;
        if (std::strcmp(name, "dummy") == 0) haveDummy = true;
        if (std::strcmp(name, "offscreen") == 0) haveOffscreen = true;
    }
    if (!haveDummy || !haveOffscreen) {
        std::printf("driver list is missing dummy/offscreen (%d drivers):", drivers);
        for (int i = 0; i < drivers; ++i) std::printf(" %s", SDL_GetVideoDriver(i));
        std::printf("\n");
        return 4;
    }

    // Force dummy so this works with no display on any platform.
    SDL_SetHint(SDL_HINT_VIDEO_DRIVER, "dummy");
    if (!SDL_Init(SDL_INIT_VIDEO)) {
        std::printf("SDL_Init(VIDEO) failed: %s\n", SDL_GetError());
        return 5;
    }

    const char* current = SDL_GetCurrentVideoDriver();
    if (!current || std::strcmp(current, "dummy") != 0) {
        std::printf("current video driver is %s, expected dummy\n", current ? current : "(null)");
        SDL_Quit();
        return 6;
    }

    SDL_Window* window = SDL_CreateWindow("mcpp-index sdl3", 320, 240, 0);
    if (!window) {
        std::printf("SDL_CreateWindow failed: %s\n", SDL_GetError());
        SDL_Quit();
        return 7;
    }
    int w = 0, h = 0;
    SDL_GetWindowSize(window, &w, &h);
    if (w != 320 || h != 240) {
        std::printf("window is %dx%d, asked for 320x240\n", w, h);
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 8;
    }

    // The dummy driver still backs a window with a real surface, so this
    // exercises the surface/pixel code rather than only the window bookkeeping.
    SDL_Surface* surface = SDL_GetWindowSurface(window);
    if (!surface || surface->w != 320 || surface->h != 240) {
        std::printf("window surface missing or wrong size: %s\n", SDL_GetError());
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 9;
    }
    if (!SDL_FillSurfaceRect(surface, nullptr, SDL_MapSurfaceRGB(surface, 0, 0, 0))) {
        std::printf("SDL_FillSurfaceRect failed: %s\n", SDL_GetError());
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 10;
    }

    // Timer subsystem: SDL_GetTicks must advance across a delay.
    const Uint64 before = SDL_GetTicks();
    SDL_Delay(20);
    const Uint64 after = SDL_GetTicks();
    if (after < before + 10) {
        std::printf("SDL_GetTicks did not advance (%llu -> %llu)\n",
                    (unsigned long long)before, (unsigned long long)after);
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 11;
    }

    SDL_DestroyWindow(window);
    SDL_Quit();

    std::printf("compat.sdl3: ok (version 3.4.2, %d video drivers, dummy window 320x240, timer advances)\n",
                drivers);
    return 0;
}

// Behavioral test: consume compat.spdlog in COMPILED mode. Asserts both halves
// of what the `compiled` feature promises:
//
//   1. the interface define reached this TU (SPDLOG_COMPILED_LIB defined, and
//      spdlog's headers therefore did NOT flip on SPDLOG_HEADER_ONLY) — a
//      static check, so a regression is a compile error, not a silent fallback
//      to the header-only path that would still pass the runtime assertions;
//   2. spdlog's src/*.cpp really were compiled and linked — the calls below
//      resolve to out-of-line symbols (default_logger_raw, log_msg's ctor,
//      logger::log_it_, and bundled fmt's vformat), which is exactly what fails
//      to link when the engine skips a feature's sources.
#include <spdlog/spdlog.h>
#include <spdlog/sinks/ostream_sink.h>
#include <sstream>
#include <string>

#ifndef SPDLOG_COMPILED_LIB
#error "compiled feature did not propagate SPDLOG_COMPILED_LIB to the consumer"
#endif
#ifdef SPDLOG_HEADER_ONLY
#error "SPDLOG_HEADER_ONLY is on in compiled mode — headers took the inline path"
#endif

int main() {
    std::ostringstream captured;
    auto sink = std::make_shared<spdlog::sinks::ostream_sink_mt>(captured);
    spdlog::logger logger("test", sink);
    logger.set_pattern("%v");  // message only, no timestamp/level decoration

    logger.info("hello {}={}", "answer", 42);
    logger.warn("{:#x}", 255);
    logger.flush();

    // Exercises the global registry too — default_logger_raw() is one of the
    // out-of-line symbols that only exists once src/spdlog.cpp is compiled.
    spdlog::set_level(spdlog::level::info);

    const std::string out = captured.str();
    const bool ok = out.find("hello answer=42") != std::string::npos
                    && out.find("0xff") != std::string::npos;
    return ok ? 0 : 1;
}

