    std::println("khronos.vulkan-hpp: ok (import vulkan_video; H.264 profile idc baseline={}, high={})",
                 static_cast<unsigned>(vk::video::H264ProfileIdc::eBaseline),
                 static_cast<unsigned>(vk::video::H264ProfileIdc::eHigh));
