// compat.vulkan-memory-allocator — drive VMA's VIRTUAL allocator.
//
// Everything else in VMA needs a VkDevice, which a CI runner with no GPU and no
// driver cannot create. The virtual allocator is the same sub-allocation
// algorithm with the Vulkan calls stripped out: it hands out offsets inside a
// notional block. That makes it the one part of VMA whose BEHAVIOUR can be
// asserted here -- and since it is compiled from the same VMA_IMPLEMENTATION
// TU as the rest, it still proves the package's implementation is built and
// linked (these symbols do not exist in the header-only view).
#include <vk_mem_alloc.h>
import std;

int main() {
    bool ok = true;
    auto check = [&](bool cond, std::string_view what) {
        if (!cond) {
            std::println("FAIL: {}", what);
            ok = false;
        }
    };

    constexpr VkDeviceSize BLOCK = 1u << 20;   // 1 MiB

    VmaVirtualBlockCreateInfo bci{};
    bci.size = BLOCK;

    VmaVirtualBlock block = VK_NULL_HANDLE;
    check(vmaCreateVirtualBlock(&bci, &block) == VK_SUCCESS, "virtual block created");
    check(block != VK_NULL_HANDLE, "block handle is non-null");
    if (block == VK_NULL_HANDLE) return 1;

    check(vmaIsVirtualBlockEmpty(block), "a fresh block is empty");

    // Allocate a set of differently-sized, differently-aligned chunks.
    struct Chunk { VmaVirtualAllocation h; VkDeviceSize off, size; };
    std::vector<Chunk> chunks;
    for (int i = 0; i < 16; ++i) {
        VmaVirtualAllocationCreateInfo aci{};
        aci.size      = static_cast<VkDeviceSize>(1024u << (i % 5));
        aci.alignment = 256;

        VmaVirtualAllocation h{};
        VkDeviceSize off = 0;
        if (vmaVirtualAllocate(block, &aci, &h, &off) != VK_SUCCESS) {
            check(false, "vmaVirtualAllocate succeeded");
            break;
        }
        check(off % 256 == 0, "returned offset honours the requested alignment");
        check(off + aci.size <= BLOCK, "allocation stays inside the block");
        chunks.push_back({h, off, aci.size});
    }
    check(chunks.size() == 16, "all 16 allocations succeeded");
    check(!vmaIsVirtualBlockEmpty(block), "block is not empty while allocations live");

    // The whole point of an allocator: no two live allocations may overlap.
    std::ranges::sort(chunks, {}, &Chunk::off);
    for (std::size_t i = 1; i < chunks.size(); ++i) {
        check(chunks[i - 1].off + chunks[i - 1].size <= chunks[i].off,
              "live allocations do not overlap");
    }

    // Statistics must account for what we asked for.
    VkDeviceSize requested = 0;
    for (const auto& c : chunks) requested += c.size;

    VmaStatistics stats{};
    vmaGetVirtualBlockStatistics(block, &stats);
    check(stats.allocationCount == chunks.size(), "stats report every allocation");
    check(stats.allocationBytes == requested, "stats report the requested bytes");

    // Freeing must return the space: after freeing everything the block is
    // empty again and a single block-sized allocation fits.
    for (const auto& c : chunks) vmaVirtualFree(block, c.h);
    check(vmaIsVirtualBlockEmpty(block), "block is empty again after freeing all");

    VmaVirtualAllocationCreateInfo whole{};
    whole.size = BLOCK;
    VmaVirtualAllocation big{};
    VkDeviceSize big_off = 0;
    check(vmaVirtualAllocate(block, &whole, &big, &big_off) == VK_SUCCESS,
          "the entire block is allocatable once freed");
    check(big_off == 0, "the block-sized allocation starts at offset 0");
    vmaVirtualFree(block, big);

    // And an over-sized request must FAIL rather than silently succeed.
    VmaVirtualAllocationCreateInfo toobig{};
    toobig.size = BLOCK * 2;
    VmaVirtualAllocation none{};
    VkDeviceSize none_off = 0;
    check(vmaVirtualAllocate(block, &toobig, &none, &none_off) != VK_SUCCESS,
          "an over-sized request is rejected");

    vmaDestroyVirtualBlock(block);

    if (ok) std::println("VulkanMemoryAllocator OK");
    return ok ? 0 : 1;
}

// Behavioral test — verify compat.vulkan builds a working loader and that a
// consumer can link its trampolines.
//
// Everything asserted here is answered by the LOADER itself, before any ICD is
// involved, so it is meaningful on a CI runner with no GPU and no driver.
// That constraint is sharper than it looks: the loader advertises the WSI
// surface extensions only when some ICD supports them, so `VK_KHR_surface` is
// legitimately ABSENT on a driverless machine and asserting on it would just be
// testing the runner's hardware.
//
// HAVE_VULKAN_LOADER is set by THIS project's own [build] cxxflags. A consumer
// that keys its source off a dependency's presence has to declare that itself.
#if defined(HAVE_VULKAN_LOADER)
#include <vulkan/vulkan.h>
#endif
import std;

#if defined(HAVE_VULKAN_LOADER) && defined(_WIN32)
// Declared rather than taken from <windows.h>: two functions are needed, and
// the header's macros and min/max collide with `import std`. Both live in
// kernel32, which every Windows program already links.
extern "C" __declspec(dllimport) void* GetModuleHandleW(const wchar_t* name);
extern "C" __declspec(dllimport) unsigned long GetModuleFileNameW(void* module, wchar_t* path,
                                                                  unsigned long size);
#endif

#if !defined(HAVE_VULKAN_LOADER)
int main() {
    std::println("compat.vulkan: skipped (no windows build — static loader unsupported upstream)");
    return 0;
}
#else
int main() {
    // Only the loader can answer this — it reports the Vulkan version the
    // loader itself implements. A package that failed to compile its
    // trampolines fails at LINK here rather than passing quietly.
    std::uint32_t apiVersion = 0;
    if (vkEnumerateInstanceVersion(&apiVersion) != VK_SUCCESS) {
        std::println("vkEnumerateInstanceVersion failed");
        return 1;
    }
    if (VK_VERSION_MAJOR(apiVersion) < 1) {
        std::println("implausible loader api version: {}", apiVersion);
        return 2;
    }

#if defined(_WIN32)
    // WHERE THE LOADER CAME FROM is the point of compat.vulkan 1.4.357.3 on
    // Windows: the package now ships vulkan-1.dll and mcpp places it beside the
    // executable, so a machine with no GPU driver can still start this program.
    // The loader has just answered, so the DLL is mapped; its directory must be
    // this executable's. That holds on a machine WITH a driver too (the
    // application directory precedes System32), which is what makes this a real
    // check: with an older compat.vulkan the loader came from System32 there,
    // and on a driverless machine the process never reached main.
    {
        std::vector<wchar_t> dll(32768), exe(32768);
        void* module = GetModuleHandleW(L"vulkan-1.dll");
        if (module == nullptr) {
            std::println("vulkan-1.dll answered but is not mapped in this process");
            return 7;
        }
        const auto dllLen = GetModuleFileNameW(module, dll.data(), 32768);
        const auto exeLen = GetModuleFileNameW(nullptr, exe.data(), 32768);
        auto dirOf = [](std::wstring_view p) {
            std::wstring d(p.substr(0, p.find_last_of(L"\\/")));
            for (auto& c : d) c = static_cast<wchar_t>(std::towlower(c));
            return d;
        };
        auto narrow = [](std::wstring_view p) {
            std::string out;
            for (wchar_t c : p) out.push_back(c < 128 ? static_cast<char>(c) : '?');
            return out;
        };
        const std::wstring_view dllPath(dll.data(), dllLen), exePath(exe.data(), exeLen);
        if (dirOf(dllPath) != dirOf(exePath)) {
            std::println("vulkan-1.dll was loaded from {}, not beside {}",
                         narrow(dllPath), narrow(exePath));
            return 8;
        }
        std::println("compat.vulkan: loader deployed beside the executable ({})", narrow(dllPath));
    }
#endif

    std::uint32_t extensionCount = 0;
    if (vkEnumerateInstanceExtensionProperties(nullptr, &extensionCount, nullptr) != VK_SUCCESS) {
        std::println("vkEnumerateInstanceExtensionProperties failed");
        return 3;
    }
    std::vector<VkExtensionProperties> extensions(extensionCount);
    if (extensionCount > 0 &&
        vkEnumerateInstanceExtensionProperties(nullptr, &extensionCount, extensions.data()) != VK_SUCCESS) {
        std::println("vkEnumerateInstanceExtensionProperties (fill) failed");
        return 4;
    }

    // VK_EXT_debug_utils is implemented BY the loader, so it is present with or
    // without a driver — unlike the surface extensions. Its absence would mean
    // the loader's own extension table never made it into the lib.
    const bool haveDebugUtils = std::ranges::any_of(extensions, [](const VkExtensionProperties& e) {
        return std::string_view(e.extensionName) == VK_EXT_DEBUG_UTILS_EXTENSION_NAME;
    });
    if (!haveDebugUtils) {
        std::println("VK_EXT_debug_utils missing from {} loader extension(s)", extensionCount);
        for (const auto& e : extensions) std::println("  {}", e.extensionName);
        return 5;
    }

    // Link-time proof that wsi.c is in the library. vkDestroySurfaceKHR is a
    // WSI trampoline; referencing it makes a build without that translation
    // unit fail to link, which is the check the extension list cannot give us
    // on a driverless machine.
    if (&vkDestroySurfaceKHR == nullptr) {
        std::println("vkDestroySurfaceKHR unexpectedly null");
        return 6;
    }

    std::println("compat.vulkan: ok (loader api {}.{}.{}, {} loader extension(s), WSI trampolines linked)",
                 VK_VERSION_MAJOR(apiVersion), VK_VERSION_MINOR(apiVersion),
                 VK_VERSION_PATCH(apiVersion), extensionCount);
    return 0;
}
#endif

// Feature test for compat.wamr: assert that the two optional guest-libc layers
// are actually linked in when requested.
//
// The discriminator is a CALL, not instantiation. WAMR does not reject a
// module whose import is unresolved — the loader logs "failed to link import
// function" and carries on, so instantiation succeeds either way. The refusal
// only appears when the guest calls the import, as an exception naming it
// "unlinked". tests/examples/wamr asserts exactly that for env.putchar against
// the base package; here the same call must go through.
#ifdef __linux__

#include <wasm_export.h>

#include <cstdio>
#include <cstdlib>
#include <cstring>

namespace {

// (module (import "env" "putchar" (func (param i32) (result i32)))
//         (func (export "emit") (param i32) (result i32) local.get 0 call 0))
const unsigned char kNeedsLibcBuiltin[] = {
    0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00,
    0x01, 0x06, 0x01, 0x60, 0x01, 0x7f, 0x01, 0x7f,
    0x02, 0x0f, 0x01, 0x03, 'e', 'n', 'v',
                      0x07, 'p', 'u', 't', 'c', 'h', 'a', 'r', 0x00, 0x00,
    0x03, 0x02, 0x01, 0x00,
    0x07, 0x08, 0x01, 0x04, 'e', 'm', 'i', 't', 0x00, 0x01,
    0x0a, 0x08, 0x01, 0x06, 0x00, 0x20, 0x00, 0x10, 0x00, 0x0b,
};

// (module (import "wasi_snapshot_preview1" "proc_exit" (func (param i32)))
//         (memory (export "memory") 1)
//         (func (export "exit0") (param i32) local.get 0 call 0))
//
// The memory is not optional decoration: WAMR refuses to load a module that
// imports WASI apis without an exported memory ("a module with WASI apis must
// export memory by default"), because the WASI wrappers address the guest's
// linear memory to return their results.
const unsigned char kNeedsLibcWasi[] = {
    0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00,
    0x01, 0x05, 0x01, 0x60, 0x01, 0x7f, 0x00,
    0x02, 0x24, 0x01,
    0x16, 'w', 'a', 's', 'i', '_', 's', 'n', 'a', 'p', 's', 'h', 'o', 't',
          '_', 'p', 'r', 'e', 'v', 'i', 'e', 'w', '1',
    0x09, 'p', 'r', 'o', 'c', '_', 'e', 'x', 'i', 't', 0x00, 0x00,
    0x03, 0x02, 0x01, 0x00,
    0x05, 0x03, 0x01, 0x00, 0x01,
    0x07, 0x12, 0x02, 0x05, 'e', 'x', 'i', 't', '0', 0x00, 0x01,
                      0x06, 'm', 'e', 'm', 'o', 'r', 'y', 0x02, 0x00,
    0x0a, 0x08, 0x01, 0x06, 0x00, 0x20, 0x00, 0x10, 0x00, 0x0b,
};

bool g_ok = true;

void check(const char *what, bool cond)
{
    std::printf("%-28s %s\n", what, cond ? "ok" : "FAILED");
    g_ok = g_ok && cond;
}

} // namespace

int main()
{
    RuntimeInitArgs init;
    std::memset(&init, 0, sizeof init);
    init.mem_alloc_type = Alloc_With_Allocator;
    init.mem_alloc_option.allocator.malloc_func = reinterpret_cast<void *>(std::malloc);
    init.mem_alloc_option.allocator.realloc_func = reinterpret_cast<void *>(std::realloc);
    init.mem_alloc_option.allocator.free_func = reinterpret_cast<void *>(std::free);

    if (!wasm_runtime_full_init(&init)) {
        std::puts("wasm_runtime_full_init failed");
        return 1;
    }

    char err[192] = { 0 };

    // ── libc-builtin: env.putchar must link and run ────────────────────────
    {
        unsigned char image[sizeof kNeedsLibcBuiltin];
        std::memcpy(image, kNeedsLibcBuiltin, sizeof image);
        wasm_module_t mod = wasm_runtime_load(image, sizeof image, err, sizeof err);
        check("libc-builtin load", mod != nullptr);
        if (mod) {
            wasm_module_inst_t inst =
                wasm_runtime_instantiate(mod, 8192, 8192, err, sizeof err);
            check("libc-builtin instantiate", inst != nullptr);
            if (inst) {
                wasm_function_inst_t fn = wasm_runtime_lookup_function(inst, "emit");
                wasm_exec_env_t env = wasm_runtime_create_exec_env(inst, 8192);
                if (fn && env) {
                    // putchar writes the byte and returns 1 (see
                    // libc_builtin_wrapper.c putchar_wrapper) -- it is not the
                    // C library's "returns the character written".
                    uint32_t argv[1] = { 0x0a };
                    bool called = wasm_runtime_call_wasm(env, fn, 1, argv);
                    if (!called)
                        std::printf("  exception: %s\n",
                                    wasm_runtime_get_exception(inst));
                    check("libc-builtin putchar call", called && argv[0] == 1);
                }
                else {
                    check("libc-builtin lookup/env", false);
                }
                if (env)
                    wasm_runtime_destroy_exec_env(env);
                wasm_runtime_deinstantiate(inst);
            }
            wasm_runtime_unload(mod);
        }
    }

    // ── libc-wasi: wasi_snapshot_preview1.proc_exit must link and run ──────
    // proc_exit does not end the process; the wrapper raises "wasi proc exit"
    // and records the code, which the embedder then reads. That round trip is
    // only possible with the feature's sources compiled in.
    {
        unsigned char image[sizeof kNeedsLibcWasi];
        std::memcpy(image, kNeedsLibcWasi, sizeof image);
        wasm_module_t mod = wasm_runtime_load(image, sizeof image, err, sizeof err);
        if (!mod)
            std::printf("  load error: %s\n", err);
        check("libc-wasi load", mod != nullptr);
        if (mod) {
            // Gives the module a wasi context; the wrapper dereferences it.
            wasm_runtime_set_wasi_args(mod, nullptr, 0, nullptr, 0, nullptr, 0,
                                       nullptr, 0);
            wasm_module_inst_t inst =
                wasm_runtime_instantiate(mod, 8192, 8192, err, sizeof err);
            check("libc-wasi instantiate", inst != nullptr);
            if (inst) {
                wasm_function_inst_t fn = wasm_runtime_lookup_function(inst, "exit0");
                wasm_exec_env_t env = wasm_runtime_create_exec_env(inst, 8192);
                if (fn && env) {
                    uint32_t argv[1] = { 3 };
                    bool called = wasm_runtime_call_wasm(env, fn, 1, argv);
                    const char *ex = wasm_runtime_get_exception(inst);
                    std::printf("  call=%d exception=%s exit_code=%u\n", called ? 1 : 0,
                                ex ? ex : "(none)",
                                wasm_runtime_get_wasi_exit_code(inst));
                    // The one thing that must NOT happen is the unlinked-import
                    // refusal; that is the signal the feature was not compiled in.
                    bool unlinked = ex && std::strstr(ex, "unlinked") != nullptr;
                    check("libc-wasi proc_exit linked", !unlinked);
                    check("libc-wasi exit code", wasm_runtime_get_wasi_exit_code(inst) == 3);
                }
                else {
                    check("libc-wasi lookup/env", false);
                }
                if (env)
                    wasm_runtime_destroy_exec_env(env);
                wasm_runtime_deinstantiate(inst);
            }
            wasm_runtime_unload(mod);
        }
    }

    wasm_runtime_destroy();
    return g_ok ? 0 : 1;
}

#else
int main() { return 0; }
#endif

// Behavioral test for compat.wamr: run a real wasm module through the
// interpreter and let it call back into the host.
//
// Nothing here is mocked. A package that links but mis-configures the runtime
// would pass a "does it link" test: without BUILD_TARGET_* the invoke-native
// section compiles to nothing, and without the generated dispatcher there is
// no invokeNative at all — either way the guest→host call below is what
// notices.
#ifdef __linux__

#include <wasm_export.h>

#include <cstdio>
#include <cstdlib>
#include <cstring>

namespace {

// (module
//   (import "env" "host_mul" (func $host_mul (param i32 i32) (result i32)))
//   (func (export "compute") (param i32 i32) (result i32)
//     local.get 0  local.get 1  call $host_mul))
const unsigned char kCallsHost[] = {
    0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00,
    0x01, 0x07, 0x01, 0x60, 0x02, 0x7f, 0x7f, 0x01, 0x7f,
    0x02, 0x10, 0x01, 0x03, 'e', 'n', 'v',
                      0x08, 'h', 'o', 's', 't', '_', 'm', 'u', 'l', 0x00, 0x00,
    0x03, 0x02, 0x01, 0x00,
    0x07, 0x0b, 0x01, 0x07, 'c', 'o', 'm', 'p', 'u', 't', 'e', 0x00, 0x01,
    0x0a, 0x0a, 0x01, 0x08, 0x00, 0x20, 0x00, 0x20, 0x01, 0x10, 0x00, 0x0b,
};

// Same shape, but importing `env.putchar` — one of the wrappers the
// `libc-builtin` feature adds. The base package must NOT resolve it; this is
// the negative half of the feature gate, with the positive half in
// tests/examples/wamr-features.
const unsigned char kNeedsLibcBuiltin[] = {
    0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00,
    0x01, 0x06, 0x01, 0x60, 0x01, 0x7f, 0x01, 0x7f,
    0x02, 0x0f, 0x01, 0x03, 'e', 'n', 'v',
                      0x07, 'p', 'u', 't', 'c', 'h', 'a', 'r', 0x00, 0x00,
    0x03, 0x02, 0x01, 0x00,
    0x07, 0x08, 0x01, 0x04, 'e', 'm', 'i', 't', 0x00, 0x01,
    0x0a, 0x08, 0x01, 0x06, 0x00, 0x20, 0x00, 0x10, 0x00, 0x0b,
};

int host_mul(wasm_exec_env_t, int a, int b) { return a * b; }

NativeSymbol g_natives[] = {
    { "host_mul", reinterpret_cast<void *>(host_mul), "(ii)i", nullptr },
};

// Calls `emit` in the given module and reports whether WAMR refused because
// the import was never linked.
//
// An unresolved import is NOT an instantiation error in WAMR — the loader only
// logs "failed to link import function" and defers, so asking whether the
// module instantiates says nothing about the feature gate. The refusal only
// materialises on the call, as an exception naming the unlinked function.
bool refused_as_unlinked(const unsigned char *bytes, unsigned size)
{
    char err[192] = { 0 };
    // wasm_runtime_load takes a mutable buffer: it may patch the module image
    // in place, so hand it a copy rather than the const literal.
    unsigned char *buf = static_cast<unsigned char *>(std::malloc(size));
    if (!buf)
        return false;
    std::memcpy(buf, bytes, size);

    bool unlinked = false;
    wasm_module_t mod = wasm_runtime_load(buf, size, err, sizeof err);
    if (!mod) {
        std::printf("  load rejected: %s\n", err);
    }
    else {
        wasm_module_inst_t inst =
            wasm_runtime_instantiate(mod, 8192, 8192, err, sizeof err);
        if (!inst) {
            std::printf("  instantiate rejected: %s\n", err);
        }
        else {
            wasm_function_inst_t fn = wasm_runtime_lookup_function(inst, "emit");
            wasm_exec_env_t env = wasm_runtime_create_exec_env(inst, 8192);
            if (fn && env) {
                uint32_t argv[1] = { 65 };
                if (!wasm_runtime_call_wasm(env, fn, 1, argv)) {
                    const char *ex = wasm_runtime_get_exception(inst);
                    std::printf("  exception: %s\n", ex ? ex : "(none)");
                    unlinked = ex && std::strstr(ex, "unlinked") != nullptr;
                }
            }
            if (env)
                wasm_runtime_destroy_exec_env(env);
            wasm_runtime_deinstantiate(inst);
        }
        wasm_runtime_unload(mod);
    }
    std::free(buf);
    return unlinked;
}

} // namespace

int main()
{
    RuntimeInitArgs init;
    std::memset(&init, 0, sizeof init);
    init.mem_alloc_type = Alloc_With_Allocator;
    init.mem_alloc_option.allocator.malloc_func = reinterpret_cast<void *>(std::malloc);
    init.mem_alloc_option.allocator.realloc_func = reinterpret_cast<void *>(std::realloc);
    init.mem_alloc_option.allocator.free_func = reinterpret_cast<void *>(std::free);
    init.native_module_name = "env";
    init.native_symbols = g_natives;
    init.n_native_symbols = 1;

    bool ok = wasm_runtime_full_init(&init);
    if (!ok) {
        std::puts("wasm_runtime_full_init failed");
        return 1;
    }

    char err[192] = { 0 };
    unsigned char image[sizeof kCallsHost];
    std::memcpy(image, kCallsHost, sizeof image);

    wasm_module_t mod = wasm_runtime_load(image, sizeof image, err, sizeof err);
    ok = ok && mod != nullptr;
    if (!mod)
        std::printf("load failed: %s\n", err);

    wasm_module_inst_t inst = nullptr;
    if (mod) {
        inst = wasm_runtime_instantiate(mod, 8192, 8192, err, sizeof err);
        ok = ok && inst != nullptr;
        if (!inst)
            std::printf("instantiate failed: %s\n", err);
    }

    if (inst) {
        wasm_function_inst_t fn = wasm_runtime_lookup_function(inst, "compute");
        ok = ok && fn != nullptr;
        if (fn) {
            wasm_exec_env_t env = wasm_runtime_create_exec_env(inst, 8192);
            ok = ok && env != nullptr;
            if (env) {
                uint32_t argv[2] = { 6, 7 };
                bool called = wasm_runtime_call_wasm(env, fn, 2, argv);
                if (!called)
                    std::printf("call failed: %s\n",
                                wasm_runtime_get_exception(inst));
                // 6 * 7 computed by the HOST and returned through the guest.
                ok = ok && called && argv[0] == 42u;
                std::printf("compute(6,7) = %u (expected 42)\n", argv[0]);
                wasm_runtime_destroy_exec_env(env);
            }
        }
        wasm_runtime_deinstantiate(inst);
    }
    if (mod)
        wasm_runtime_unload(mod);

    // Feature gate, negative direction: libc-builtin is not in the base build,
    // so a module importing env.putchar must be refused.
    std::puts("expecting env.putchar to be unlinked (libc-builtin is off):");
    bool libc_absent =
        refused_as_unlinked(kNeedsLibcBuiltin, sizeof kNeedsLibcBuiltin);
    ok = ok && libc_absent;
    std::printf("libc-builtin gated out: %s\n", libc_absent ? "yes" : "NO");

    wasm_runtime_destroy();
    return ok ? 0 : 1;
}

#else
int main() { return 0; }
#endif

// freedesktop.wayland-cursor — the client-side pointer.
//
// WHAT CANNOT BE ASSERTED HERE, AND WHY THE FIRST VERSION OF THIS FILE CRASHED
//
// `wl_cursor_theme_load(name, size, shm)` is not callable without a compositor,
// and not merely inadvisable: line 410 of upstream's wayland-cursor.c is
//
//     theme->pool = shm_pool_create(shm, size * size * 4);
//
// which reaches `wl_shm_create_pool(shm, ...)` and dereferences the proxy with
// no null check. The first version of this test passed `nullptr` on the theory
// that only the theme PARSER would run — it segfaulted (exit 139). A `wl_shm`
// comes from a compositor's registry, so the buffer half of this library
// belongs in a program that has one, exactly as opening /dev/input/event*
// belongs outside tests/examples/libinput.
//
// WHAT IS ASSERTED IS STILL THE PART THAT CARRIES THE PACKAGING RISK: that the
// hand-written module wrapper exports every name, that the two PUBLIC structs
// are usable as values rather than opaque handles, and that libwayland-client
// is really linked in. The compiled-in cursor search path being empty — the
// other packaging decision — is checked in the fork's CI by grepping the
// binary, which is the only place it is visible.

#ifdef __linux__

#include <wayland-client.h>
#include <wayland-cursor.h>

#include <cstdio>
#include <cstdlib>
#include <cstring>

import freedesktop.wayland.cursor;

namespace {

int failures = 0;

void check(bool ok, const char *what)
{
    std::printf("%-58s %s\n", what, ok ? "ok" : "FAILED");
    if (!ok) {
        ++failures;
    }
}

} // namespace

int main()
{
    // ── 1. The module carries the API ────────────────────────────────────
    // Taking the address of each: a name that vanished from the hand-written
    // module wrapper is a compile error here. That is the guarantee
    // mcpp/tools/genmod.py gives the client and server wrappers, which this
    // one is too small to justify.
    check(&wl_cursor_theme_load != nullptr,         "module exports wl_cursor_theme_load");
    check(&wl_cursor_theme_destroy != nullptr,      "module exports wl_cursor_theme_destroy");
    check(&wl_cursor_theme_get_cursor != nullptr,   "module exports wl_cursor_theme_get_cursor");
    check(&wl_cursor_image_get_buffer != nullptr,   "module exports wl_cursor_image_get_buffer");
    check(&wl_cursor_frame != nullptr,              "module exports wl_cursor_frame");
    check(&wl_cursor_frame_and_duration != nullptr, "module exports wl_cursor_frame_and_duration");

    // ── 2. The public structs are VALUES, not opaque handles ─────────────
    // `wl_cursor` and `wl_cursor_image` have their fields in the public header
    // and a client reads them to place the hotspot every time the pointer
    // enters a surface. Exporting them as opaque would compile here and fail
    // at the caller's first `image->hotspot_x`, which is why the fields are
    // touched rather than just the types named.
    wl_cursor_image img{};
    img.width = 24; img.height = 24;
    img.hotspot_x = 4; img.hotspot_y = 4; img.delay = 50;
    check(img.width == 24 && img.hotspot_x == 4 && img.delay == 50,
          "wl_cursor_image fields are reachable through the module");

    wl_cursor cur{};
    wl_cursor_image *one = &img;
    cur.image_count = 1;
    cur.images = &one;
    cur.name = const_cast<char *>("left_ptr");
    check(cur.image_count == 1 && cur.images[0]->hotspot_y == 4,
          "wl_cursor fields are reachable, including the images array");

    // ── 3. wl_cursor_frame works on a theme-less cursor ──────────────────
    // The animation helper is pure arithmetic over the images array — no shm,
    // no compositor — so it IS callable here, and it is the one piece of real
    // behaviour this test can exercise. A single-image cursor is not animated,
    // so every timestamp must select frame 0.
    check(wl_cursor_frame(&cur, 0) == 0,      "wl_cursor_frame(t=0) selects the only frame");
    check(wl_cursor_frame(&cur, 100000) == 0, "…and so does a far-future timestamp");

    uint32_t duration = 12345;   // wayland-cursor.h includes <stdint.h>, not <cstdint>
    const int f = wl_cursor_frame_and_duration(&cur, 0, &duration);
    std::printf("   frame_and_duration -> frame %d, duration %u\n", f, duration);
    check(f == 0, "wl_cursor_frame_and_duration agrees on the frame");

    // ── 4. It links the client for real ──────────────────────────────────
    // Unlike libwayland-egl, this library CALLS into libwayland-client — that
    // is exactly why §3's theme loader needs a live wl_shm. The two are in one
    // program by necessity rather than by convention.
    //
    // `wl_display_connect` AND NOT `wl_shm_create_pool`, which is what this
    // check said first and what the llvm leg rejected:
    //
    //     ld.lld: error: undefined symbol: wl_proxy_get_version
    //     >>>   wayland-cursor.o:(wl_shm_create_pool(wl_shm*, int, int))
    //
    // `wl_shm_create_pool` is one of wayland-scanner's `static inline`
    // protocol wrappers (mcpp/generated/wayland-client-protocol.h:2202), so
    // taking its address FORCES this translation unit to emit a copy — and
    // that copy calls `wl_proxy_marshal_flags` and friends, which live in
    // libwayland-client. GNU ld resolves those through the transitive
    // DT_NEEDED of libwayland-cursor; lld deliberately does not, and lld is
    // right: a program that names a symbol should link the library that
    // defines it.
    //
    // `wl_display_connect` is an ordinary exported function, so referencing it
    // proves the same thing without emitting anything. Same form the sibling
    // wayland-egl test uses, which is why that one was green on both legs.
    check(&wl_display_connect != nullptr,
          "libwayland-client is linked in (wl_display_connect)");

    // ── 5. Report the environment the ecosystem is expected to fill ───────
    // Not asserted: nothing in the index or in xim ships cursor themes yet, so
    // an unset XCURSOR_PATH is the current correct state rather than a defect.
    // When a theme package exists this becomes an assertion, exactly as the
    // RMLVO check in tests/examples/libxkbcommon did once xkeyboard-config
    // landed.
    const char *xp = std::getenv("XCURSOR_PATH");
    std::printf("   XCURSOR_PATH = %s\n",
                xp ? xp : "(unset — no cursor-theme package exists yet)");

    std::printf("\n%d check(s) failed\n", failures);
    return failures == 0 ? 0 : 1;
}

#else
int main() { return 0; }
#endif

// freedesktop.wayland-egl — the step that used to be missing.
//
// WHAT THIS CAN AND CANNOT ASSERT, decided by what the library actually is.
//
// libwayland-egl is 118 lines and holds no connection: `wl_egl_window_create`
// allocates a struct, stores the `wl_surface *` it was handed, and records a
// size. It calls no client function and talks to no compositor — an EGL
// implementation later reads and writes the struct through
// `wayland-egl-backend.h`.
//
// So a CI runner with no compositor can exercise the whole library honestly.
// What it cannot do is `eglCreateWindowSurface`, which needs a real
// `wl_display` from a real compositor — asserting that here would only assert
// that the runner has a desktop session.
//
// THE BACKEND HEADER IS INCLUDED ON PURPOSE. `wayland-egl-core.h` exposes four
// functions and an opaque type, so through it alone the only observable is
// "create returned non-null". `wayland-egl-backend.h` is the contract this
// library has with an EGL implementation — Mesa includes it — and reading the
// struct through it is what lets the test check that create and resize wrote
// what they claim.
//
// The `wl_surface *` is a null pointer ON PURPOSE: upstream stores it without
// dereferencing (wayland-egl.c:93), so this exercises the real path, and the
// test can then assert the pointer round-tripped.

#ifdef __linux__

#include <wayland-client.h>
#include <wayland-egl.h>
#include <wayland-egl-backend.h>

#include <cstdio>
#include <cstring>

import freedesktop.wayland.egl;

namespace {

int failures = 0;

void check(bool ok, const char *what)
{
    std::printf("%-58s %s\n", what, ok ? "ok" : "FAILED");
    if (!ok) {
        ++failures;
    }
}

} // namespace

int main()
{
    // ── 1. The module carries the API ────────────────────────────────────
    // Taking the address of each is what makes this a check rather than a
    // comment: a name that vanished from the module is a compile error here,
    // which is the guarantee genmod.py gives the client and server wrappers
    // and that this hand-written module needs by other means.
    check(&wl_egl_window_create != nullptr,            "module exports wl_egl_window_create");
    check(&wl_egl_window_destroy != nullptr,           "module exports wl_egl_window_destroy");
    check(&wl_egl_window_resize != nullptr,            "module exports wl_egl_window_resize");
    check(&wl_egl_window_get_attached_size != nullptr, "module exports wl_egl_window_get_attached_size");

    // ── 2. The bridge itself ─────────────────────────────────────────────
    // This is the call that did not exist in this ecosystem before: the only
    // way to turn a wl_surface into something EGL can render into.
    wl_egl_window *w = wl_egl_window_create(nullptr, 640, 480);
    check(w != nullptr, "wl_egl_window_create(surface, 640, 480)");
    if (w == nullptr) {
        std::printf("\n%d check(s) failed\n", failures);
        return 1;
    }

    // ── 3. It wrote what it was given ────────────────────────────────────
    // Read back through the backend header, which is how Mesa reads it.
    // `version` matters most of the three: an EGL implementation switches on
    // it, and it is the field upstream casts away constness to set.
    std::printf("   version=%ld  size=%d x %d\n",
                (long)w->version, w->width, w->height);
    check(w->version == WL_EGL_WINDOW_VERSION, "…and stamped WL_EGL_WINDOW_VERSION");
    check(w->width == 640 && w->height == 480, "…and recorded 640 x 480");
    check(w->surface == nullptr,               "…and round-tripped the wl_surface pointer");

    // ── 4. attached size is 0 BEFORE any EGL implementation attaches ─────
    // Not an oversight and not the creation size: `attached_width/height` are
    // written by the EGL side when it attaches a buffer, and `create` calloc's
    // them to zero. The first version of this test asserted 640 x 480 here and
    // was wrong — the check now encodes the real contract, which is that a
    // window nothing has rendered into reports nothing attached.
    int aw = -1, ah = -1;
    wl_egl_window_get_attached_size(w, &aw, &ah);
    std::printf("   attached size before any EGL attach: %d x %d\n", aw, ah);
    check(aw == 0 && ah == 0, "get_attached_size reports 0 x 0 until EGL attaches");

    // ── 5. Resize is what a client calls on every configure event ────────
    wl_egl_window_resize(w, 800, 600, 0, 0);
    check(w->width == 800 && w->height == 600, "wl_egl_window_resize updated the geometry");

    // A rejected resize, which is a real branch: upstream returns early on a
    // non-positive dimension rather than storing it, so the previous size must
    // survive. Same guard `create` uses.
    wl_egl_window_resize(w, 0, 600, 0, 0);
    check(w->width == 800 && w->height == 600, "…and a width of 0 is refused, not stored");

    wl_egl_window_destroy(w);
    check(true, "wl_egl_window_destroy");

    // ── 6. create rejects a degenerate size ──────────────────────────────
    check(wl_egl_window_create(nullptr, 0, 480) == nullptr,
          "wl_egl_window_create refuses a width of 0");

    // ── 7. The two halves agree on the linkage they share ────────────────
    // `wl_display_connect` comes from libwayland-client and is NOT in
    // libwayland-egl — the fork's CI asserts that separation on the library,
    // and this asserts the consumer side: both are reachable from one program,
    // which is the arrangement a real client is in.
    check(&wl_display_connect != nullptr,
          "libwayland-client is in the same program (wl_display_connect)");

    std::printf("\n%d check(s) failed\n", failures);
    return failures == 0 ? 0 : 1;
}

#else
int main() { return 0; }
#endif

// wayland-protocols, as a compositor would consume it.
//
// The packages ship the marshalling code wayland-scanner generates from
// upstream's XML. Three things can be wrong and none is a missing symbol:
//
//   1. THE HEADERS ARE THE PUBLIC INTERFACE. A consumer writes
//      `#include <xdg-shell-client-protocol.h>`, so the generated directory
//      has to be EXPOSED rather than build-private. This file compiling is the
//      first assertion, and freedesktop.wayland had exactly this bug once —
//      masked locally by a header the SubOS happened to carry.
//
//   2. THE INTERFACE TABLES MUST LINK. A header-only package sails past
//      compilation; `xdg_wm_base_interface` is a `wl_interface` OBJECT in the
//      generated .c, so reading it proves the .c files were compiled.
//
//   3. TWO TIERS MUST COMPOSE. stable and staging are separate packages
//      precisely so they can be used together; that they do is what this
//      member is for. (stable + unstable is the pair that cannot — 13 shared
//      symbols — which is upstream's semantics rather than a defect.)
//
// Nothing here connects: no compositor and no display.

#ifdef __linux__

#include <wayland-client.h>
#include <wayland-server.h>

#include <xdg-shell-client-protocol.h>          // stable
#include <xdg-shell-server-protocol.h>
#include <linux-dmabuf-v1-client-protocol.h>    // stable — the GBM bridge
#include <cursor-shape-v1-client-protocol.h>    // staging

#include <cstdio>
#include <cstring>
#include <string>

namespace {

int failures = 0;

void check(bool ok, const char *what)
{
    std::printf("%-58s %s\n", what, ok ? "ok" : "FAILED");
    if (!ok) {
        ++failures;
    }
}

void report(const wl_interface &i, const char *want, const char *tier)
{
    std::printf("   %-8s %-28s version %d, %d method(s)\n",
                tier, i.name ? i.name : "(null)", i.version, i.method_count);
    check(i.name != nullptr && std::strcmp(i.name, want) == 0,
          (std::string(tier) + " " + want + " is linked in").c_str());
    check(i.method_count > 0, "…and it describes its requests");
}

} // namespace

int main()
{
    // ── 1. Both tiers linked, in one program ─────────────────────────────
    report(xdg_wm_base_interface,             "xdg_wm_base",             "stable");
    report(zwp_linux_dmabuf_v1_interface,     "zwp_linux_dmabuf_v1",     "stable");
    report(wp_cursor_shape_manager_v1_interface,
                                              "wp_cursor_shape_manager_v1", "staging");

    // ── 2. The server side was generated too ─────────────────────────────
    // `xdg_wm_base_send_ping` is a `static inline` only the SERVER header
    // defines. Client and server headers are separate scanner outputs and a
    // packaging mistake tends to lose one of them.
    check(reinterpret_cast<const void *>(&xdg_wm_base_send_ping) != nullptr,
          "the server-side headers were generated too");

    // ── 3. The library that marshals these is new enough ─────────────────
    // The generated code calls wl_proxy_marshal_flags, which arrived in
    // libwayland 1.19 — so the protocols and the client library are not from
    // different eras.
    check(reinterpret_cast<void *>(&wl_proxy_marshal_flags) != nullptr,
          "libwayland provides wl_proxy_marshal_flags");
    check(reinterpret_cast<void *>(&wl_display_create) != nullptr,
          "libwayland-server is linked for the compositor side");

    // ── 4. The GBM bridge protocol is the stable one ─────────────────────
    // linux-dmabuf is how a compositor hands a gbm_bo to a client, so it is
    // the protocol that ties this package to compat.libgbm. It lives in
    // stable/ upstream; the unstable spelling is one of the three this index
    // deliberately does not ship.
    check(zwp_linux_dmabuf_v1_interface.version >= 4,
          "linux-dmabuf is the stable v4+ interface, not the unstable spelling");

    std::printf("\n%d check(s) failed\n", failures);
    return failures == 0 ? 0 : 1;
}

// ── 1.49.1: the enum headers upstream installs ───────────────────────────────
//
// `wayland-scanner enum-header` output, which this fork did not generate before
// 1.49.1. wlroots 0.20 includes these from TEN of its PUBLIC headers, so a
// consumer of wlroots writing the ordinary `#include <wlr/...>` needs them on
// the include path — which is why they belong to THIS package rather than to
// wlroots.
//
// The enum header carries only the protocol's enums: no interface symbols and
