// The module wrappers, used the way a consumer would.
//
// The claim they make is narrow and testable: `import freedesktop.wayland.client;` gives
// you the same entities `#include <wayland-client.h>` does, spelled the same
// way. So this file includes NOTHING from wayland — no header — and still
// calls the stock API. If an export were missing, this would not compile; if a
// name had been renamed or wrapped, it would not compile either.
//
// tests/wayland.cpp is the header-based sibling. Both must pass: the module
// layer is an addition, not a replacement.

#ifdef __linux__

#include <cstdio>
#include <string>
#include <vector>

import freedesktop.wayland.client;
import freedesktop.wayland.server;
import freedesktop.wayland.util;

namespace {

int failures = 0;

void check(bool ok, const char *what)
{
    std::printf("%-58s %s\n", what, ok ? "ok" : "FAILED");
    if (!ok) ++failures;
}

// A node linked through wl_list, the shape every wayland consumer writes.
struct listener_node {
    int id;
    wl_list link;
};

} // namespace

int main()
{
    // ── 1. Client entities, with no #include anywhere ────────────────────
    {
        wl_display *d = wl_display_connect("mcpp-no-such-compositor");
        check(d == nullptr, "wl_display_connect through the module returns NULL");

        // A protocol interface object: generated code, exported by the module.
        check(std::string(wl_registry_interface.name) == "wl_registry",
              "wl_registry_interface arrives through freedesktop.wayland.client");
        check(std::string(wl_compositor_interface.name) == "wl_compositor",
              "so does wl_compositor_interface");
    }

    // ── 2. Server entities ───────────────────────────────────────────────
    {
        wl_display *s = wl_display_create();
        check(s != nullptr, "wl_display_create through freedesktop.wayland.server");
        if (s != nullptr) {
            wl_event_loop *loop = wl_display_get_event_loop(s);
            check(loop != nullptr, "wl_display_get_event_loop returns a loop");
            wl_display_destroy(s);
        }
    }

    // ── 3. The macros, as entities ───────────────────────────────────────
    // These are the names a module cannot export as macros; freedesktop.wayland.util
    // carries them as a constant, a template and ranges. Exercised here in a
    // consumer rather than only in the package's own test.
    {
        wl_list head;
        head.prev = &head;
        head.next = &head;

        listener_node a{1, {}}, b{2, {}};
        for (listener_node *n : {&a, &b}) {
            wl_list *prev = head.prev;
            n->link.prev = prev; n->link.next = &head;
            prev->next = &n->link; head.prev = &n->link;
        }

        std::vector<int> seen;
        for (listener_node *n : wl_list_each<&listener_node::link>(&head)) {
            seen.push_back(n->id);
        }
        check(seen.size() == 2 && seen[0] == 1 && seen[1] == 2,
              "wl_list_each walks a consumer's own list type");

        check(wl_container_of<&listener_node::link>(&b.link) == &b,
              "wl_container_of recovers the containing object");

        check(WL_MARSHAL_FLAG_DESTROY == 1u,
              "WL_MARSHAL_FLAG_DESTROY keeps upstream's value");
    }

    // ⭐ 这八个函数在 mcpp4 之前根本够不着(`static inline` 无法从模块导出),
    // 而**没有任何测试调用过它们**,所以谁都没发现。缺口是从外面被一个最小
    // wlroots 合成器问出来的。下面每一行都是"再塌陷就编译不过"的探针。
    {
        // wayland-util.h 的定点数 —— 协议里每个亚像素坐标的载体
        check(wl_fixed_from_int(3) == 768, "wl_fixed_from_int");
        check(wl_fixed_to_double(wl_fixed_from_double(1.5)) == 1.5, "wl_fixed double 往返");
        check(wl_fixed_from_double(-1.5) == -384, "负数按上游 round() 舍入");

        // wayland-server-core.h 的 signal —— 每次 wlroots 挂监听都要它
        wl_signal sig{};
        wl_signal_init(&sig);
        check(sig.listener_list.next == &sig.listener_list, "wl_signal_init");
        wl_listener l{};
        l.notify = [](wl_listener *, void *) {};
        wl_signal_add(&sig, &l);
        check(wl_signal_get(&sig, l.notify) == &l, "wl_signal_add + wl_signal_get");
        wl_list_remove(&l.link);
    }

    std::printf("\n%d check(s) failed\n", failures);
    return failures == 0 ? 0 : 1;
}

#else

int main() { return 0; }

#endif

// compat.wayland — behavioral test, runnable with no compositor.
//
// Two seams, and the second is the one a compositor author depends on.
//
//   1. THE CLIENT LIBRARY, which the package puts on the link line itself.
//      `wl_display_connect` on a machine with no compositor must return NULL
//      cleanly -- that exercises the real library (it reads WAYLAND_DISPLAY,
//      builds a socket path and fails to connect) without needing a server.
//
//   2. THE LIBRARIES THE PACKAGE DELIBERATELY DOES NOT LINK. libwayland-server
//      is harvested into the farm but kept off `ldflags`, so a consumer reaches
//      it by adding `-lwayland-server` to its own build — which this member's
//      mcpp.toml does. If the farm ever stops carrying the server library, the
//      documented escape hatch silently stops working; this file is what turns
//      that into a link error here instead.

#ifdef __linux__

#include <wayland-client.h>
#include <wayland-server-core.h>

#include <dlfcn.h>

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>

namespace {

int failures = 0;

void check(bool ok, const char *what)
{
    std::printf("%-58s %s\n", what, ok ? "ok" : "FAILED");
    if (!ok) {
        ++failures;
    }
}

} // namespace

int main()
{
    // ── 1. Headers resolved from the flat include root ───────────────────
    check(WL_DISPLAY_ERROR_INVALID_OBJECT == 0,
          "wayland-client.h provides the core protocol enums");

    // ── 2. Both libraries are really linked ──────────────────────────────
    for (const char *sym : {"wl_display_connect", "wl_display_disconnect",
                            "wl_proxy_marshal", "wl_registry_interface"}) {
        check(::dlsym(RTLD_DEFAULT, sym) != nullptr,
              (std::string("libwayland-client exports ") + sym).c_str());
    }
    // This one comes from the farm via the consumer's own -lwayland-server,
    // not from anything this package puts on the link line.
    for (const char *sym : {"wl_display_create", "wl_display_destroy"}) {
        check(::dlsym(RTLD_DEFAULT, sym) != nullptr,
              (std::string("libwayland-server exports ") + sym).c_str());
    }

    // ── 3. Connecting with no compositor fails cleanly ───────────────────
    // Deliberately points at a socket that cannot exist, so the result does
    // not depend on whether the machine running the test has a session.
    ::setenv("WAYLAND_DISPLAY", "mcpp-no-such-compositor", 1);
    ::unsetenv("WAYLAND_SOCKET");
    wl_display *dpy = wl_display_connect(nullptr);
    std::printf("   wl_display_connect (no compositor) = %p\n", (void *)dpy);
    check(dpy == nullptr,
          "wl_display_connect returns NULL rather than crashing");
    if (dpy != nullptr) {
        wl_display_disconnect(dpy);
    }

    // ── 4. The server library can actually build a display ───────────────
    // No socket is bound, so this needs no privileges and no session; it is
    // the cheapest proof that libwayland-server is functional and not merely
    // present.
    wl_display *server = wl_display_create();
    std::printf("   wl_display_create = %p\n", (void *)server);
    check(server != nullptr, "wl_display_create succeeds (server library live)");
    if (server != nullptr) {
        wl_display_destroy(server);
    }

    std::printf("\n%d check(s) failed\n", failures);
    return failures == 0 ? 0 : 1;
}

#else

int main()
{
    return 0;
}

#endif

// ws_features_test.cpp — asserts compat.websocket's `server` and `zlib`
// features, enabled through the member's dependency declaration.
//
//   * `server`: an ix::WebSocketServer runs inside the test process on
//     loopback and echoes every message; the client's round-trips go through
//     the REAL server class (the sibling member tests/examples/websocket uses
//     a hand-written raw-socket echo server precisely so the zero-dep client
//     is tested against something independent — here the point is the opposite:
//     prove the compiled-in server works).
//   * `zlib`: the client enables per-message-deflate. A highly-compressible
//     payload must come back as a message whose str is the full payload but
//     whose wireSize is the COMPRESSED frame bytes (the transport delivers
//     str = decompressed content and wireSize = raw wire payload), which is
//     how a compression round-trip is observable without sniffing the socket.
//
// No network access is required; everything stays on 127.0.0.1.

#include <ixwebsocket/IXConnectionState.h>
#include <ixwebsocket/IXNetSystem.h>
#include <ixwebsocket/IXWebSocket.h>
#include <ixwebsocket/IXWebSocketMessage.h>
#include <ixwebsocket/IXWebSocketServer.h>

#include <chrono>
#include <condition_variable>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <mutex>
#include <string>
#include <thread>
#include <vector>

// Raw sockets only for find_free_port() (a fixed test port would collide on
// shared CI runners; port 0 is the race-free way to ask the OS).
#ifdef _WIN32
#include <winsock2.h>
#include <ws2tcpip.h>
using SockType = SOCKET;
constexpr SockType kInvalidSocket = INVALID_SOCKET;
#else
#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <unistd.h>
using SockType = int;
constexpr SockType kInvalidSocket = -1;
#endif

namespace
{

int g_failures = 0;

void check(bool ok, const std::string& what)
{
    if (ok)
    {
        std::cout << "  ok: " << what << "\n";
    }
    else
    {
        std::cout << "  FAIL: " << what << "\n";
        ++g_failures;
    }
}

int find_free_port()
{
#ifdef _WIN32
    WSADATA wsa;
    WSAStartup(MAKEWORD(2, 2), &wsa);
#endif
    SockType s = socket(AF_INET, SOCK_STREAM, 0);
    if (s == kInvalidSocket) return -1;
    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    addr.sin_port = 0;
    if (bind(s, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) != 0)
    {
#ifdef _WIN32
        closesocket(s);
#else
        ::close(s);
#endif
        return -1;
    }
#ifdef _WIN32
    int len = sizeof(addr);
#else
    socklen_t len = sizeof(addr);
#endif
    if (getsockname(s, reinterpret_cast<sockaddr*>(&addr), &len) != 0)
    {
#ifdef _WIN32
        closesocket(s);
#else
        ::close(s);
#endif
        return -1;
    }
    int port = ntohs(addr.sin_port);
#ifdef _WIN32
    closesocket(s);
#else
    ::close(s);
#endif
    return port;
}

// ── Client-side message collector ──────────────────────────────────────────

struct RecvMsg
{
    ix::WebSocketMessageType type;
    std::string str;
    bool binary;
    size_t wireSize;
};

class Collector
{
public:
    void add(const ix::WebSocketMessagePtr& msg)
    {
        std::lock_guard<std::mutex> lk(m_);
        msgs_.push_back(RecvMsg{msg->type, msg->str, msg->binary, msg->wireSize});
        cv_.notify_all();
    }

    template <typename Pred>
    bool wait_for(Pred pred, int timeout_ms)
    {
        std::unique_lock<std::mutex> lk(m_);
        return cv_.wait_for(lk, std::chrono::milliseconds(timeout_ms), [&] { return pred(msgs_); });
    }

private:
    std::mutex m_;
    std::condition_variable cv_;
    std::vector<RecvMsg> msgs_;
};

} // namespace

int main()
{
    std::cout << std::unitbuf;

    bool netOk = ix::initNetSystem();
    check(netOk, "ix::initNetSystem()");

    int port = find_free_port();
    check(port > 0, "found a free loopback port");
    if (port <= 0)
    {
        ix::uninitNetSystem();
        return 1;
    }

    // The `server` feature: a real ix::WebSocketServer.
    ix::WebSocketServer server(port, "127.0.0.1");
    server.setOnClientMessageCallback(
        [](std::shared_ptr<ix::ConnectionState> /*state*/,
           ix::WebSocket& ws,
           const ix::WebSocketMessagePtr& msg)
        {
            if (msg->type == ix::WebSocketMessageType::Message)
            {
                if (msg->binary) ws.sendBinary(msg->str);
                else ws.sendText(msg->str);
            }
        });
    check(server.listenAndStart(), "ix::WebSocketServer listenAndStart()");

    Collector collector;
    ix::WebSocket ws;
    ws.setUrl("ws://127.0.0.1:" + std::to_string(port) + "/");
    ws.enablePerMessageDeflate();
    ws.setOnMessageCallback([&](const ix::WebSocketMessagePtr& msg) { collector.add(msg); });
    ws.start();

    check(collector.wait_for(
              [](const std::vector<RecvMsg>& v) {
                  for (const auto& m : v)
                      if (m.type == ix::WebSocketMessageType::Open) return true;
                  return false;
              },
              5000),
          "client opened against ix::WebSocketServer");

    // Text round-trip through the real server.
    ws.sendText("hello, real server!");
    check(collector.wait_for(
              [](const std::vector<RecvMsg>& v) {
                  for (const auto& m : v)
                      if (m.type == ix::WebSocketMessageType::Message &&
                          m.str == "hello, real server!" && !m.binary)
                          return true;
                  return false;
              },
              5000),
          "text message echoed by ix::WebSocketServer");

    // Binary round-trip through the real server.
    std::string bin("\x00\x01\xfe\xff\x80\x01binary", 10);
    ws.sendBinary(bin);
    check(collector.wait_for(
              [&](const std::vector<RecvMsg>& v) {
                  for (const auto& m : v)
                      if (m.type == ix::WebSocketMessageType::Message && m.str == bin && m.binary)
                          return true;
                  return false;
              },
              5000),
          "binary message echoed by ix::WebSocketServer");

    // The `zlib` feature: per-message-deflate must actually compress on the
    // wire. 64 KiB of a repeated byte compresses to a few hundred bytes; the
    // client delivers the FULL decompressed str but reports wireSize = the raw
    // (compressed) frame payload, so the ratio is observable.
    const size_t kBig = 65536;
    ws.sendText(std::string(kBig, 'a'));
    size_t compressedWire = 0;
    bool gotBig = collector.wait_for(
        [&](const std::vector<RecvMsg>& v) {
            for (const auto& m : v)
                if (m.type == ix::WebSocketMessageType::Message && m.str.size() == kBig &&
                    !m.binary)
                {
                    compressedWire = m.wireSize;
                    return true;
                }
            return false;
        },
        5000);
    check(gotBig, "64 KiB compressible message round-tripped");
    if (gotBig)
    {
        check(compressedWire < 1024,
              "per-message-deflate compressed the wire (wireSize=" + std::to_string(compressedWire) +
                  " << 65536)");
    }

    ws.stop();
    server.stop();
    ix::uninitNetSystem();

    if (g_failures == 0)
    {
        std::cout << "ALL WEBSOCKET-FEATURES ASSERTIONS PASSED\n";
        return 0;
    }
    std::cout << g_failures << " ASSERTION(S) FAILED\n";
    return 1;
}

