// ws_test.cpp — self-contained WebSocket client test for compat.websocket.
//
// IXWebSocket is a pure client here (the descriptor builds the client TUs
// only), so this test brings its OWN minimal RFC 6455 echo server, built on
// raw sockets, and drives the ix::WebSocket client against 127.0.0.1:0. That
// exercises the real wire behaviors the client must implement — the HTTP
// upgrade handshake (the client validates Sec-WebSocket-Accept), client-side
// masking, fragmentation (the server replies with a fragmented message and the
// client must reassemble it), ping/pong in both directions, and the closing
// handshake. No network access and no server process are required: everything
// stays inside one process on the loopback interface.
//
// The server is intentionally independent of the library under test: it
// computes Sec-WebSocket-Accept with its own SHA-1 + base64 and implements the
// framing itself, so a client bug in any of those areas fails the assertions
// below rather than being hidden by shared code.

#include <ixwebsocket/IXNetSystem.h>
#include <ixwebsocket/IXWebSocket.h>
#include <ixwebsocket/IXWebSocketMessage.h>

#include <atomic>
#include <chrono>
#include <condition_variable>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <mutex>
#include <string>
#include <thread>
#include <vector>

namespace
{

int g_failures = 0;

void check(bool ok, const std::string& what)
{
    if (ok)
    {
        std::cout << "  ok: " << what << "\n";
    }
    else
    {
        std::cout << "  FAIL: " << what << "\n";
        ++g_failures;
    }
}

// ── SHA-1 and base64 (for Sec-WebSocket-Accept) ────────────────────────────
// Compact reference implementations, independent of the library under test.

std::string base64_encode(const std::string& in)
{
    static const char tbl[] =
        "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    std::string out;
    unsigned val = 0;
    int valb = -6;
    for (unsigned char c : in)
    {
        val = (val << 8) | c;
        valb += 8;
        while (valb >= 0)
        {
            out.push_back(tbl[(val >> valb) & 0x3F]);
            valb -= 6;
        }
    }
    if (valb > -6) out.push_back(tbl[((val << 8) >> (valb + 8)) & 0x3F]);
    while (out.size() % 4) out.push_back('=');
    return out;
}

std::string sha1_binary(const std::string& msg)
{
    uint32_t h0 = 0x67452301, h1 = 0xEFCDAB89, h2 = 0x98BADCFE, h3 = 0x10325476,
             h4 = 0xC3D2E1F0;
    uint64_t bitlen = static_cast<uint64_t>(msg.size()) * 8;
    std::string m = msg;
    m.push_back(static_cast<char>(0x80));
    while (m.size() % 64 != 56) m.push_back('\0');
    for (int i = 7; i >= 0; --i)
        m.push_back(static_cast<char>((bitlen >> (i * 8)) & 0xFF));

    for (size_t i = 0; i < m.size(); i += 64)
    {
        uint32_t w[80];
        for (int j = 0; j < 16; ++j)
            w[j] = (static_cast<uint32_t>(static_cast<unsigned char>(m[i + j * 4])) << 24) |
                   (static_cast<uint32_t>(static_cast<unsigned char>(m[i + j * 4 + 1])) << 16) |
                   (static_cast<uint32_t>(static_cast<unsigned char>(m[i + j * 4 + 2])) << 8) |
                   (static_cast<uint32_t>(static_cast<unsigned char>(m[i + j * 4 + 3])));
        for (int j = 16; j < 80; ++j)
        {
            uint32_t x = w[j - 3] ^ w[j - 8] ^ w[j - 14] ^ w[j - 16];
            w[j] = (x << 1) | (x >> 31);
        }
        uint32_t a = h0, b = h1, c = h2, d = h3, e = h4;
        for (int j = 0; j < 80; ++j)
        {
            uint32_t f, k;
            if (j < 20)
            {
                f = (b & c) | ((~b) & d);
                k = 0x5A827999;
            }
            else if (j < 40)
            {
                f = b ^ c ^ d;
                k = 0x6ED9EBA1;
            }
            else if (j < 60)
            {
                f = (b & c) | (b & d) | (c & d);
                k = 0x8F1BBCDC;
            }
            else
            {
                f = b ^ c ^ d;
                k = 0xCA62C1D6;
            }
            uint32_t tmp = ((a << 5) | (a >> 27)) + f + e + k + w[j];
            e = d;
            d = c;
            c = (b << 30) | (b >> 2);
            b = a;
            a = tmp;
        }
        h0 += a;
        h1 += b;
        h2 += c;
        h3 += d;
        h4 += e;
    }
    std::string out(20, '\0');
    const uint32_t hs[5] = {h0, h1, h2, h3, h4};
    for (int i = 0; i < 5; ++i)
        for (int j = 0; j < 4; ++j)
            out[i * 4 + j] = static_cast<char>((hs[i] >> ((3 - j) * 8)) & 0xFF);
    return out;
}

// ── Platform socket abstraction ────────────────────────────────────────────

#ifdef _WIN32
#include <winsock2.h>
#include <ws2tcpip.h>
using SockType = SOCKET;
constexpr SockType kInvalidSocket = INVALID_SOCKET;
using AddrLenType = int;
#else
#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <unistd.h>
using SockType = int;
constexpr SockType kInvalidSocket = -1;
using AddrLenType = socklen_t;
#endif

void init_sockets()
{
#ifdef _WIN32
    WSADATA wsa;
    WSAStartup(MAKEWORD(2, 2), &wsa);
#endif
}

void close_socket(SockType s)
{
#ifdef _WIN32
    closesocket(s);
#else
    ::close(s);
#endif
}

// Safety net: any read that stalls this long makes the server thread return so
// the test fails cleanly instead of hanging the process (and, on CI, a runner).
void set_recv_timeout(SockType s, int ms)
{
#ifdef _WIN32
    DWORD t = static_cast<DWORD>(ms);
    setsockopt(s, SOL_SOCKET, SO_RCVTIMEO, reinterpret_cast<const char*>(&t), sizeof(t));
#else
    timeval tv{};
    tv.tv_sec = ms / 1000;
    tv.tv_usec = (ms % 1000) * 1000;
    setsockopt(s, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
#endif
}

// ── Minimal RFC 6455 echo server ───────────────────────────────────────────

class EchoServer
{
public:
    ~EchoServer()
    {
        if (client != kInvalidSocket) close_socket(client);
        if (listener != kInvalidSocket) close_socket(listener);
        if (thread.joinable()) thread.join();
    }

    bool start()
    {
        init_sockets();
        listener = socket(AF_INET, SOCK_STREAM, 0);
        if (listener == kInvalidSocket) return false;
        int one = 1;
#ifdef _WIN32
        setsockopt(listener, SOL_SOCKET, SO_REUSEADDR,
                   reinterpret_cast<const char*>(&one), sizeof(one));
#else
        setsockopt(listener, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));
#endif
        sockaddr_in addr{};
        addr.sin_family = AF_INET;
        addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        addr.sin_port = 0; // ephemeral
        if (bind(listener, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) != 0) return false;
        AddrLenType alen = sizeof(addr);
        getsockname(listener, reinterpret_cast<sockaddr*>(&addr), &alen);
        port = ntohs(addr.sin_port);
        if (listen(listener, 1) != 0) return false;
        thread = std::thread([this] { run(); });
        return true;
    }

    int port = 0;
    std::atomic<bool> server_saw_masked{false};
    std::atomic<bool> server_saw_pong{false};
    std::atomic<bool> server_saw_close{false};

private:
    SockType listener = kInvalidSocket;
    SockType client = kInvalidSocket;
    std::thread thread;

    // Receive exactly n bytes; false on timeout/error/disconnect.
    bool recv_n(char* buf, size_t n)
    {
        size_t got = 0;
        while (got < n)
        {
            int r = recv(client, buf + got, static_cast<int>(n - got), 0);
            if (r <= 0) return false;
            got += static_cast<size_t>(r);
        }
        return true;
    }

    std::string lower(std::string s)
    {
        for (char& c : s)
            if (c >= 'A' && c <= 'Z') c = static_cast<char>(c + ('a' - 'A'));
        return s;
    }

    bool handshake()
    {
        std::string req;
        char tmp[1024];
        while (req.find("\r\n\r\n") == std::string::npos)
        {
            int r = recv(client, tmp, sizeof(tmp), 0);
            if (r <= 0) return false;
            req.append(tmp, static_cast<size_t>(r));
            if (req.size() > 65536) return false;
        }
        std::string key;
        std::string rest = req;
        for (;;)
        {
            size_t eol = rest.find("\r\n");
            if (eol == std::string::npos) break;
            std::string line = rest.substr(0, eol);
            rest = rest.substr(eol + 2);
            size_t colon = line.find(':');
            if (colon == std::string::npos) continue;
            std::string name = lower(line.substr(0, colon));
            std::string value = line.substr(colon + 1);
            size_t b = value.find_first_not_of(" \t");
            size_t e = value.find_last_not_of(" \t");
            value = (b == std::string::npos) ? std::string() : value.substr(b, e - b + 1);
            if (name == "sec-websocket-key") key = value;
        }
        if (key.empty()) return false;

        const std::string guid = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";
        std::string accept = base64_encode(sha1_binary(key + guid));

        std::string resp = "HTTP/1.1 101 Switching Protocols\r\n"
                           "Upgrade: websocket\r\n"
                           "Connection: Upgrade\r\n"
                           "Sec-WebSocket-Accept: " + accept + "\r\n"
                           "\r\n";
        size_t off = 0;
        while (off < resp.size())
        {
            int w = send(client, resp.data() + off, static_cast<int>(resp.size() - off), 0);
            if (w <= 0) return false;
            off += static_cast<size_t>(w);
        }
        return true;
    }

    bool send_frame(uint8_t opcode, const std::string& payload, bool fin = true)
    {
        // Server->client frames are NOT masked (RFC 6455 §5.1).
        std::string frame;
        frame.push_back(static_cast<char>((fin ? 0x80 : 0x00) | (opcode & 0x0F)));
        size_t n = payload.size();
        if (n < 126)
        {
            frame.push_back(static_cast<char>(n));
        }
        else if (n <= 0xFFFF)
        {
            frame.push_back(static_cast<char>(126));
            frame.push_back(static_cast<char>((n >> 8) & 0xFF));
            frame.push_back(static_cast<char>(n & 0xFF));
        }
        else
        {
            frame.push_back(static_cast<char>(127));
            for (int i = 7; i >= 0; --i)
                frame.push_back(static_cast<char>((n >> (i * 8)) & 0xFF));
        }
        frame += payload;
        size_t off = 0;
        while (off < frame.size())
        {
            int w = send(client, frame.data() + off, static_cast<int>(frame.size() - off), 0);
            if (w <= 0) return false;
            off += static_cast<size_t>(w);
        }
        return true;
    }

    bool recv_frame(uint8_t& opcode, std::string& payload)
    {
        char hdr[2];
        if (!recv_n(hdr, 2)) return false;
        bool fin = (hdr[0] & 0x80) != 0;
        (void) fin;
        opcode = static_cast<uint8_t>(hdr[0] & 0x0F);
        bool masked = (hdr[1] & 0x80) != 0;
        if (masked) server_saw_masked = true;
        size_t len = static_cast<size_t>(hdr[1] & 0x7F);
        if (len == 126)
        {
            char ext[2];
            if (!recv_n(ext, 2)) return false;
            len = (static_cast<size_t>(static_cast<unsigned char>(ext[0])) << 8) |
                  static_cast<size_t>(static_cast<unsigned char>(ext[1]));
        }
        else if (len == 127)
        {
            char ext[8];
            if (!recv_n(ext, 8)) return false;
            len = 0;
            for (int i = 0; i < 8; ++i)
                len = (len << 8) | static_cast<size_t>(static_cast<unsigned char>(ext[i]));
        }
        char key[4] = {0, 0, 0, 0};
        if (masked && !recv_n(key, 4)) return false;
        payload.resize(len);
        if (len && !recv_n(&payload[0], len)) return false;
        if (masked)
            for (size_t i = 0; i < len; ++i)
                payload[i] = static_cast<char>(payload[i] ^ key[i % 4]);
        return true;
    }

    void run()
    {
        sockaddr_in peer{};
        AddrLenType plen = sizeof(peer);
        client = accept(listener, reinterpret_cast<sockaddr*>(&peer), &plen);
        if (client == kInvalidSocket) return;
        set_recv_timeout(client, 10000);
        if (!handshake()) return;

        for (;;)
        {
            uint8_t opcode = 0;
            std::string payload;
            if (!recv_frame(opcode, payload)) return;

            switch (opcode)
            {
                case 0x9: // ping -> pong
                    if (!send_frame(0xA, payload)) return;
                    break;
                case 0xA: // pong (answer to our ping)
                    server_saw_pong = true;
                    break;
                case 0x8: // close -> echo close code, then shut down
                {
                    server_saw_close = true;
                    std::string close_payload = payload;
                    if (close_payload.size() < 2) close_payload = std::string("\x03\xe8", 2); // 1000
                    if (!send_frame(0x8, close_payload)) return;
                    return;
                }
                case 0x1: // text
                case 0x2: // binary
                {
                    if (payload == "FRAG")
                    {
                        // Reply with a fragmented text message.
                        if (!send_frame(0x1, "fragA-", false)) return;
                        if (!send_frame(0x0, "fragB-", false)) return;
                        if (!send_frame(0x0, "fragC!", true)) return;
                    }
                    else if (payload == "PINGME")
                    {
                        // Ask the client to answer a ping with a pong.
                        if (!send_frame(0x9, "server-ping", true)) return;
                    }
                    else
                    {
                        if (!send_frame(opcode, payload, true)) return;
                    }
                    break;
                }
                default:
                    // continuation frames and anything else: ignore.
                    break;
            }
        }
    }
};

// ── Client-side message collector ──────────────────────────────────────────

struct RecvMsg
{
    ix::WebSocketMessageType type;
    std::string str;
    bool binary;
};

class Collector
{
public:
    void add(const ix::WebSocketMessagePtr& msg)
    {
        std::lock_guard<std::mutex> lk(m_);
        msgs_.push_back(RecvMsg{msg->type, msg->str, msg->binary});
        cv_.notify_all();
    }

    // Wait up to timeout_ms for a predicate over the collected messages.
    template <typename Pred>
    bool wait_for(Pred pred, int timeout_ms)
    {
        std::unique_lock<std::mutex> lk(m_);
        return cv_.wait_for(lk, std::chrono::milliseconds(timeout_ms), [&] { return pred(msgs_); });
    }

    bool has_type(ix::WebSocketMessageType t) const
    {
        std::lock_guard<std::mutex> lk(m_);
        for (const auto& m : msgs_)
            if (m.type == t) return true;
        return false;
    }

private:
    mutable std::mutex m_;
    std::condition_variable cv_;
    std::vector<RecvMsg> msgs_;
};

} // namespace

int main()
{
    // Unbuffered: `mcpp test` runs this piped, and a hang without visible
    // progress is indistinguishable from a slow pass otherwise.
    std::cout << std::unitbuf;

    EchoServer server;
    if (!server.start())
    {
        std::cout << "FAIL: could not start echo server\n";
        return 1;
    }
    std::cout << "server listening on 127.0.0.1:" << server.port << "\n";

    bool netOk = ix::initNetSystem();
    check(netOk, "ix::initNetSystem()");

    Collector collector;
    ix::WebSocket ws;
    ws.setUrl("ws://127.0.0.1:" + std::to_string(server.port) + "/");
    ws.setOnMessageCallback([&](const ix::WebSocketMessagePtr& msg) { collector.add(msg); });
    ws.start();

    // 1. Handshake: the client must validate our Sec-WebSocket-Accept and open.
    check(collector.wait_for(
              [](const std::vector<RecvMsg>& v) {
                  for (const auto& m : v)
                      if (m.type == ix::WebSocketMessageType::Open) return true;
                  return false;
              },
              5000),
          "client opened after HTTP upgrade handshake");

    // 2. Text echo — by the time the server echoes, it has seen the client's
    //    masked frames (RFC 6455 §5.1 requires client->server masking).
    ws.sendText("hello, ws!");
    check(collector.wait_for(
              [](const std::vector<RecvMsg>& v) {
                  for (const auto& m : v)
                      if (m.type == ix::WebSocketMessageType::Message && m.str == "hello, ws!" &&
                          !m.binary)
                          return true;
                  return false;
              },
              5000),
          "text message echoed back");
    check(server.server_saw_masked.load(), "client frames arrive masked");

    // 3. Binary echo (arbitrary bytes, not valid UTF-8).
    std::string bin("\x00\x01\x02\xfe\xff\x80hello", 9);
    ws.sendBinary(bin);
    check(collector.wait_for(
              [&](const std::vector<RecvMsg>& v) {
                  for (const auto& m : v)
                      if (m.type == ix::WebSocketMessageType::Message && m.str == bin && m.binary)
                          return true;
                  return false;
              },
              5000),
          "binary message echoed back byte-for-byte");

    // 4. Client ping -> server pong -> client surfaces the Pong message.
    ws.ping("ping-payload");
    check(collector.wait_for(
              [](const std::vector<RecvMsg>& v) {
                  for (const auto& m : v)
                      if (m.type == ix::WebSocketMessageType::Pong && m.str == "ping-payload")
                          return true;
                  return false;
              },
              5000),
          "ping/pong round-trip (client-initiated)");

    // 5. Server ping -> client auto-pong (enablePong default is on).
    ws.sendText("PINGME");
    {
        auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(5);
        while (!server.server_saw_pong.load() && std::chrono::steady_clock::now() < deadline)
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }
    check(server.server_saw_pong.load(), "client auto-answered a server ping with a pong");

    // 6. Fragmentation: server replies with a fragmented text message, the
    //    client must reassemble it into one Message (Fragment frames precede it).
    ws.sendText("FRAG");
    check(collector.wait_for(
              [&](const std::vector<RecvMsg>& v) {
                  bool sawFragment = false;
                  for (const auto& m : v)
                  {
                      if (m.type == ix::WebSocketMessageType::Fragment) sawFragment = true;
                      if (m.type == ix::WebSocketMessageType::Message && m.str == "fragA-fragB-fragC!")
                          return true;
                  }
                  (void) sawFragment;
                  return false;
              },
              5000),
          "fragmented server message reassembled by the client");
    check(collector.has_type(ix::WebSocketMessageType::Fragment),
          "fragment frames surfaced before the reassembled message");

    // 7. Close handshake: stop() initiates the close (via its internal
    //    close()), waits for the server's close reply and for the client thread
    //    to exit, and sets `_stop` so the run loop cannot fall into the
    //    automatic reconnection that a CLOSED state would otherwise trigger
    //    (IXWebSocket enables automatic reconnection by default). The Close
    //    message is delivered to the collector before stop() returns.
    ws.stop();
    check(collector.has_type(ix::WebSocketMessageType::Close),
          "closing handshake completed (client saw Close)");
    check(server.server_saw_close.load(), "server received the client's close frame");

    ix::uninitNetSystem();

    if (g_failures == 0)
    {
        std::cout << "ALL WEBSOCKET ASSERTIONS PASSED\n";
        return 0;
    }
    std::cout << g_failures << " ASSERTION(S) FAILED\n";
    return 1;
}

// Behavioral test: WIL's three families, each doing real work.
//
// A header-only package can fail in two ways a "does it link" test would miss:
// the headers might not compile under this toolchain at all (WIL is dense in
// __declspec, SAL annotations and intrinsics, and this index builds Windows
// with clang rather than cl.exe), and the RAII types might not actually release
// what they own. So the assertions observe SIDE EFFECTS — a handle that really
// closed, a COM refcount that really dropped — rather than just naming symbols.
#ifdef _WIN32

#include <wil/com.h>
#include <wil/resource.h>
#include <wil/result.h>

#include <windows.h>
#include <shobjidl.h>

#include <cassert>
#include <utility>

namespace {

// Returns whether the handle value still names a live kernel object in this
// process. This is how "the wrapper really closed it" gets observed.
bool handle_is_live(HANDLE h) {
    DWORD flags = 0;
    return ::GetHandleInformation(h, &flags) != FALSE;
}

HRESULT succeeds() { return S_OK; }
HRESULT fails() { return E_ACCESSDENIED; }

HRESULT propagates_failure() {
    RETURN_IF_FAILED(succeeds());
    RETURN_IF_FAILED(fails());     // must return here
    return S_FALSE;                // unreachable
}

}  // namespace

int main() {
    // ── wil::unique_handle: ownership, move, and actual closure ──────────
    HANDLE raw = ::CreateEventW(nullptr, TRUE, FALSE, nullptr);
    assert(raw != nullptr && handle_is_live(raw));
    {
        wil::unique_handle owner(raw);
        assert(owner.get() == raw);

        wil::unique_handle moved = std::move(owner);
        assert(!owner && moved.get() == raw);   // move really transferred
        assert(handle_is_live(raw));            // and did not close on the way
    }
    assert(!handle_is_live(raw) && "unique_handle did not close the handle");

    // release() must hand ownership BACK, i.e. not close it
    HANDLE raw2 = ::CreateEventW(nullptr, TRUE, FALSE, nullptr);
    assert(raw2 != nullptr);
    {
        wil::unique_handle owner(raw2);
        HANDLE released = owner.release();
        assert(released == raw2 && !owner);
    }
    assert(handle_is_live(raw2) && "release() must not close");
    ::CloseHandle(raw2);

    // ── wil::unique_hlocal_string over a LocalAlloc'd buffer ─────────────
    {
        auto* buffer = static_cast<PWSTR>(::LocalAlloc(LPTR, 8 * sizeof(wchar_t)));
        assert(buffer != nullptr);
        wcscpy_s(buffer, 8, L"wil");
        wil::unique_hlocal_string owned(buffer);
        assert(owned && wcscmp(owned.get(), L"wil") == 0);
    }  // LocalFree runs here; nothing observable, but it must compile and not crash

    // ── wil::com_ptr against a real COM object ───────────────────────────
    {
        const auto uninit = wil::CoInitializeEx(COINIT_APARTMENTTHREADED);

        wil::com_ptr<IShellLinkW> link;
        const HRESULT hr = ::CoCreateInstance(CLSID_ShellLink, nullptr, CLSCTX_INPROC_SERVER,
                                              IID_PPV_ARGS(&link));
        assert(SUCCEEDED(hr) && link);

        // query() crosses an interface — the classic com_ptr operation.
        auto persist = link.query<IPersistFile>();
        assert(persist);

        // A raw AddRef/Release pair around a copy proves the smart pointer is
        // actually counting, not just holding.
        link->AddRef();
        const ULONG after_addref = link->AddRef();
        const ULONG after_release = link->Release();
        assert(after_release == after_addref - 1);
        link->Release();

        wil::com_ptr<IShellLinkW> copy = link;
        assert(copy.get() == link.get());
        copy.reset();
        assert(!copy && link);
    }

    // ── HRESULT macros: the error model, not just the spelling ───────────
    assert(propagates_failure() == E_ACCESSDENIED);

    bool threw = false;
    try {
        THROW_IF_FAILED(fails());
    } catch (const wil::ResultException& e) {
        threw = true;
        assert(e.GetErrorCode() == E_ACCESSDENIED);
    }
    assert(threw && "THROW_IF_FAILED did not throw on a failed HRESULT");

    // …and must NOT throw on success.
    THROW_IF_FAILED(succeeds());

    return 0;
}

#else

int main() { return 0; }   // WIL is Windows-only; nothing to assert here.

#endif

// wlroots — what can be asserted without a seat, a GPU or a compositor.
//
// WHAT THIS TEST IS FOR
//
// A compositor library is mostly untestable in CI: creating a backend wants a
// DRM master, a libseat session and an input device, and none of a runner's
// three exist. So the temptation is to assert that it linked, which is worth
// almost nothing — a package can link and still have compiled none of the
// files a consumer needs (this index has measured exactly that).
//
// Everything below is chosen to be an INTERMEDIATE QUANTITY: a value the
// library computes on its own, from data it carries, with no device involved.
// Each one names a specific generator in build.mcpp, so a failure says which
// one broke rather than "wlroots is broken":
//
//   version           → include/wlr/version.h
//   WLR_HAS_*         → include/wlr/config.h, and the feature set behind it
//   the PNP table     → pnpids.c, from the pinned hwdata
//   the box maths     → util/box.c, i.e. that ordinary sources compiled
//   the module itself → 986 `using ::` declarations that must all resolve
//   `namespace_`      → the C++ keyword-member rewrite
//
// ⚠️ NO extern "C" WRAPPER, and that is the point. wlroots' public headers
// contain not one `extern "C"` block, and two of them are not even valid C++
// (C99 `[static N]` array parameters). A C++ consumer cannot include them at
// all. `import wlroots;` is not a nicety here — it is the only way in.

#ifdef __linux__

// ⚠️ THE MODULE CANNOT CARRY MACROS, so `WLR_HAS_*` comes from the header.
// Macros are preprocessor entities and nothing exports them.
//
// ⚠️ AND ONLY A MACRO-ONLY HEADER MAY BE INCLUDED ALONGSIDE THE MODULE.
// `<wlr/config.h>` is nothing but `#define`s, so it is safe. `<wlr/version.h>`
// is not: it DECLARES wlr_version_get_major and has no `extern "C"` of its
// own, so including it here gives those three names C++ linkage while the
// module's have C linkage — two different entities, and the link fails with
//
//     undefined reference to `wlr_version_get_major()'
//
// naming a function the library plainly contains. The parentheses in that
// message are the tell: a mangled name, i.e. the wrong one. Take declarations
// from the module and macros from the header, never the same name from both.
#include <wlr/config.h>

import wlroots;

// `get_pnp_manufacturer` is INTERNAL to the DRM backend — declared in the
// private `backend/drm/util.h`, so it is not in the module and not in any
// installed header. Declared here because the generated table behind it is
// the one thing in this package whose failure looks exactly like success.
// `const char code[static 3]` and `const char *` are the same parameter after
// array-to-pointer decay, so this declaration is ABI-identical to upstream's.
extern "C" const char *get_pnp_manufacturer(const char *code);

#include <cstdio>
#include <cstring>

namespace {

int failures = 0;

void check(bool ok, const char *what)
{
    std::printf("%-62s %s\n", what, ok ? "ok" : "FAILED");
    if (!ok) {
        ++failures;
    }
}

} // namespace

int main()
{
    // ── 1. version.h was generated, and says what the manifest says ───────
    std::printf("   wlroots %d.%d.%d\n", wlr_version_get_major(),
                wlr_version_get_minor(), wlr_version_get_micro());
    check(wlr_version_get_major() == 0 && wlr_version_get_minor() == 20,
          "version.h reports 0.20, the version the manifest declares");

    // ── 2. config.h reports THIS build's features ────────────────────────
    // Not "some features are on" — the exact default set, so a feature that
    // silently stopped being compiled is a failure and not a shrug.
    std::printf("   drm=%d libinput=%d session=%d gles2=%d gbm=%d | "
                "x11=%d vulkan=%d xwayland=%d\n",
                WLR_HAS_DRM_BACKEND, WLR_HAS_LIBINPUT_BACKEND, WLR_HAS_SESSION,
                WLR_HAS_GLES2_RENDERER, WLR_HAS_GBM_ALLOCATOR,
                WLR_HAS_X11_BACKEND, WLR_HAS_VULKAN_RENDERER, WLR_HAS_XWAYLAND);
    check(WLR_HAS_DRM_BACKEND && WLR_HAS_LIBINPUT_BACKEND && WLR_HAS_SESSION
              && WLR_HAS_GLES2_RENDERER && WLR_HAS_GBM_ALLOCATOR,
          "the five default features are all on");
    check(!WLR_HAS_X11_BACKEND && !WLR_HAS_VULKAN_RENDERER && !WLR_HAS_XWAYLAND,
          "…and X11, Vulkan and Xwayland are off, as the manifest says");

    // ── 3. util/box.c: ordinary sources really were compiled ─────────────
    // Pure arithmetic on two rectangles, no device. If the package had linked
    // without compiling anything this would not resolve.
    wlr_box a{.x = 0, .y = 0, .width = 100, .height = 50};
    wlr_box b{.x = 60, .y = 20, .width = 100, .height = 50};
    wlr_box out{};
    const bool overlap = wlr_box_intersection(&out, &a, &b);
    std::printf("   intersection = %d,%d %dx%d\n", out.x, out.y, out.width, out.height);
    check(overlap && out.x == 60 && out.y == 20 && out.width == 40 && out.height == 30,
          "wlr_box_intersection computes the overlap");

    check(wlr_box_contains_point(&a, 10, 10) && !wlr_box_contains_point(&a, 10, 90),
          "wlr_box_contains_point agrees with the box it was given");

    // ── 4. the scene graph allocates ─────────────────────────────────────
    // wlr_scene_create needs no backend — it is the one non-trivial object a
    // test can build. It also proves types/scene/*.c compiled.
    wlr_scene *scene = wlr_scene_create();
    check(scene != nullptr, "wlr_scene_create without a backend");
    if (scene != nullptr) {
        const float colour[4] = {1.0f, 0.0f, 0.0f, 1.0f};
        wlr_scene_rect *rect = wlr_scene_rect_create(&scene->tree, 32, 16, colour);
        check(rect != nullptr, "…and a rect in it");
        // wlr_scene_rect_set_color is one of the five declarations that use
        // C99 `[static 4]`. Calling it is what proves the rewritten header
        // declares the same function the library defines.
        if (rect != nullptr) {
            const float other[4] = {0.0f, 1.0f, 0.0f, 1.0f};
            wlr_scene_rect_set_color(rect, other);
            check(true, "…and wlr_scene_rect_set_color, whose C99 [static 4] was rewritten");
        }
        wlr_scene_node_destroy(&scene->tree.node);
    }

    // ── 5. the C++ keyword-member rewrite ────────────────────────────────
    // `struct wlr_layer_surface_v1` has a member C++ cannot name. The header
    // this build compiles against renames it under `#ifdef __cplusplus`, at
    // the same offset. Reading it through a null-object offset would be UB, so
    // this asserts on a real object's storage instead.
    wlr_layer_surface_v1 ls{};
    ls.namespace_ = const_cast<char *>("panel");
    check(std::strcmp(ls.namespace_, "panel") == 0,
          "wlr_layer_surface_v1::namespace_ is reachable from C++");

    // ── 6. the PNP table generated from the PINNED hwdata ────────────────
    // The failure this catches looks exactly like a passing build: upstream's
    // gen_pnpids.sh reads /usr/share/hwdata/pnp.ids off the BUILD MACHINE, so
    // the manufacturer a monitor reports would depend on where the package was
    // built. `get_pnp_manufacturer` is wlroots-internal rather than exported,
    // so it is reached through the DRM backend header's declaration.
    //
    // "ACR" is the id in the EDID of the Acer monitor freedesktop.libdisplay-
    // info tests against, which is where the expected string comes from.
    const char *acr = get_pnp_manufacturer("ACR");
    const char *del = get_pnp_manufacturer("DEL");
    // ⚠️ "JJJ", not an arbitrary byte triple. PNP_ID keeps only the LOW FIVE
    // BITS of each character, so "\x01\x02\x03" packs to the same key as "ABC"
    // and returns AboCom System Inc. — measured, and it is upstream's encoding
    // rather than a bug here. An id that is genuinely absent has to be one
    // whose 15-bit key no entry occupies; "JJJ" (key 10570) is one of them.
    const char *nope = get_pnp_manufacturer("JJJ");
    std::printf("   ACR=%s  DEL=%s  JJJ=%s\n", acr ? acr : "(null)",
                del ? del : "(null)", nope ? nope : "(null)");
    check(acr != nullptr && std::strstr(acr, "Acer") != nullptr,
          "the pinned pnp.ids resolved ACR to Acer");
    check(del != nullptr && std::strstr(del, "Dell") != nullptr, "…and DEL to Dell");
    check(nope == nullptr, "…and an unoccupied key returns NULL, not a neighbour");

    std::printf("\n%d check(s) failed\n", failures);
    return failures == 0 ? 0 : 1;
}

#else
int main() { return 0; }
#endif

// Behavioral test: the digests themselves, against upstream's own vectors.
//
// A hash package that links but computes a different value is worse than one
// that does not link at all — every caller downstream is content-addressing
// something. So the assertions here are known-answer tests taken verbatim from
// xxHash's `tests/sanity_test_vectors.h`, together with the buffer generator
// from `tests/sanity_test.c` that those vectors were computed over. Nothing is
// derived from running the code under test.
//
// The lengths cover every size branch XXH3 switches on (0, 1-3, 4-8, 9-16,
// 17-128, 129-240, >240) plus the multi-block path at 2048 and 4160, which is
// where a mis-selected SIMD variant or a byte-order slip would show up.
#include <xxhash.h>

#include <cassert>
#include <cstddef>
#include <cstdint>
#include <vector>

namespace {

// tests/sanity_test.c: fillTestBuffer(). "Its values must not be changed."
constexpr std::uint32_t kPrime32 = 2654435761U;
constexpr std::uint64_t kPrime64 = 11400714785074694797ULL;

std::vector<unsigned char> make_sanity_buffer(std::size_t len) {
    std::vector<unsigned char> buf(len);
    std::uint64_t gen = kPrime32;
    for (std::size_t i = 0; i < len; ++i) {
        buf[i] = static_cast<unsigned char>(gen >> 56);
        gen *= kPrime64;
    }
    return buf;
}

struct Case32 { std::uint32_t len; std::uint32_t seed; std::uint32_t expected; };
struct Case64 { std::uint32_t len; std::uint64_t seed; std::uint64_t expected; };
struct Case128 { std::uint32_t len; std::uint64_t lo; std::uint64_t hi; };

// XSUM_XXH32_testdata, seed 0.
constexpr Case32 kXXH32[] = {
    {    0, 0x00000000U, 0x02CC5D05U }, {    1, 0x00000000U, 0xCF65B03EU },
    {    2, 0x00000000U, 0x1151BEE4U }, {    3, 0x00000000U, 0xC23884F5U },
    {    4, 0x00000000U, 0xA9DE7CE9U }, {    8, 0x00000000U, 0xA3F6F44BU },
    {    9, 0x00000000U, 0xFFB82A24U }, {   16, 0x00000000U, 0x93BA3759U },
    {   17, 0x00000000U, 0x89FDC23EU }, {   64, 0x00000000U, 0x02E95DBBU },
    {  128, 0x00000000U, 0x0FD07B71U }, {  129, 0x00000000U, 0x68C9EC37U },
    {  222, 0x00000000U, 0x5BD11DBDU }, {  240, 0x00000000U, 0xFA6B6557U },
    {  241, 0x00000000U, 0xE5F7C54DU }, {  403, 0x00000000U, 0x6675FF5AU },
    {  512, 0x00000000U, 0xD485C30AU }, { 2048, 0x00000000U, 0x7C535464U },
    { 4160, 0x00000000U, 0xDB0D9141U },
};

// XSUM_XXH64_testdata, seed 0.
constexpr Case64 kXXH64[] = {
    {    0, 0ULL, 0xEF46DB3751D8E999ULL }, {    1, 0ULL, 0xE934A84ADB052768ULL },
    {    2, 0ULL, 0x5D48CD60A77E23FFULL }, {    3, 0ULL, 0xFF7E1959CB50794AULL },
    {    4, 0ULL, 0x9136A0DCA57457EEULL }, {    8, 0ULL, 0xCDBCF538E71D1348ULL },
    {    9, 0ULL, 0x554B1AE991EDA6B6ULL }, {   16, 0ULL, 0x98C90B57FDFCB55CULL },
    {   17, 0ULL, 0x0D39A2D051A30C2CULL }, {   64, 0ULL, 0xEF558F8ACAC2B5CDULL },
    {  128, 0ULL, 0x90CA021457D96DC5ULL }, {  129, 0ULL, 0x41C280132D697ABAULL },
    {  222, 0ULL, 0xB641AE8CB691C174ULL }, {  240, 0ULL, 0xB81838D483BAEE53ULL },
    {  241, 0ULL, 0x95D76C8B4D8FC4D6ULL }, {  403, 0ULL, 0xD99858FEE82283DFULL },
    {  512, 0ULL, 0x4358D2FDD62B58A7ULL }, { 2048, 0ULL, 0x5940F2752BC04387ULL },
    { 4160, 0ULL, 0xEEE6A4E2AC952A5EULL },
};

// XSUM_XXH3_testdata, seed 0 and seed PRIME64 — the seeded path is a different
// branch in XXH3, not a reseeding of the same one.
constexpr Case64 kXXH3[] = {
    {    0, 0ULL, 0x2D06800538D394C2ULL }, {    1, 0ULL, 0xC44BDFF4074EECDBULL },
    {    2, 0ULL, 0x7A9978044CB8A8BBULL }, {    3, 0ULL, 0x54247382A8D6B94DULL },
    {    4, 0ULL, 0xE5DC74BC51848A51ULL }, {    8, 0ULL, 0x24CCC9ACAA9F65E4ULL },
    {    9, 0ULL, 0x14D5001C15DD3F2BULL }, {   16, 0ULL, 0x981B17D36C7498C9ULL },
    {   17, 0ULL, 0x796F5ACD3A60F862ULL }, {   64, 0ULL, 0x9CB48487720EC49DULL },
    {  128, 0ULL, 0xFCFF24126754D861ULL }, {  129, 0ULL, 0x98F1B0A679A2CA29ULL },
    {  222, 0ULL, 0xB9163B558664D356ULL }, {  240, 0ULL, 0x81C3C2B67F568CCFULL },
    {  241, 0ULL, 0xC5A639ECD2030E5EULL }, {  403, 0ULL, 0xCDEB804D65C6DEA4ULL },
    {  512, 0ULL, 0x617E49599013CB6BULL }, { 2048, 0ULL, 0xDD59E2C3A5F038E0ULL },
    { 4160, 0ULL, 0x4F323B15321E94E1ULL },
};

constexpr Case64 kXXH3Seeded[] = {
    {    0, 0x9E3779B185EBCA8DULL, 0xA8A6B918B2F0364AULL },
    {    1, 0x9E3779B185EBCA8DULL, 0x032BE332DD766EF8ULL },
    {   16, 0x9E3779B185EBCA8DULL, 0x663F29333B4DB6B1ULL },
    {  129, 0x9E3779B185EBCA8DULL, 0x21FFFDBCA099C844ULL },
    {  241, 0x9E3779B185EBCA8DULL, 0xDDA9B0A161D4829AULL },
    { 4160, 0x9E3779B185EBCA8DULL, 0x1BF6F5FAF9EECABDULL },
};

// XSUM_XXH128_testdata, seed 0.
constexpr Case128 kXXH128[] = {
    {    0, 0x6001C324468D497FULL, 0x99AA06D3014798D8ULL },
    {    1, 0xC44BDFF4074EECDBULL, 0xA6CD5E9392000F6AULL },
    {   16, 0x562980258A998629ULL, 0xC68C368ECF8A9C05ULL },
    {  129, 0x86C9E3BC8F0A3B5CULL, 0x03815FC91F1B30B6ULL },
    {  241, 0xC5A639ECD2030E5EULL, 0x99A80ECF0ECFC647ULL },
    { 4160, 0x4F323B15321E94E1ULL, 0x67140711C1E3E335ULL },
};

}  // namespace

int main() {
    for (const auto& c : kXXH32) {
        const auto buf = make_sanity_buffer(c.len);
        assert(XXH32(buf.data(), c.len, c.seed) == c.expected);
    }
    for (const auto& c : kXXH64) {
        const auto buf = make_sanity_buffer(c.len);
        assert(XXH64(buf.data(), c.len, c.seed) == c.expected);
    }
    for (const auto& c : kXXH3) {
        const auto buf = make_sanity_buffer(c.len);
        assert(XXH3_64bits(buf.data(), c.len) == c.expected);
    }
    for (const auto& c : kXXH3Seeded) {
        const auto buf = make_sanity_buffer(c.len);
        assert(XXH3_64bits_withSeed(buf.data(), c.len, c.seed) == c.expected);
    }
    for (const auto& c : kXXH128) {
        const auto buf = make_sanity_buffer(c.len);
        const XXH128_hash_t h = XXH3_128bits(buf.data(), c.len);
        assert(h.low64 == c.lo && h.high64 == c.hi);
    }

    // --- streaming must agree with the one-shot form ---
    // Split at 3 bytes, which is neither the 16-byte stripe nor the 256-byte
    // block, so the internal buffering path is actually exercised.
    {
        const auto buf = make_sanity_buffer(4160);
        XXH64_state_t* st = XXH64_createState();
        assert(st != nullptr);
        assert(XXH64_reset(st, 0) == XXH_OK);
        assert(XXH64_update(st, buf.data(), 3) == XXH_OK);
        assert(XXH64_update(st, buf.data() + 3, buf.size() - 3) == XXH_OK);
        assert(XXH64_digest(st) == 0xEEE6A4E2AC952A5EULL);
        assert(XXH64_freeState(st) == XXH_OK);

        XXH3_state_t* s3 = XXH3_createState();
        assert(s3 != nullptr);
        assert(XXH3_64bits_reset(s3) == XXH_OK);
        assert(XXH3_64bits_update(s3, buf.data(), 3) == XXH_OK);
        assert(XXH3_64bits_update(s3, buf.data() + 3, buf.size() - 3) == XXH_OK);
        assert(XXH3_64bits_digest(s3) == 0x4F323B15321E94E1ULL);
        assert(XXH3_freeState(s3) == XXH_OK);
    }

    // --- the canonical (big-endian) serialization round-trips ---
    {
        const auto buf = make_sanity_buffer(512);
        const std::uint64_t h64 = XXH64(buf.data(), buf.size(), 0);
        XXH64_canonical_t c64;
        XXH64_canonicalFromHash(&c64, h64);
        assert(c64.digest[0] == static_cast<unsigned char>(h64 >> 56));  // big-endian, always
        assert(XXH64_hashFromCanonical(&c64) == h64);

        const XXH128_hash_t h128 = XXH3_128bits(buf.data(), buf.size());
        XXH128_canonical_t c128;
        XXH128_canonicalFromHash(&c128, h128);
        const XXH128_hash_t back = XXH128_hashFromCanonical(&c128);
        assert(back.low64 == h128.low64 && back.high64 == h128.high64);
    }

    // --- a single flipped bit must change the digest ---
    {
        auto buf = make_sanity_buffer(4160);
        const std::uint64_t before = XXH3_64bits(buf.data(), buf.size());
        buf[buf.size() / 2] ^= 0x01;
        assert(XXH3_64bits(buf.data(), buf.size()) != before);
    }

    return 0;
}

// Behavioral test for compat.yaml-cpp 0.8.0 -- the same checks as
// tests/examples/yaml-cpp (0.9.0) minus the float formatting 0.9.0 added.
//
// Each check reaches symbols defined in the package's own .cpp files, so a
// package that compiled nothing cannot pass by being header-only by accident:
//
//   YAML::Load, node access, conversions  -> parse.cpp, node_data.cpp, convert.cpp
//   anchors and aliases                   -> nodebuilder.cpp, singledocparser.cpp
//   YAML::LoadAll                         -> parse.cpp, parser.cpp
//   YAML::Emitter, YAML::Dump             -> emitter.cpp, emitterstate.cpp, emit.cpp
//   malformed input                       -> scanner.cpp, exceptions.cpp
//   YAML::BuildGraphOfNextDocument        -> contrib/graphbuilder*.cpp
//
// Returns non-zero on any mismatch.
#include <yaml-cpp/yaml.h>
#include <yaml-cpp/contrib/graphbuilder.h>

#include <cstdio>
#include <sstream>
#include <string>
#include <vector>

// The package builds objects, not a shared library, so every yaml-cpp
// declaration this TU sees must be plain -- not dllimport. The package
// delivers that with a shim in front of yaml-cpp/dll.h, because no descriptor
// key carries a define to a consumer's TUs. On Linux the difference is only a
// visibility attribute and everything links anyway; on the MSVC ABI it is a
// link failure. Asserting it at compile time fails everywhere the moment the
// shim stops being reached.
#ifndef YAML_CPP_STATIC_DEFINE
#  error "YAML_CPP_STATIC_DEFINE did not reach the consumer: the yaml-cpp/dll.h shim was not found first"
#endif

// Proves this member resolved 0.8.0 and not the newest version: the header
// 0.9.0 added must not exist here.
#if __has_include(<yaml-cpp/fptostring.h>)
#  error "yaml-cpp/fptostring.h is present: this member did not resolve compat.yaml-cpp 0.8.0"
#endif

namespace {

const char *const kDoc = R"(
name: mcpp-index
version: 3
ratio: 0.25
enabled: true
tags: [yaml, cpp, "quoted, with comma"]
base: &base
  host: localhost
  port: 8080
derived:
  <<: *base
  alias_of_base: *base
text: |
  line one
  line two
)";

bool loads_and_converts() {
    YAML::Node root = YAML::Load(kDoc);
    if (!root.IsMap()) return false;
    if (root["name"].as<std::string>() != "mcpp-index") return false;
    if (root["version"].as<int>() != 3) return false;
    if (root["ratio"].as<double>() != 0.25) return false;
    if (!root["enabled"].as<bool>()) return false;

    const YAML::Node tags = root["tags"];
    if (!tags.IsSequence() || tags.size() != 3) return false;
    if (tags[2].as<std::string>() != "quoted, with comma") return false;
    if (tags.as<std::vector<std::string>>().front() != "yaml") return false;

    if (root["text"].as<std::string>() != "line one\nline two\n") return false;

    // A missing key is reported as undefined and a fallback applies; an
    // explicit conversion of the wrong kind throws.
    if (root["absent"].IsDefined()) return false;
    if (root["absent"].as<int>(42) != 42) return false;
    try {
        (void)root["name"].as<int>();
        return false;
    } catch (const YAML::BadConversion &) {
    }
    return true;
}

bool resolves_aliases() {
    YAML::Node root = YAML::Load(kDoc);
    const YAML::Node alias = root["derived"]["alias_of_base"];
    if (alias["port"].as<int>() != 8080) return false;
    // An alias is the SAME node as its anchor, not a copy of it.
    return alias.is(root["base"]);
}

bool loads_every_document() {
    const std::vector<YAML::Node> docs = YAML::LoadAll("a: 1\n---\nb: 2\n---\n- 3\n");
    return docs.size() == 3 && docs[0]["a"].as<int>() == 1
           && docs[1]["b"].as<int>() == 2 && docs[2][0].as<int>() == 3;
}

bool emits_and_round_trips() {
    YAML::Emitter out;
    out << YAML::BeginMap;
    out << YAML::Key << "list" << YAML::Value << YAML::Flow
        << YAML::BeginSeq << 1 << 2 << 3 << YAML::EndSeq;
    out << YAML::Key << "nested" << YAML::Value << YAML::BeginMap
        << YAML::Key << "k" << YAML::Value << "v" << YAML::EndMap;
    out << YAML::EndMap;
    if (!out.good()) return false;
    if (std::string(out.c_str()) != "list: [1, 2, 3]\nnested:\n  k: v") return false;

    YAML::Node again = YAML::Load(out.c_str());
    if (again["list"][2].as<int>() != 3) return false;

    // A node built in code and dumped comes back with the same content.
    YAML::Node built;
    built["x"] = 7;
    built["y"].push_back("first");
    built["y"].push_back("second");
    YAML::Node back = YAML::Load(YAML::Dump(built));
    return back["x"].as<int>() == 7 && back["y"].size() == 2
           && back["y"][1].as<std::string>() == "second";
}

bool rejects_malformed_input() {
    try {
        (void)YAML::Load("key: [unterminated\nother: 1\n");
    } catch (const YAML::ParserException &e) {
        // The mark points into the document rather than being left unset.
        return e.mark.line >= 0 && !std::string(e.what()).empty();
    }
    return false;
}

}  // namespace

// Upstream declares GraphBuilderInterface's destructor pure virtual and
// defines it nowhere (0.8.0 and 0.9.0 alike), so every class derived from it
// -- upstream's own GraphBuilder<Impl> included -- needs the definition from
// its user. This is that definition, as any consumer of the contrib API must
// write it. BuildGraphOfNextDocument below still comes only from
// src/contrib/graphbuilder.cpp, so the check still proves contrib was built.
YAML::GraphBuilderInterface::~GraphBuilderInterface() = default;

namespace {

// Counts what the contrib GraphBuilder is told, which only the two
// src/contrib/*.cpp translation units implement.
struct Counter : YAML::GraphBuilderInterface {
    int scalars = 0, sequences = 0, maps = 0;
    void *NewNull(const YAML::Mark &, void *) override { return this; }
    void *NewScalar(const YAML::Mark &, const std::string &, void *,
                    const std::string &) override {
        ++scalars;
        return this;
    }
    void *NewSequence(const YAML::Mark &, const std::string &, void *) override {
        ++sequences;
        return this;
    }
    void AppendToSequence(void *, void *) override {}
    void SequenceComplete(void *) override {}
    void *NewMap(const YAML::Mark &, const std::string &, void *) override {
        ++maps;
        return this;
    }
    void AssignInMap(void *, void *, void *) override {}
    void MapComplete(void *) override {}
    void *AnchorReference(const YAML::Mark &, void *node) override { return node; }
};

bool builds_a_graph() {
    std::istringstream in("a: [1, 2]\nb: {c: 3}\n");
    YAML::Parser parser(in);
    Counter counter;
    if (YAML::BuildGraphOfNextDocument(parser, counter) == nullptr) return false;
    // keys a, b, c and values 1, 2, 3
    return counter.scalars == 6 && counter.sequences == 1 && counter.maps == 2;
}

}  // namespace

int main() {
    struct Check {
        const char *name;
        bool (*run)();
    } checks[] = {
        {"loads_and_converts", loads_and_converts},
        {"resolves_aliases", resolves_aliases},
        {"loads_every_document", loads_every_document},
        {"emits_and_round_trips", emits_and_round_trips},
        {"rejects_malformed_input", rejects_malformed_input},
        {"builds_a_graph", builds_a_graph},
    };
    bool ok = true;
    for (const Check &c : checks) {
        const bool passed = c.run();
        std::printf("%s %s\n", passed ? "ok  " : "FAIL", c.name);
        ok = ok && passed;
    }
    return ok ? 0 : 1;
}

// Behavioral test for compat.yaml-cpp 0.9.0.
//
// Each check reaches symbols defined in the package's own .cpp files, so a
// package that compiled nothing cannot pass by being header-only by accident:
//
//   YAML::Load, node access, conversions  -> parse.cpp, node_data.cpp, convert.cpp
//   anchors and aliases                   -> nodebuilder.cpp, singledocparser.cpp
//   YAML::LoadAll                         -> parse.cpp, parser.cpp
//   YAML::Emitter, YAML::Dump             -> emitter.cpp, emitterstate.cpp, emit.cpp
//   malformed input                       -> scanner.cpp, exceptions.cpp
//   YAML::BuildGraphOfNextDocument        -> contrib/graphbuilder*.cpp
//   YAML::FpToString                      -> fptostring.cpp (new in 0.9.0)
//
// Returns non-zero on any mismatch.
#include <yaml-cpp/yaml.h>
#include <yaml-cpp/contrib/graphbuilder.h>
#include <yaml-cpp/fptostring.h>

#include <cstdio>
#include <sstream>
#include <string>
#include <vector>

// The package builds objects, not a shared library, so every yaml-cpp
// declaration this TU sees must be plain -- not dllimport. The package
// delivers that with a shim in front of yaml-cpp/dll.h, because no descriptor
// key carries a define to a consumer's TUs. On Linux the difference is only a
// visibility attribute and everything links anyway; on the MSVC ABI it is a
// link failure. Asserting it at compile time fails everywhere the moment the
// shim stops being reached.
#ifndef YAML_CPP_STATIC_DEFINE
#  error "YAML_CPP_STATIC_DEFINE did not reach the consumer: the yaml-cpp/dll.h shim was not found first"
#endif

namespace {

const char *const kDoc = R"(
name: mcpp-index
version: 3
ratio: 0.25
enabled: true
tags: [yaml, cpp, "quoted, with comma"]
base: &base
  host: localhost
  port: 8080
derived:
  <<: *base
  alias_of_base: *base
text: |
  line one
  line two
)";

bool loads_and_converts() {
    YAML::Node root = YAML::Load(kDoc);
    if (!root.IsMap()) return false;
    if (root["name"].as<std::string>() != "mcpp-index") return false;
    if (root["version"].as<int>() != 3) return false;
    if (root["ratio"].as<double>() != 0.25) return false;
    if (!root["enabled"].as<bool>()) return false;

    const YAML::Node tags = root["tags"];
    if (!tags.IsSequence() || tags.size() != 3) return false;
    if (tags[2].as<std::string>() != "quoted, with comma") return false;
    if (tags.as<std::vector<std::string>>().front() != "yaml") return false;

    if (root["text"].as<std::string>() != "line one\nline two\n") return false;

    // A missing key is reported as undefined and a fallback applies; an
    // explicit conversion of the wrong kind throws.
    if (root["absent"].IsDefined()) return false;
    if (root["absent"].as<int>(42) != 42) return false;
    try {
        (void)root["name"].as<int>();
        return false;
    } catch (const YAML::BadConversion &) {
    }
    return true;
}

bool resolves_aliases() {
    YAML::Node root = YAML::Load(kDoc);
    const YAML::Node alias = root["derived"]["alias_of_base"];
    if (alias["port"].as<int>() != 8080) return false;
    // An alias is the SAME node as its anchor, not a copy of it.
    return alias.is(root["base"]);
}

bool loads_every_document() {
    const std::vector<YAML::Node> docs = YAML::LoadAll("a: 1\n---\nb: 2\n---\n- 3\n");
    return docs.size() == 3 && docs[0]["a"].as<int>() == 1
           && docs[1]["b"].as<int>() == 2 && docs[2][0].as<int>() == 3;
}

bool emits_and_round_trips() {
    YAML::Emitter out;
    out << YAML::BeginMap;
    out << YAML::Key << "list" << YAML::Value << YAML::Flow
        << YAML::BeginSeq << 1 << 2 << 3 << YAML::EndSeq;
    out << YAML::Key << "nested" << YAML::Value << YAML::BeginMap
        << YAML::Key << "k" << YAML::Value << "v" << YAML::EndMap;
    out << YAML::EndMap;
    if (!out.good()) return false;
    if (std::string(out.c_str()) != "list: [1, 2, 3]\nnested:\n  k: v") return false;

    YAML::Node again = YAML::Load(out.c_str());
    if (again["list"][2].as<int>() != 3) return false;

    // A node built in code and dumped comes back with the same content.
    YAML::Node built;
    built["x"] = 7;
    built["y"].push_back("first");
    built["y"].push_back("second");
    YAML::Node back = YAML::Load(YAML::Dump(built));
    return back["x"].as<int>() == 7 && back["y"].size() == 2
           && back["y"][1].as<std::string>() == "second";
}

bool rejects_malformed_input() {
    try {
        (void)YAML::Load("key: [unterminated\nother: 1\n");
    } catch (const YAML::ParserException &e) {
        // The mark points into the document rather than being left unset.
        return e.mark.line >= 0 && !std::string(e.what()).empty();
    }
    return false;
}

}  // namespace

// Upstream declares GraphBuilderInterface's destructor pure virtual and
// defines it nowhere (0.8.0 and 0.9.0 alike), so every class derived from it
// -- upstream's own GraphBuilder<Impl> included -- needs the definition from
// its user. This is that definition, as any consumer of the contrib API must
// write it. BuildGraphOfNextDocument below still comes only from
// src/contrib/graphbuilder.cpp, so the check still proves contrib was built.
YAML::GraphBuilderInterface::~GraphBuilderInterface() = default;

namespace {

// Counts what the contrib GraphBuilder is told, which only the two
// src/contrib/*.cpp translation units implement.
struct Counter : YAML::GraphBuilderInterface {
    int scalars = 0, sequences = 0, maps = 0;
    void *NewNull(const YAML::Mark &, void *) override { return this; }
    void *NewScalar(const YAML::Mark &, const std::string &, void *,
                    const std::string &) override {
        ++scalars;
        return this;
    }
    void *NewSequence(const YAML::Mark &, const std::string &, void *) override {
        ++sequences;
        return this;
    }
    void AppendToSequence(void *, void *) override {}
    void SequenceComplete(void *) override {}
    void *NewMap(const YAML::Mark &, const std::string &, void *) override {
        ++maps;
        return this;
    }
    void AssignInMap(void *, void *, void *) override {}
    void MapComplete(void *) override {}
    void *AnchorReference(const YAML::Mark &, void *node) override { return node; }
};

bool builds_a_graph() {
    std::istringstream in("a: [1, 2]\nb: {c: 3}\n");
    YAML::Parser parser(in);
    Counter counter;
    if (YAML::BuildGraphOfNextDocument(parser, counter) == nullptr) return false;
    // keys a, b, c and values 1, 2, 3
    return counter.scalars == 6 && counter.sequences == 1 && counter.maps == 2;
}

// 0.9.0 formats floating point by the shortest representation that reads
// back to the same value; 0.8.0 printed max_digits10 digits
// ("0.10000000000000001"). The emitter uses the same routine.
bool formats_floats_shortest() {
    if (YAML::FpToString(0.1) != "0.1") return false;
    if (YAML::FpToString(1.5f) != "1.5") return false;
    YAML::Emitter out;
    out << 0.1;
    return std::string(out.c_str()) == "0.1";
}

}  // namespace

int main() {
    struct Check {
        const char *name;
        bool (*run)();
    } checks[] = {
        {"loads_and_converts", loads_and_converts},
        {"resolves_aliases", resolves_aliases},
        {"loads_every_document", loads_every_document},
        {"emits_and_round_trips", emits_and_round_trips},
        {"rejects_malformed_input", rejects_malformed_input},
        {"builds_a_graph", builds_a_graph},
        {"formats_floats_shortest", formats_floats_shortest},
    };
    bool ok = true;
    for (const Check &c : checks) {
        const bool passed = c.run();
        std::printf("%s %s\n", passed ? "ok  " : "FAIL", c.name);
        ok = ok && passed;
    }
    return ok ? 0 : 1;
}

// Smoke test — verify compat.yyjson builds, links, and works
#include "yyjson.h"
import std;

int main() {
    const char* json = R"({"name":"mcpp","version":"0.12.0"})";
    yyjson_doc* doc = yyjson_read(json, strlen(json), 0);
    if (!doc) return 1;
    auto* root = yyjson_doc_get_root(doc);
    auto* name = yyjson_obj_get(root, "name");
    if (!name || std::string_view{yyjson_get_str(name)} != "mcpp") return 2;
    std::println("compat.yyjson smoke test: ok");
    yyjson_doc_free(doc);
    return 0;
}

// compat.zlib: behaviour, and agreement between the library and its consumer.
#include <zlib.h>

#include <cstdio>
#include <cstring>
#include <string>

namespace {

int failures = 0;

void check(bool held, const char* what) {
    if (!held) { std::printf("FAIL: %s\n", what); ++failures; }
}

// zlibCompileFlags() bits 6 and 7 state the size of z_off_t the library was
// compiled with: 0 is 2 bytes, 1 is 4, 2 is 8, 3 is another size.
unsigned long library_off_t_size() {
    switch ((zlibCompileFlags() >> 6) & 3u) {
        case 0: return 2;
        case 1: return 4;
        case 2: return 8;
        default: return 0;
    }
}

}  // namespace

int main() {
    check(library_off_t_size() == sizeof(z_off_t),
          "the library and this consumer agree on the width of z_off_t");

    const std::string text(4096, 'z');
    uLongf bound = compressBound(static_cast<uLong>(text.size()));
    std::string packed(bound, '\0');
    check(compress(reinterpret_cast<Bytef*>(packed.data()), &bound,
                   reinterpret_cast<const Bytef*>(text.data()),
                   static_cast<uLong>(text.size())) == Z_OK,
          "a buffer is compressed");
    std::string unpacked(text.size(), '\0');
    uLongf size = static_cast<uLongf>(unpacked.size());
    check(uncompress(reinterpret_cast<Bytef*>(unpacked.data()), &size,
                     reinterpret_cast<const Bytef*>(packed.data()), bound) == Z_OK
              && size == text.size() && unpacked == text,
          "and decompresses to what it was");

    const char* name = "zlib-test.gz";
    gzFile out = gzopen(name, "wb");
    check(out != nullptr, "a gz file is opened for writing");
    if (out) {
        check(gzwrite(out, text.data(), static_cast<unsigned>(text.size()))
                  == static_cast<int>(text.size()), "the gz file is written");
        gzclose(out);
    }
    gzFile in = gzopen(name, "rb");
    check(in != nullptr, "the gz file is opened for reading");
    if (in) {
        std::string back(text.size(), '\0');
        check(gzread(in, back.data(), static_cast<unsigned>(back.size()))
                  == static_cast<int>(text.size()) && back == text,
              "and reads back what was written");
        check(gzseek(in, 10, SEEK_SET) == 10 && gztell(in) == 10,
              "a gz file seeks and reports its offset through z_off_t");
        gzclose(in);
    }
    std::remove(name);

    if (failures == 0) std::printf("compat.zlib: every observation held\n");
    return failures == 0 ? 0 : 1;
}
